window.SikhifyData.gurbani = {"banis":[{"id":"japji-sahib","name":"Japji Sahib","gurmukhiName":"ਜਪੁਜੀ ਸਾਹਿਬ","author":"Guru Nanak Dev Ji","source":"Sri Guru Granth Sahib Ji","ang":"1–8","time":"morning","audio":{"url":"https://archive.org/download/Kirtan-Teg-Singh_Nitnem/01%20-%20Kirtan%20Teg%20Singh%20-%20Japji%20Sahib.mp3","duration":"44:11","by":"Kirtan Teg Singh","license":"CC BY-NC-ND 4.0","source":"https://archive.org/details/Kirtan-Teg-Singh_Nitnem"},"youtube":"SC1gipmk214","context":"Recited first, in the early hours of the morning (Amrit Vela).","type":"Bani","nitnem":true,"baniDbId":2,"lineCount":385,"opening":[{"g":"ਆਦਿ ਸਚੁ ਜੁਗਾਦਿ ਸਚੁ ॥","t":"aadh sach jugaadh sach ||","pa":"ਹੇ ਨਾਨਕ ! ਅਕਾਲ ਪੁਰਖ ਮੁੱਢ ਤੋਂ ਹੋਂਦ ਵਾਲਾ ਹੈ, ਜੁਗਾਂ ਦੇ ਮੁੱਢ ਤੋਂ ਮੌਜੂਦ ਹੈ ।","hi":"अकाल पुरख आरम्भ से ही अस्तित्व वाला है~ युगों के आरम्भ से मौजूद है।","en":"True In The Primal Beginning. True Throughout The Ages.","p":3},{"g":"ਹੈ ਭੀ ਸਚੁ ਨਾਨਕ ਹੋਸੀ ਭੀ ਸਚੁ ॥੧॥","t":"hai bhee sach naanak hosee bhee sach ||1||","pa":"ਇਸ ਵੇਲੇ ਭੀ ਮੌਜੂਦ ਹੈ ਤੇ ਅਗਾਂਹ ਨੂੰ ਭੀ ਹੋਂਦ ਵਾਲਾ ਰਹੇਗਾ ।੧।","hi":"हे नानक! इस समय भी मौजूद है और आगे भी अस्तित्व में रहेगा।१।","en":"True Here And Now. O Nanak, Forever And Ever True. ||1||","p":3}]},{"id":"jaap-sahib","name":"Jaap Sahib","gurmukhiName":"ਜਾਪੁ ਸਾਹਿਬ","author":"Guru Gobind Singh Ji","source":"Dasam Granth","time":"morning","audio":{"url":"https://archive.org/download/Kirtan-Teg-Singh_Nitnem/02%20-%20Kirtan%20Teg%20Singh%20-%20Jaap%20Sahib.mp3","duration":"47:26","by":"Kirtan Teg Singh","license":"CC BY-NC-ND 4.0","source":"https://archive.org/details/Kirtan-Teg-Singh_Nitnem"},"youtube":"V0yK9gjb-uA","context":"Recited in the morning after Japji Sahib.","type":"Bani","nitnem":true,"baniDbId":4,"lineCount":808,"opening":[{"g":"ਚੱਕ੍ਰ ਚਿਹਨ ਅਰੁ ਬਰਨ ਜਾਤਿ ਅਰੁ ਪਾਤਿ ਨਹਿਨ ਜਿਹ ॥","t":"cha'kr chihan ar baran jaat ar paat nahin jeh ||","pa":"ਜਿਸ ਦਾ ਕੋਈ ਚਿੰਨ੍ਹ, ਚਕ੍ਰ, ਵਰਨ, ਜਾਤਿ ਅਤੇ ਗੋਤ ਨਹੀਂ ਹੈ,","hi":"","en":"He who is without mark or sign, He who is without caste or line.","p":6},{"g":"ਰੂਪ ਰੰਗ ਅਰੁ ਰੇਖ ਭੇਖ ਕੋਊ ਕਹਿ ਨ ਸਕਤਿ ਕਿਹ ॥","t":"roop ra(n)g ar rekh bhekh kouoo keh na sakat keh ||","pa":"ਅਤੇ ਜਿਸ ਦੇ ਰੂਪ, ਰੰਗ, ਰੇਖ, ਭੇਖ ਬਾਰੇ ਕੋਈ ਕੁਝ ਨਹੀਂ ਕਹਿ ਸਕਦਾ (ਕਿ ਉਹ) ਕਿਹੋ ਜਿਹਾ ਹੈ।","hi":"","en":"He who is without colour or form, and without any distinctive norm.","p":6}]},{"id":"tav-prasad-savaiye","name":"Tav-Prasad Savaiye","gurmukhiName":"ਤ੍ਵ ਪ੍ਰਸਾਦਿ ਸਵੱਯੇ","author":"Guru Gobind Singh Ji","source":"Dasam Granth","time":"morning","audio":null,"youtube":"YPPSuG2Kxt8","context":"The ten Savaiye beginning “Sravag sudh”, recited in the morning.","type":"Bani","nitnem":true,"baniDbId":6,"lineCount":43,"opening":[{"g":"ਸ੍ਰਾਵਗ ਸੁੱਧ ਸਮੂਹ ਸਿਧਾਨ ਕੇ ਦੇਖਿ ਫਿਰਿਓ ਘਰ ਜੋਗ ਜਤੀ ਕੇ ॥","t":"sraavag su'dh samooh sidhaan ke dhekh firio ghar jog jatee ke ||","pa":"(ਹੇ ਪ੍ਰਭੂ! ਮੈਂ) ਬੁੱਧ ਅਤੇ ਜੈਨ ਮਤ ਨੂੰ ਮੰਨਣ ਵਾਲੇ ਸ਼੍ਰਾਵਕਾ, ਕਰਮਕਾਡੀਆਂ, ਸਿੱਧਾ, ਜੋਗੀਆਂ ਅਤੇ ਜਤੀਆਂ ਦੇ ਸਿੱਧਾਤਿਕ ਵਿਚਾਰਾ (ਘਰਾ) ਨੂੰ ਘੋਖ ਲਿਆ ਹੈ;","hi":"","en":"I have seen during my tours pure Sravaks (Jaina and Buddhist monks), group of adepts and abodes of ascetics and Yogi.","p":4},{"g":"ਸੂਰ ਸੁਰਾਰਦਨ ਸੁੱਧ ਸੁਧਾਦਿਕ ਸੰਤ ਸਮੂਹ ਅਨੇਕ ਮਤੀ ਕੇ ॥","t":"soor suraaradhan su'dh sudhaadhik sa(n)t samooh anek matee ke ||","pa":"ਸ਼ੂਰਵੀਰਾ, (ਦੇਵਤਿਆਂ ਦੇ ਵੈਰੀ) ਦੈਂਤਾ ਅਤੇ ਸ਼ੁੱਧ ਅੰਮ੍ਰਿਤ (ਸੁਧਾ) ਪਾਨ ਕਰਨ ਵਾਲੇ ਦੇਵਤਿਆਂ ਅਤੇ ਅਨੇਕ ਪ੍ਰਕਾਰ ਦੇ ਸੰਤਾ ਦੀਆਂ ਮੰਡਲੀਆਂ ਨੂੰ (ਤੁਰ ਫਿਰ ਕੇ ਵੇਖ ਲਿਆ ਹੈ);","hi":"","en":"Valiant heroes, demons killing gods, gods drinking nectar and assemblies of saints of various sects.","p":4}]},{"id":"benti-chaupai","name":"Benti Chaupai","gurmukhiName":"ਬੇਨਤੀ ਚੌਪਈ ਸਾਹਿਬ","author":"Guru Gobind Singh Ji","source":"Dasam Granth","time":"morning","audio":null,"youtube":"21Zth-_kn-w","context":"A prayer for protection, recited in the morning and within Rehras Sahib.","type":"Bani","nitnem":true,"baniDbId":9,"lineCount":104,"opening":[{"g":"ਹਮਰੀ ਕਰੋ ਹਾਥ ਦੈ ਰੱਛਾ ॥","t":"hamaree karo haath dhai ra'chhaa ||","pa":"(ਹੇ ਪਰਮ ਸੱਤਾ!) ਆਪਣਾ ਹੱਥ ਦੇ ਕੇ ਮੇਰੀ ਰਖਿਆ ਕਰੋ।","hi":"","en":"Protect me O Lord! with Thine own Hands","p":17},{"g":"ਪੂਰਨ ਹੋਇ ਚਿਤ ਕੀ ਇੱਛਾ ॥","t":"pooran hoi chit kee i'chhaa ||","pa":"(ਤਾ ਜੋ) ਮੇਰੇ ਚਿਤ ਦੀ ਇੱਛਾ ਪੂਰੀ ਹੋ ਜਾਏ।","hi":"","en":"all the desires of my heart be fulfilled.","p":17}]},{"id":"anand-sahib","name":"Anand Sahib","gurmukhiName":"ਅਨੰਦੁ ਸਾਹਿਬ","author":"Guru Amar Das Ji","source":"Sri Guru Granth Sahib Ji","ang":"917–922","raag":"Raag Ramkali","time":"morning","audio":{"url":"https://archive.org/download/Kirtan-Teg-Singh_Nitnem/03%20-%20Kirtan%20Teg%20Singh%20-%20Anand%20Sahib.mp3","duration":"28:55","by":"Kirtan Teg Singh","license":"CC BY-NC-ND 4.0","source":"https://archive.org/details/Kirtan-Teg-Singh_Nitnem"},"youtube":"vc3QMm8cDSo","context":"Recited in the morning; the first five and last Pauri close every Sikh service.","type":"Bani","nitnem":true,"baniDbId":10,"lineCount":211,"opening":[{"g":"ਅਨੰਦੁ ਭਇਆ ਮੇਰੀ ਮਾਏ ਸਤਿਗੁਰੂ ਮੈ ਪਾਇਆ ॥","t":"ana(n)dh bhiaa meree maae satiguroo mai paiaa ||","pa":"ਹੇ ਭਾਈ ਮਾਂ! (ਮੇਰੇ ਅੰਦਰ) ਪੂਰਨ ਖਿੜਾਉ ਪੈਦਾ ਹੋ ਗਿਆ ਹੈ (ਕਿਉਂਕਿ) ਮੈਨੂੰ ਗੁਰੂ ਮਿਲ ਪਿਆ ਹੈ ।","hi":"हे भाई माँ ! (मेरे अंदर) पूर्ण खिड़ाव (आनंद) पैदा हो गया है (क्योंकि) मुझे गुरू मिल गया है।","en":"I am in ecstasy, O my mother, for I have found my True Guru.","p":4},{"g":"ਸਤਿਗੁਰੁ ਤ ਪਾਇਆ ਸਹਜ ਸੇਤੀ ਮਨਿ ਵਜੀਆ ਵਾਧਾਈਆ ॥","t":"satigur ta paiaa sahaj setee man vajeeaa vaadhaieeaa ||","pa":"ਮੈਨੂੰ ਗੁਰੂ ਮਿਲਿਆ ਹੈ, ਤੇ ਨਾਲ ਹੀ ਅਡੋਲ ਅਵਸਥਾ ਭੀ ਪ੍ਰਾਪਤ ਹੋ ਗਈ ਹੈ (ਭਾਵ, ਗੁਰੂ ਦੇ ਮਿਲਣ ਨਾਲ ਮੇਰਾ ਮਨ ਡੋਲਣੋਂ ਹਟ ਗਿਆ ਹੈ); ਮੇਰੇ ਮਨ ਵਿਚ (ਮਾਨੋ) ਖ਼ੁਸ਼ੀ ਦੇ ਵਾਜੇ ਵੱਜ ਪਏ ਹਨ,","hi":"मुझे गुरू मिला है। और साथ ही अडोल अवस्था भी प्राप्त हो गई है (भाव। गुरू के मिलने से मेरा मन डोलने से हट गया है); मेरे मन में (मानो) खुशी के बाजे बज उठे हें।","en":"I have found the True Guru, with intuitive ease, and my mind vibrates with the music of bliss.","p":4}]},{"id":"rehras-sahib","name":"Rehras Sahib","gurmukhiName":"ਰਹਰਾਸਿ ਸਾਹਿਬ","author":"Several Gurus","source":"Sri Guru Granth Sahib Ji & Dasam Granth","ang":"8–12","time":"evening","audio":null,"youtube":"dy1bAclA25k","context":"The evening prayer, recited at sunset after the day's work.","type":"Bani","nitnem":true,"baniDbId":21,"lineCount":309,"opening":[{"g":"ਸੋ ਦਰੁ ਤੇਰਾ ਕੇਹਾ ਸੋ ਘਰੁ ਕੇਹਾ ਜਿਤੁ ਬਹਿ ਸਰਬ ਸਮਾਲੇ ॥","t":"so dhar teraa kehaa so ghar kehaa jit beh sarab samaale ||","pa":"(ਹੇ ਪ੍ਰਭੂ !) ਤੇਰਾ ਉਹ ਘਰ ਅਤੇ (ਉਸ ਘਰ ਦਾ) ਉਹ ਦਰਵਾਜ਼ਾ ਬੜਾ ਹੀ ਅਸਚਰਜ ਹੋਵੇਗਾ, ਜਿੱਥੇ ਬੈਠ ਕੇ ਤੂੰ ਸਾਰੇ ਜੀਵਾਂ ਦੀ ਸੰਭਾਲ ਕਰ ਰਿਹਾ ਹੈਂ ।","hi":"(हे प्रभू!) तेरा वह घर और (उस घर का) वह दरवाजा बड़ा ही आश्चर्य भरा है जहाँ बैठ के तू सारे जीवों की संभाल कर रहा है।","en":"Where is That Door of Yours, and where is That Home, in which You sit and take care of all?","p":13},{"g":"ਵਾਜੇ ਤੇਰੇ ਨਾਦ ਅਨੇਕ ਅਸੰਖਾ ਕੇਤੇ ਤੇਰੇ ਵਾਵਣਹਾਰੇ ॥","t":"vaaje tere naadh anek asa(n)khaa kete tere vaavanahaare ||","pa":"(ਤੇਰੀ ਇਸ ਰਚੀ ਹੋਈ ਕੁਦਰਤ ਵਿਚ) ਅਨੇਕਾਂ ਤੇ ਅਣਗਿਣਤ ਵਾਜੇ ਤੇ ਰਾਗ ਹਨ; ਬੇਅੰਤ ਹੀ ਜੀਵ (ਉਹਨਾਂ ਵਾਜਿਆਂ ਨੂੰ) ਵਜਾਣ ਵਾਲੇ ਹਨ ।","hi":"(तेरी इस रची हुई कुदरत में) अनेकों और अनगिनत वाजे (संगीत-यंत्र) और राग हैं; बेअंत ही जीव (इन बाजों को) बजाने वाले हैं ।","en":"The Sound-current of the Naad vibrates there for You, and countless musicians play all sorts of instruments there for You.","p":13}]},{"id":"sohila-sahib","name":"Sohila Sahib","gurmukhiName":"ਸੋਹਿਲਾ ਸਾਹਿਬ","author":"Guru Nanak Dev Ji, Guru Ram Das Ji & Guru Arjan Dev Ji","source":"Sri Guru Granth Sahib Ji","ang":"12–13","time":"night","audio":{"url":"https://archive.org/download/Kirtan-Teg-Singh_Nitnem/04%20-%20Kirtan%20Teg%20Singh%20-%20Kirtan%20Sohila.mp3","duration":"15:10","by":"Kirtan Teg Singh","license":"CC BY-NC-ND 4.0","source":"https://archive.org/details/Kirtan-Teg-Singh_Nitnem"},"youtube":"jkwTfDew37g","context":"Recited at night before sleeping, and at the close of the Antim Sanskar.","type":"Bani","nitnem":true,"baniDbId":23,"lineCount":55,"opening":[{"g":"ਜੈ ਘਰਿ ਕੀਰਤਿ ਆਖੀਐ ਕਰਤੇ ਕਾ ਹੋਇ ਬੀਚਾਰੋ ॥","t":"jai ghar keerat aakheeaai karate kaa hoi beechaaro ||","pa":"ਜਿਸ (ਸਤਸੰਗ-) ਘਰ ਵਿਚ (ਪਰਮਾਤਮਾ ਦੀ) ਸਿਫ਼ਤਿ-ਸਾਲਾਹ ਕੀਤੀ ਜਾਂਦੀ ਹੈ ਅਤੇ ਕਰਤਾਰ ਦੇ ਗੁਣਾਂ ਦੀ ਵਿਚਾਰ ਹੁੰਦੀ ਹੈ (ਹੇ ਜਿੰਦ-ਕੁੜੀਏ !)","hi":"जिस (सत्संग) घर में (परमात्मा की) सिफत-सलाह की जाती है और करतार के गुणों की विचार होती है","en":"In that house where the Praises of the Creator are chanted and contemplated","p":19},{"g":"ਤਿਤੁ ਘਰਿ ਗਾਵਹੁ ਸੋਹਿਲਾ ਸਿਵਰਿਹੁ ਸਿਰਜਣਹਾਰੋ ॥੧॥","t":"tit ghar gaavahu sohilaa sivarih sirajanahaaro ||1||","pa":"ਉਸ (ਸਤਸੰਗ-) ਘਰ ਵਿਚ (ਜਾ ਕੇ ਤੂੰ ਭੀ) ਪ੍ਰਭੂ ਦੀ ਸਿਫ਼ਤਿ-ਸਾਲਾਹ ਦੇ ਗੀਤ (ਸੁਹਾਗ-ਮਿਲਾਪ ਦੀ ਤਾਂਘ ਦੇ ਸ਼ਬਦ) ਗਾਇਆ ਕਰ ਅਤੇ ਆਪਣੇ ਪੈਦਾ ਕਰਨ ਵਾਲੇ ਪ੍ਰਭੂ ਨੂੰ ਯਾਦ ਕਰਿਆ ਕਰ ।੧।","hi":"(हे शरीर-कन्या!) उस (सत्संग) घर में (जा के तू भी) प्रभू के सिफत-सलाह के गीत (सुहाग-मिलाप के उल्लास के शबद) गाया कर और अपने पैदा करने वाले प्रभू को याद करा कर।1।","en":"-in that house, sing Songs of Praise; meditate and remember the Creator Lord. ||1||","p":19}]},{"id":"sukhmani-sahib","name":"Sukhmani Sahib","gurmukhiName":"ਸੁਖਮਨੀ ਸਾਹਿਬ","author":"Guru Arjan Dev Ji","ang":"262–296","raag":"Raag Gauri","source":"Sri Guru Granth Sahib Ji","type":"Bani","nitnem":false,"baniDbId":31,"lineCount":2019,"opening":[{"g":"ਸੁਖਮਨੀ ਸੁਖ ਅੰਮ੍ਰਿਤ ਪ੍ਰਭ ਨਾਮੁ ॥","t":"sukhamanee sukh a(n)mirat prabh naam ||","pa":"ਪ੍ਰਭੂ ਦਾ ਅਮਰ ਕਰਨ ਵਾਲਾ ਤੇ ਸੁਖਦਾਈ ਨਾਮ (ਸਭ) ਸੁਖਾਂ ਦੀ ਮਣੀ ਹੈ,","hi":"प्रभू का अमर करने वाला व सुखदाई नाम (सब) सुखों की मणी है।","en":"Sukhmani: Peace of Mind, the Nectar of the Name of God."},{"g":"ਭਗਤ ਜਨਾ ਕੈ ਮਨਿ ਬਿਸ੍ਰਾਮ ॥ ਰਹਾਉ ॥","t":"bhagat janaa kai man bisraam || rahaau ||","pa":"ਇਸ ਦਾ ਟਿਕਾਣਾ ਭਗਤਾਂ ਦੇ ਹਿਰਦੇ ਵਿਚ ਹੈ ।","hi":"इसका ठिकाना भक्तों के हृदय में है।","en":"The minds of the devotees abide in a joyful peace. ||Pause||"}],"audio":null,"youtube":"lBxtI0ifpoQ"},{"id":"asa-di-vaar","name":"Asa Di Vaar","gurmukhiName":"ਆਸਾ ਦੀ ਵਾਰ","author":"Guru Nanak Dev Ji","ang":"448–475","raag":"Raag Asa","source":"Sri Guru Granth Sahib Ji","type":"Bani","nitnem":false,"baniDbId":90,"lineCount":758,"opening":[{"g":"ਬਲਿਹਾਰੀ ਗੁਰ ਆਪਣੇ ਦਿਉਹਾੜੀ ਸਦ ਵਾਰ ॥","t":"balihaaree gur aapane dhiauhaaRee sadh vaar ||","pa":"ਮੈਂ ਆਪਣੇ ਗੁਰੂ ਤੋਂ (ਇਕ) ਦਿਨ ਵਿਚ ਸੌ ਵਾਰੀ ਸਦਕੇ ਹੁੰਦਾ ਹਾਂ,","hi":"","en":"A hundred times a day, I am a sacrifice to my Guru;"},{"g":"ਜਿਨਿ ਮਾਣਸ ਤੇ ਦੇਵਤੇ ਕੀਏ ਕਰਤ ਨ ਲਾਗੀ ਵਾਰ ॥੧॥","t":"jin maanas te dhevate ke'ee karat na laagee vaar ||1||","pa":"ਜਿਸ (ਗੁਰੂ) ਨੇ ਮਨੁੱਖਾਂ ਤੋਂ ਦੇਵਤੇ ਬਣਾ ਦਿੱਤੇ ਤੇ ਬਣਾਉਂਦਿਆਂ (ਰਤਾ) ਚਿਰ ਨਾਹ ਲੱਗਾ ।੧।","hi":"","en":"He made angels out of men, without delay. ||1||"}],"audio":null,"youtube":"zBJgPM2uR0Y"},{"id":"barah-maha-majh","name":"Barah Maha (Majh)","gurmukhiName":"ਬਾਰਹ ਮਾਹਾ ਮਾਂਝ","author":"Guru Arjan Dev Ji","ang":"133–136","raag":"Raag Majh","source":"Sri Guru Granth Sahib Ji","type":"Bani","nitnem":false,"baniDbId":27,"lineCount":130,"opening":[{"g":"ਕਿਰਤਿ ਕਰਮ ਕੇ ਵੀਛੁੜੇ ਕਰਿ ਕਿਰਪਾ ਮੇਲਹੁ ਰਾਮ ॥","t":"kirat karam ke veechhuRe kar kirapaa melahu raam ||","pa":"ਹੇ ਪ੍ਰਭੂ ! ਅਸੀ ਆਪਣੇ ਕਰਮਾਂ ਦੀ ਕਮਾਈ ਅਨੁਸਾਰ (ਤੈਥੋਂ) ਵਿੱਛੁੜੇ ਹੋਏ ਹਾਂ (ਤੈਨੂੰ ਵਿਸਾਰੀ ਬੈਠੇ ਹਾਂ), ਮਿਹਰ ਕਰ ਕੇ ਸਾਨੂੰ ਆਪਣੇ ਨਾਲ ਮਿਲਾਵੋ ।","hi":"हे प्रभू !हम अपने कर्मों की कमाई के अनुसार (तुझसे) विछुड़े हुए हैं (तुझे बिसारे बैठे हैं)~ मेहर करके हमें अपने साथ मिलाओ।","en":"By the actions we have committed, we are separated from You. Please show Your Mercy, and unite us with Yourself, Lord."},{"g":"ਚਾਰਿ ਕੁੰਟ ਦਹ ਦਿਸ ਭ੍ਰਮੇ ਥਕਿ ਆਏ ਪ੍ਰਭ ਕੀ ਸਾਮ ॥","t":"chaar ku(n)T dheh dhis bhrame thak aae prabh kee saam ||","pa":"(ਮਾਇਆ ਦੇ ਮੋਹ ਵਿਚ ਫਸ ਕੇ) ਚੁਫੇਰੇ ਹਰ ਪਾਸੇ (ਸੁਖਾਂ ਦੀ ਖ਼ਾਤਰ) ਭਟਕਦੇ ਰਹੇ ਹਾਂ, ਹੁਣ, ਹੇ ਪ੍ਰਭੂ ! ਥੱਕ ਕੇ ਤੇਰੀ ਸਰਨ ਆਏ ਹਾਂ ।","hi":"(माया के मोह में फंस के) चुफेरे हर तरफ (सुखों की खातिर) भटकते रहे हैं। अब~ हे प्रभू थक के तेरी शरण आए हैं।","en":"We have grown weary of wandering to the four corners of the earth and in the ten directions. We have come to Your Sanctuary, God."}],"audio":null,"youtube":"iTy455s7bbE"},{"id":"laavan","name":"Laavan","gurmukhiName":"ਲਾਵਾਂ","author":"Guru Ram Das Ji","ang":"773–774","raag":"Raag Suhi","source":"Sri Guru Granth Sahib Ji","type":"Bani","nitnem":false,"baniDbId":11,"lineCount":26,"opening":[{"g":"ਹਰਿ ਪਹਿਲੜੀ ਲਾਵ ਪਰਵਿਰਤੀ ਕਰਮ ਦ੍ਰਿੜਾਇਆ ਬਲਿ ਰਾਮ ਜੀਉ ॥","t":"har pahilaRee laav paraviratee karam dhiraRaiaa bal raam jeeau ||","pa":"ਹੇ ਰਾਮ ਜੀ! ਮੈਂ ਤੈਥੋਂ ਸਦਕੇ ਹਾਂ । (ਤੇਰੀ ਮਿਹਰ ਨਾਲ ਗੁਰੂ ਨੇ ਸਿੱਖ ਨੂੰ) ਹਰਿ-ਨਾਮ ਜਪਣ ਦੇ ਆਹਰ ਵਿਚ ਰੁੱਝਣ ਦਾ ਕੰਮ ਨਿਸ਼ਚੇ ਕਰਾਇਆ ਹੈ (ਤਾਕੀਦ ਕੀਤੀ ਹੈ) । ਇਹੀ ਹੈ ਪ੍ਰਭੂ-ਪਤੀ ਨਾਲ (ਜੀਵ-ਇਸਤ੍ਰੀ ਦੇ ਵਿਆਹ ਦੀ) ਪਹਿਲੀ ਸੋਹਣੀ ਲਾਂਵ ।","hi":"हे राम जी ! मैं तुझसे सदके जाता हूँ।(तेरी मेहर से गुरू के सिख को) हरी-नाम जपने के आहर में व्यस्त होने का काम निश्चय करवाया है (हरी-नाम जपने की कर्म प्रवृति दृढ़ करवाई है)।यही है प्रभू-पति से (जीव-स्त्री के विवाह की) पहली सुंदर लांव।","en":"In the first round of the marriage ceremony, the Lord sets out His Instructions for performing the daily duties of married life."},{"g":"ਬਾਣੀ ਬ੍ਰਹਮਾ ਵੇਦੁ ਧਰਮੁ ਦ੍ਰਿੜਹੁ ਪਾਪ ਤਜਾਇਆ ਬਲਿ ਰਾਮ ਜੀਉ ॥","t":"baanee brahamaa vedh dharam dhiraRahu paap tajaiaa bal raam jeeau ||","pa":"ਹੇ ਭਾਈ! ਗੁਰੂ ਦੀ ਬਾਣੀ ਹੀ (ਸਿੱਖ ਵਾਸਤੇ) ਬ੍ਰਹਮਾ ਦਾ ਵੇਦ ਹੈ । ਇਸ ਬਾਣੀ ਦੀ ਬਰਕਤਿ ਨਾਲ ਪਰਮਾਤਮਾ ਦਾ ਨਾਮ ਸਿਮਰਨ ਦਾ) ਧਰਮ (ਆਪਣੇ ਹਿਰਦੇ ਵਿਚ) ਪੱਕਾ ਕਰੋ (ਨਾਮ ਸਿਮਰਿਆਂ ਸਾਰੇ) ਪਾਪ ਦੂਰ ਹੋ ਜਾਂਦੇ ਹਨ ।","hi":"हे भाई ! गुरू की बाणी ही (सिख के लिए) ब्रहमा के वेद हैं।इस बाणी की बरकति से (परमात्मा के नाम के सिमरन का) धर्म (अपने हृदय में) पक्का करो (नाम सिमरने से सारे) पाप दूर हो जाते हैं।","en":"Instead of the hymns of the Vedas to Brahma, embrace the righteous conduct of Dharma, and renounce sinful actions."}],"audio":null,"youtube":null},{"id":"salok-mahalla-9","name":"Salok Mahalla 9","gurmukhiName":"ਸਲੋਕ ਮਹਲਾ ੯","author":"Guru Tegh Bahadur Ji","ang":"1426–1429","source":"Sri Guru Granth Sahib Ji","type":"Bani","nitnem":false,"baniDbId":30,"lineCount":117,"opening":[{"g":"ਗੁਨ ਗੋਬਿੰਦ ਗਾਇਓ ਨਹੀ ਜਨਮੁ ਅਕਾਰਥ ਕੀਨੁ ॥","t":"gun gobi(n)dh gaio nahee janam akaarath keen ||","pa":"ਹੇ ਭਾਈ! ਜੇ ਤੂੰ ਪਰਮਾਤਮਾ ਦੇ ਗੁਣ ਕਦੇ ਨਹੀਂ ਗਾਏ, ਤਾਂ ਤੂੰ ਆਪਣਾ ਮਨੁੱਖਾ ਜਨਮ ਨਿਕੰਮਾ ਕਰ ਲਿਆ ।","hi":"हे भाई ! अगर तूने परमात्मा के गुण कभी नहीं गाए। तो तूने अपना मानस जन्म निकम्मा कर लिया।","en":"If you do not sing the Praises of the Lord, your life is rendered useless."},{"g":"ਕਹੁ ਨਾਨਕ ਹਰਿ ਭਜੁ ਮਨਾ ਜਿਹ ਬਿਧਿ ਜਲ ਕਉ ਮੀਨੁ ॥੧॥","t":"kahu naanak har bhaj manaa jeh bidh jal kau meen ||1||","pa":"ਹੇ ਨਾਨਕ! ਆਖ—ਹੇ ਮਨ! ਪਰਮਾਤਮਾ ਦਾ ਭਜਨ ਕਰਿਆ ਕਰ (ਤੇ, ਉਸ ਨੂੰ ਇਉਂ ਜ਼ਿੰਦਗੀ ਦਾ ਆਸਰਾ ਬਣਾ) ਜਿਵੇਂ ਪਾਣੀ ਨੂੰ ਮੱਛੀ (ਆਪਣੀ ਜਿੰਦ ਦਾ ਆਸਰਾ ਬਣਾਈ ਰੱਖਦੀ ਹੈ) ।੧।","hi":"हे नानक ! कह-हे मन ! परमात्मा का भजन किया कर (और। उसको इस तरह जिंदगी का आसरा बना) जैसे पानी को मछली (अपनी जिंद का आसरा बनाए रखती है)। 1।","en":"Says Nanak, meditate, vibrate upon the Lord; immerse your mind in Him, like the fish in the water. ||1||"}],"audio":null,"youtube":"hVJlk1XEl-4"},{"id":"bavan-akhri","name":"Bavan Akhri","gurmukhiName":"ਬਾਵਨ ਅਖਰੀ","author":"Guru Arjan Dev Ji","ang":"250–262","raag":"Raag Gauri","source":"Sri Guru Granth Sahib Ji","type":"Bani","nitnem":false,"baniDbId":33,"lineCount":674,"opening":[{"g":"ਗੁਰਦੇਵ ਮਾਤਾ ਗੁਰਦੇਵ ਪਿਤਾ ਗੁਰਦੇਵ ਸੁਆਮੀ ਪਰਮੇਸੁਰਾ ॥","t":"gurdhev maataa gurdhev pitaa gurdhev suaamee paramesuraa ||","pa":"ਗੁਰੂ ਹੀ ਮਾਂ ਹੈ, ਗੁਰੂ ਹੀ ਪਿਉ ਹੈ (ਗੁਰੂ ਹੀ ਆਤਮਕ ਜਨਮ ਦੇਣ ਵਾਲਾ ਹੈ), ਗੁਰੂ ਮਾਲਕ-ਪ੍ਰਭੂ ਦਾ ਰੂਪ ਹੈ ।","hi":"गुरू ही मां है। गुरू ही पिता है (गुरू ही आत्मिक जन्म देने वाला है)। गुरू मालिक प्रभू का रूप है।","en":"The Divine Guru is my mother, the Divine Guru is my father; the Divine Guru is my Transcendent Lord and Master."},{"g":"ਗੁਰਦੇਵ ਸਖਾ ਅਗਿਆਨ ਭੰਜਨੁ ਗੁਰਦੇਵ ਬੰਧਿਪ ਸਹੋਦਰਾ ॥","t":"gurdhev sakhaa agiaan bha(n)jan gurdhev ba(n)dhip sahodharaa ||","pa":"ਗੁਰੂ (ਮਾਇਆ ਦੇ ਮੋਹ ਦਾ) ਹਨੇਰਾ ਨਾਸ ਕਰਨ ਵਾਲਾ ਮਿੱਤਰ ਹੈ, ਗੁਰੂ ਹੀ (ਤੋੜ ਨਿਭਣ ਵਾਲਾ) ਸੰਬੰਧੀ ਤੇ ਭਰਾ ਹੈ ।","hi":"गुरू (माया के मोह का) अंधकार नाश करने वाला मित्र है। गुरू ही (तोड़ निभाने वाला) संबंधी व भाई है।","en":"The Divine Guru is my companion, the Destroyer of ignorance; the Divine Guru is my relative and brother."}],"audio":null,"youtube":"4VXu9yb74k0"},{"id":"sidh-gosht","name":"Sidh Gosht","gurmukhiName":"ਸਿਧ ਗੋਸਟਿ","author":"Guru Nanak Dev Ji","ang":"938–946","raag":"Raag Ramkali","source":"Sri Guru Granth Sahib Ji","type":"Bani","nitnem":false,"baniDbId":34,"lineCount":406,"opening":[{"g":"ਸਿਧ ਸਭਾ ਕਰਿ ਆਸਣਿ ਬੈਠੇ ਸੰਤ ਸਭਾ ਜੈਕਾਰੋ ॥","t":"sidh sabhaa kar aasan baiThe sa(n)t sabhaa jaikaaro ||","pa":"(ਸਾਡੀ) ਨਮਸਕਾਰ ਉਹਨਾਂ ਸੰਤਾਂ ਦੀ ਸਭਾ ਨੂੰ ਹੈ ਜੋ ‘ਰੱਬੀ ਮਜਲਸ’ (ਸਤਸੰਗ) ਬਣਾ ਕੇ ਅਡੋਲ ਬੈਠੇ ਹਨ;","hi":"(हमारी) नमस्कार उन संतों की सभा को है जो 'ईश्वरीय सभा' (सत्संग) बना के अडोल बैठे हैं।","en":"The Siddhas formed an assembly; sitting in their Yogic postures, they shouted, \"\"Salute this gathering of Saints.\"\""},{"g":"ਤਿਸੁ ਆਗੈ ਰਹਰਾਸਿ ਹਮਾਰੀ ਸਾਚਾ ਅਪਰ ਅਪਾਰੋ ॥","t":"tis aagai raharaas hamaaree saachaa apar apaaro ||","pa":"ਸਾਡੀ ਅਰਦਾਸ ਉਸ ਸੰਤ-ਸਭਾ ਅੱਗੇ ਹੈ ਜਿਸ ਵਿਚ ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲਾ ਅਪਰ ਅਪਾਰ ਪ੍ਰਭੂ (ਪ੍ਰਤੱਖ ਵੱਸਦਾ) ਹੈ ।","hi":"हमारी अरदास उस संत सभा के आगे है जिसमें सदा कायम रहने वाला अपर-अपार प्रभू (प्रत्यक्ष बसता) है।","en":"I offer my salutation to the One who is true, infinite and incomparably beautiful."}],"audio":null,"youtube":"O9mZoNt9eTU"},{"id":"dakhni-oankar","name":"Dakhni Oankar","gurmukhiName":"ਦਖਣੀ ਓਅੰਕਾਰੁ","author":"Guru Nanak Dev Ji","ang":"929–938","raag":"Raag Ramkali","source":"Sri Guru Granth Sahib Ji","type":"Bani","nitnem":false,"baniDbId":35,"lineCount":400,"opening":[{"g":"ਓਅੰਕਾਰਿ ਬ੍ਰਹਮਾ ਉਤਪਤਿ ॥","t":"oa(n)kaar brahamaa utapat ||","pa":"(ਹੇ ਪਾਂਡੇ! ਤੁਸੀ ਮੰਦਰ ਵਿਚ ਅਸਥਾਪਨ ਕੀਤੀ ਹੋਈ ਇਸ ਮੂਰਤੀ ਨੂੰ ‘ਓਅੰਕਾਰ’ ਮਿਥ ਰਹੇ ਹੋ, ਤੇ ਆਖਦੇ ਹੋ ਕਿ ਸ੍ਰਿਸ਼ਟੀ ਨੂੰ ਬ੍ਰਹਮਾ ਨੇ ਪੈਦਾ ਕੀਤਾ ਸੀ । ਪਰ ‘ਓਅੰਕਾਰ’ ਉਹ ਸਰਬ-ਵਿਆਪਕ ਪਰਮਾਤਮਾ ਹੈ ਜਿਸ) ਸਰਬ-ਵਿਆਪਕ ਪਰਮਾਤਮਾ ਤੋਂ ਬ੍ਰਹਮਾ ਦਾ (ਭੀ) ਜਨਮ ਹੋਇਆ,","hi":"(हे पांडे ! तुम मन्दिर में स्थापित की हुई मूर्ति को 'ओंकार' मिथ रहे हो। और कहते हो सृष्टि को ब्रहमा ने पैदा किया था। 'ओअंकार' वह सर्व-व्यापक परमात्मा है जिस) सर्व-व्यापक परमात्मा से ब्रहमा का (भी) जन्म हुआ।","en":"From Ongkaar, the One Universal Creator God, Brahma was created."},{"g":"ਓਅੰਕਾਰੁ ਕੀਆ ਜਿਨਿ ਚਿਤਿ ॥","t":"oa(n)kaar keeaa jin chit ||","pa":"ਉਸ ਬ੍ਰਹਮਾ ਨੇ ਭੀ ਉਸ ਸਰਬ-ਵਿਆਪਕ ਪ੍ਰਭੂ ਨੂੰ ਆਪਣੇ ਮਨ ਵਿਚ ਵਸਾਇਆ ।","hi":"उस ब्रह्मा ने भी उस सर्व-व्यापक प्रभू को अपने मन में बसाया।","en":"He kept Ongkaar in his consciousness."}],"audio":null,"youtube":"l9M6DgukGSM"}],"shabads":[{"id":"shabad-300","type":"Shabad","title":"Too(n) meraa pitaa too(n)hai meraa maataa ","gurmukhiTitle":"ਤੂੰ ਮੇਰਾ ਪਿਤਾ ਤੂੰਹੈ ਮੇਰਾ ਮਾਤਾ","author":"Guru Arjan Dev Ji","raag":"Raag Maajh","ang":103,"source":"Sri Guru Granth Sahib Ji","nitnem":false,"lines":[{"g":"ਮਾਝ ਮਹਲਾ ੫ ॥","t":"maajh mahalaa panjavaa ||","pa":"","hi":"","en":"Maajh, Fifth Mehla:"},{"g":"ਤੂੰ ਮੇਰਾ ਪਿਤਾ ਤੂੰਹੈ ਮੇਰਾ ਮਾਤਾ ॥","t":"too(n) meraa pitaa too(n)hai meraa maataa ||","pa":"ਹੇ ਪ੍ਰਭੂ ! ਤੂੰ ਮੇਰਾ ਪਿਉ (ਦੇ ਥਾਂ) ਹੈਂ ਤੂੰ ਹੀ ਮੇਰਾ ਮਾਂ (ਦੇ ਥਾਂ) ਹੈ,","hi":"हे प्रभू ! तू मेरा पिता (की जगह) है तू ही मेरी माँ (की जगह) है।","en":"You are my Father, and You are my Mother."},{"g":"ਤੂੰ ਮੇਰਾ ਬੰਧਪੁ ਤੂੰ ਮੇਰਾ ਭ੍ਰਾਤਾ ॥","t":"too(n) meraa ba(n)dhap too(n) meraa bhraataa ||","pa":"ਤੂੰ ਮੇਰਾ ਰਿਸ਼ਤੇਦਾਰ ਹੈਂ ਤੂੰ ਹੀ ਮੇਰਾ ਭਰਾ ਹੈਂ ।","hi":"तू मेरा रिश्तेदार है~ तू ही मेरा भाई है।","en":"You are my Relative, and You are my Brother."},{"g":"ਤੂੰ ਮੇਰਾ ਰਾਖਾ ਸਭਨੀ ਥਾਈ ਤਾ ਭਉ ਕੇਹਾ ਕਾੜਾ ਜੀਉ ॥੧॥","t":"too(n) meraa raakhaa sabhanee thaiee taa bhau kehaa kaaRaa jeeau ||1||","pa":"(ਹੇ ਪ੍ਰਭੂ ! ਜਦੋਂ) ਤੂੰ ਹੀ ਸਭ ਥਾਵਾਂ ਤੇ ਮੇਰਾ ਰਾਖਾ ਹੈਂ, ਤਾਂ ਕੋਈ ਡਰ ਮੈਨੂੰ ਪੋਹ ਨਹੀਂ ਸਕਦਾ, ਕੋਈ ਚਿੰਤਾ ਮੇਰੇ ਉੱਤੇ ਜ਼ੋਰ ਨਹੀਂ ਪਾ ਸਕਦੀ ।੧।","hi":"(हे प्रभू ! जब) तू ही सब जगहों पे मेरा रक्षक है~ तो कोई डर मुझे पोह भी नहीं सकता~ कोई चिंता मुझपर जोर नहीं डाल सकती।1।","en":"You are my Protector everywhere; why should I feel any fear or anxiety? ||1||"},{"g":"ਤੁਮਰੀ ਕ੍ਰਿਪਾ ਤੇ ਤੁਧੁ ਪਛਾਣਾ ॥","t":"tumaree kirapaa te tudh pachhaanaa ||","pa":"(ਹੇ ਪ੍ਰਭੂ !) ਤੇਰੀ ਮਿਹਰ ਨਾਲ ਹੀ ਮੈਂ ਤੇਰੇ ਨਾਲ ਡੂੰਘੀ ਸਾਂਝ ਪਾ ਸਕਦਾ ਹਾਂ ।","hi":"(हे प्रभू !) तेरी मेहर से मैं तेरे साथ गहरी सांझ डाल सकता हूँ।","en":"By Your Grace, I recognize You."},{"g":"ਤੂੰ ਮੇਰੀ ਓਟ ਤੂੰਹੈ ਮੇਰਾ ਮਾਣਾ ॥","t":"too(n) meree oT too(n)hai meraa maanaa ||","pa":"ਤੂੰ ਹੀ ਮੇਰਾ ਆਸਰਾ ਹੈਂ, ਤੂੰ ਹੀ ਮੇਰਾ ਫ਼ਖ਼ਰ ਦਾ ਥਾਂ ਹੈਂ ।","hi":"तू ही मेरा आसरा है~ तू ही मेरे गौरव की जगह है।","en":"You are my Shelter, and You are my Honor."},{"g":"ਤੁਝ ਬਿਨੁ ਦੂਜਾ ਅਵਰੁ ਨ ਕੋਈ ਸਭੁ ਤੇਰਾ ਖੇਲੁ ਅਖਾੜਾ ਜੀਉ ॥੨॥","t":"tujh bin dhoojaa avar na koiee sabh teraa khel akhaaRaa jeeau ||2||","pa":"ਤੈਥੋਂ ਬਿਨਾ ਤੇਰੇ ਵਰਗਾ ਹੋਰ ਕੋਈ ਨਹੀਂ ਹੈ । ਇਹ ਜਗਤ ਤਮਾਸ਼ਾ ਇਹ ਜਗਤ ਅਖਾੜਾ ਤੇਰਾ ਹੀ ਬਣਾਇਆ ਹੋਇਆ ਹੈ ।੨।","hi":"तेरे बगैर तेरे जैसा और कोई नहीं। ये जगत तमाशा ये जगत अखाड़ा तेरा ही बनाया हुआ है।2।","en":"Without You, there is no other; the entire Universe is the Arena of Your Play. ||2||"},{"g":"ਜੀਅ ਜੰਤ ਸਭਿ ਤੁਧੁ ਉਪਾਏ ॥","t":"jeea ja(n)t sabh tudh upaae ||","pa":"(ਹੇ ਪ੍ਰਭੂ !) ਜਗਤ ਦੇ ਸਾਰੇ ਜੀਅ ਜੰਤ ਤੂੰ ਹੀ ਪੈਦਾ ਕੀਤੇ ਹਨ,","hi":"(हे प्रभू !) जगत के सारे जीव जन्तु तूने ही पैदा किये हैं।","en":"You have created all beings and creatures."},{"g":"ਜਿਤੁ ਜਿਤੁ ਭਾਣਾ ਤਿਤੁ ਤਿਤੁ ਲਾਏ ॥","t":"jit jit bhaanaa tit tit laae ||","pa":"ਜਿਸ ਜਿਸ ਕੰਮ ਵਿਚ ਤੇਰੀ ਰਜ਼ਾ ਹੋਈ ਤੂੰ ਉਸ ਉਸ ਕੰਮ ਵਿਚ (ਸਾਰੇ ਜੀਅ ਜੰਤ) ਲਾਏ ਹੋਏ ਹਨ ।","hi":"जिस जिस काम में तेरी रजा होती है तूने उस उस काम में (सारे जीव जन्तु) लगाए हुए हैं।","en":"As it pleases You, You assign tasks to one and all."},{"g":"ਸਭ ਕਿਛੁ ਕੀਤਾ ਤੇਰਾ ਹੋਵੈ ਨਾਹੀ ਕਿਛੁ ਅਸਾੜਾ ਜੀਉ ॥੩॥","t":"sabh kichh keetaa teraa hovai naahee kichh asaaRaa jeeau ||3||","pa":"(ਜਗਤ ਵਿਚ ਜੋ ਕੁਝ ਹੋ ਰਿਹਾ ਹੈ) ਸਭ ਤੇਰਾ ਕੀਤਾ ਹੋ ਰਿਹਾ ਹੈ, ਸਾਡਾ ਜੀਵਾਂ ਦਾ ਕੋਈ ਜ਼ੋਰ ਨਹੀਂ ਚੱਲ ਸਕਦਾ ।੩।","hi":"(जगत में जो कुछ हो रहा है) सब तेरा किया ही हो रहा है। हम जीवों का कोई जोर नहीं चल सकता।3।","en":"All things are Your Doing; we can do nothing ourselves. ||3||"},{"g":"ਨਾਮੁ ਧਿਆਇ ਮਹਾ ਸੁਖੁ ਪਾਇਆ ॥","t":"naam dhiaai mahaa sukh paiaa ||","pa":"(ਹੇ ਭਾਈ !) ਪਰਮਤਾਮਾ ਦਾ ਨਾਮ ਸਿਮਰ ਕੇ ਮੈਂ ਬੜਾ ਆਤਮਕ ਆਨੰਦ ਹਾਸਲ ਕੀਤਾ ਹੈ ।","hi":"(हे भाई !) परमात्मा का नाम सिमर के मैंने बड़ा आत्मिक आनंद हासिल किया है।","en":"Meditating on the Naam, I have found great peace."},{"g":"ਹਰਿ ਗੁਣ ਗਾਇ ਮੇਰਾ ਮਨੁ ਸੀਤਲਾਇਆ ॥","t":"har gun gai meraa man seetalaiaa ||","pa":"ਪਰਮਾਤਮਾ ਦੇ ਗੁਣ ਗਾ ਕੇ ਮੇਰਾ ਮਨ ਠੰਢਾ-ਠਾਰ ਹੋ ਗਿਆ ਹੈ ।","hi":"परमात्मा के गुण गा के मेरा मन ठण्डा ठार हो गया है।","en":"Singing the Glorious Praises of the Lord, my mind is cooled and soothed."},{"g":"ਗੁਰਿ ਪੂਰੈ ਵਜੀ ਵਾਧਾਈ ਨਾਨਕ ਜਿਤਾ ਬਿਖਾੜਾ ਜੀਉ ॥੪॥੨੪॥੩੧॥","t":"gur poorai vajee vaadhaiee naanak jitaa bikhaaRaa jeeau ||4||24||31||","pa":"ਹੇ ਨਾਨਕ ! (ਆਖ—) ਪੂਰੇ ਗੁਰੂ ਦੀ ਰਾਹੀਂ (ਮੇਰੇ ਅੰਦਰ) ਆਤਮਕ ਉਤਸ਼ਾਹ ਦਾ (ਮਾਨੋ) ਢੋਲ ਵੱਜ ਪਿਆ ਹੈ ਤੇ ਮੈਂ (ਵਿਕਾਰਾਂ ਨਾਲ ਹੋ ਰਿਹਾ) ਔਖਾ ਘੋਲ ਜਿੱਤ ਲਿਆ ਹੈ ।੪।੨੪।੩੧।","hi":"हे नानक ! (कह–) पूरे गुरू के द्वारा (मेरे अंदर) आत्मिक उत्साह का (जैसे) ढोल बज रहा है और मैंने (विकारों के साथ हो रही) मुश्किल कुश्ती को जीत लिया है।4।24।31।","en":"Through the Perfect Guru, congratulations are pouring in-Nanak is victorious on the arduous battlefield of life! ||4||24||31||"}],"audioUrl":null,"youtube":{"id":"XLv-1DYujvo","artist":"Bhai Davinder Singh Sodhi"}},{"id":"shabad-2404","type":"Shabad","title":"Jo nar dhukh mai dhukh nahee maanai ","gurmukhiTitle":"ਜੋ ਨਰੁ ਦੁਖ ਮੈ ਦੁਖੁ ਨਹੀ ਮਾਨੈ","author":"Guru Tegh Bahadur Ji","raag":"Raag Sorath","ang":633,"source":"Sri Guru Granth Sahib Ji","nitnem":false,"lines":[{"g":"ਸੋਰਠਿ ਮਹਲਾ ੯ ॥","t":"soraTh mahalaa nauvaa ||","pa":"","hi":"","en":"Sorat'h, Ninth Mehla:"},{"g":"ਜੋ ਨਰੁ ਦੁਖ ਮੈ ਦੁਖੁ ਨਹੀ ਮਾਨੈ ॥","t":"jo nar dhukh mai dhukh nahee maanai ||","pa":"ਹੇ ਭਾਈ! ਜੇਹੜਾ ਮਨੁੱਖ ਦੁੱਖਾਂ ਵਿਚ ਘਬਰਾਂਦਾ ਨਹੀਂ","hi":"हे भाई ! जो मनुष्य दुखों में घबराता नहीं।","en":"That man, who in the midst of pain, does not feel pain,"},{"g":"ਸੁਖ ਸਨੇਹੁ ਅਰੁ ਭੈ ਨਹੀ ਜਾ ਕੈ ਕੰਚਨ ਮਾਟੀ ਮਾਨੈ ॥੧॥ ਰਹਾਉ ॥","t":"sukh saneh ar bhai nahee jaa kai ka(n)chan maaTee maanai ||1|| rahaau ||","pa":"ਜਿਸ ਮਨੁੱਖ ਦੇ ਹਿਰਦੇ ਵਿਚ ਸੁਖਾਂ ਨਾਲ ਮੋਹ ਨਹੀਂ, ਅਤੇ (ਕਿਸੇ ਕਿਸਮ ਦੇ) ਡਰ ਨਹੀਂ, ਜੇਹੜਾ ਮਨੁੱਖ ਸੋਨੇ ਨੂੰ ਮਿੱਟੀ (ਸਮਾਨ) ਸਮਝਦਾ ਹੈ (ਉਸ ਦੇ ਅੰਦਰ ਪਰਮਾਤਮਾ ਦਾ ਨਿਵਾਸ ਹੋ ਜਾਂਦਾ ਹੈ) ।੧।ਰਹਾਉ।","hi":"जिस मनुष्य के हृदय में सुखों से मोह नहीं।और (किसी किस्म का) डर नहीं।जो मनुष्य सोने को मिट्टी (के समान) समझता है (उसके अंदर परमात्मा का निवास हो जाता है)। 1।रहाउ।","en":"who is not affected by pleasure, affection or fear, and who looks alike upon gold and dust;||1||Pause||"},{"g":"ਨਹ ਨਿੰਦਿਆ ਨਹ ਉਸਤਤਿ ਜਾ ਕੈ ਲੋਭੁ ਮੋਹੁ ਅਭਿਮਾਨਾ ॥","t":"neh ni(n)dhiaa neh usatat jaa kai lobh moh abhimaanaa ||","pa":"ਹੇ ਭਾਈ! ਜਿਸ ਮਨੁੱਖ ਦੇ ਅੰਦਰ ਕਿਸੇ ਦੀ ਚੁਗ਼ਲੀ-ਬੁਰਾਈ ਨਹੀਂ, ਕਿਸੇ ਦੀ ਖ਼ੁਸ਼ਾਮਦ ਨਹੀਂ, ਜਿਸ ਦੇ ਅੰਦਰ ਨਾਹ ਲੋਭ ਹੈ, ਨਾਹ ਮੋਹ ਹੈ, ਨਾਹ ਅਹੰਕਾਰ ਹੈ;","hi":"हे भाई ! जिस मनुष्य के अंदर किसी की चुगली-बुराई नहीं।किसी की खुशमद नहीं।जिसके अंदर ना लोभ है।ना मोह है।ना अहंकार है;","en":"Who is not swayed by either slander or praise, nor affected by greed, attachment or pride;"},{"g":"ਹਰਖ ਸੋਗ ਤੇ ਰਹੈ ਨਿਆਰਉ ਨਾਹਿ ਮਾਨ ਅਪਮਾਨਾ ॥੧॥","t":"harakh sog te rahai niaarau naeh maan apamaanaa ||1||","pa":"ਜੇਹੜਾ ਮਨੁੱਖ ਖ਼ੁਸ਼ੀ ਤੇ ਗ਼ਮੀ ਤੋਂ ਨਿਰਲੇਪ ਰਹਿੰਦਾ ਹੈ, ਜਿਸ ਨੂੰ ਨਾਹ ਆਦਰ ਪੋਹ ਸਕਦਾ ਹੈ ਨਾਹ ਨਿਰਾਦਰੀ (ਮਨੁੱਖ ਦੇ ਹਿਰਦੇ ਵਿਚ ਪਰਮਾਤਮਾ ਦਾ ਨਿਵਾਸ ਹੋ ਜਾਂਦਾ ਹੈ)","hi":"जो मनुष्य खुशी और ग़मी से निर्लिप रहता है।जिस पर ना आदर असर कर सकता है ना निरादरी (ऐसे मनुष्य के दिल में परमात्मा का निवास हो जाता है)। 1।","en":"who remains unaffected by joy and sorrow, honor and dishonor;||1||"},{"g":"ਆਸਾ ਮਨਸਾ ਸਗਲ ਤਿਆਗੈ ਜਗ ਤੇ ਰਹੈ ਨਿਰਾਸਾ ॥","t":"aasaa manasaa sagal tiaagai jag te rahai niraasaa ||","pa":"ਹੇ ਭਾਈ! ਜੇਹੜਾ ਮਨੁੱਖਾਂ ਆਸਾਂ ਉਮੈਦਾਂ ਸਭ ਤਿਆਗ ਦੇਂਦਾ ਹੈ, ਜਗਤ ਤੋਂ ਨਿਰਮੋਹ ਰਹਿੰਦਾ ਹੈ,","hi":"हे भाई ! जो मनुष्य आशाएं-उम्मीदें सब त्याग देता है।जगत से निर्मोह रहता है।","en":"who renounces all hopes and desires and remains desireless in the world;"},{"g":"ਕਾਮੁ ਕ੍ਰੋਧੁ ਜਿਹ ਪਰਸੈ ਨਾਹਨਿ ਤਿਹ ਘਟਿ ਬ੍ਰਹਮੁ ਨਿਵਾਸਾ ॥੨॥","t":"kaam karodh jeh parasai naahan teh ghaT braham nivaasaa ||2||","pa":"ਜਿਸ ਮਨੁੱਖ ਨੂੰ ਨਾਹ ਕਾਮ-ਵਾਸਨਾ ਛੋਹ ਸਕਦੀ ਹੈ ਨਾਹ ਕੋ੍ਰਧ ਛੋਹ ਸਕਦਾ ਹੈ, ਉਸ ਮਨੁੱਖ ਦੇ ਹਿਰਦੇ ਵਿਚ ਪਰਮਾਤਮਾ ਦਾ ਨਿਵਾਸ ਹੋ ਜਾਂਦਾ ਹੈ ।੨।","hi":"जिस मनुष्य को ना काम-वासना छू सकती है ना ही क्रोध छू सकता है।उस मनुष्य के दिल में परमात्मा का निवास हो जाता है। 2।","en":"who is not touched by sexual desire or anger - within his heart, God dwells. ||2||"},{"g":"ਗੁਰ ਕਿਰਪਾ ਜਿਹ ਨਰ ਕਉ ਕੀਨੀ ਤਿਹ ਇਹ ਜੁਗਤਿ ਪਛਾਨੀ ॥","t":"gur kirapaa jeh nar kau keenee teh ieh jugat pachhaanee ||","pa":"(ਪਰ) ਹੇ ਨਾਨਕ! (ਆਖ—) ਜਿਸ ਮਨੁੱਖ ਉੱਤੇ ਗੁਰੂ ਨੇ ਮੇਹਰ ਕੀਤੀ ਉਸ ਨੇ (ਹੀ ਜੀਵਨ ਦੀ) ਇਹ ਜਾਚ ਸਮਝੀ ਹੈ ।","hi":"(पर) हे नानक ! (कह–) जिस मनुष्य पर गुरू ने मेहर की उसने (ही जीवन की) ये जाच समझी है।","en":"That man, blessed by Guru's Grace, understands this way."},{"g":"ਨਾਨਕ ਲੀਨ ਭਇਓ ਗੋਬਿੰਦ ਸਿਉ ਜਿਉ ਪਾਨੀ ਸੰਗਿ ਪਾਨੀ ॥੩॥੧੧॥","t":"naanak leen bhio gobi(n)dh siau jiau paanee sa(n)g paanee ||3||11||","pa":"ਉਹ ਮਨੁੱਖ ਪਰਮਾਤਮਾ ਨਾਲ ਇਉਂ ਇਕ-ਮਿਕ ਹੋ ਜਾਂਦਾ ਹੈ, ਜਿਵੇਂ ਪਾਣੀ ਨਾਲ ਪਾਣੀ ਮਿਲ ਜਾਂਦਾ ਹੈ ।੩।੧੧।","hi":"वह मनुष्य परमात्मा के साथ ऐसे एक-मेक हो जाता है।जैसे पानी के साथ पानी मिल जाता है। 3। 11।","en":"O Nanak, he merges with the Lord of the Universe, like water with water. ||3||11||"}],"audioUrl":null,"youtube":null},{"id":"shabad-277","type":"Shabad","title":"Meraa man lochai gur dharasan taiee ","gurmukhiTitle":"ਮੇਰਾ ਮਨੁ ਲੋਚੈ ਗੁਰ ਦਰਸਨ ਤਾਈ","author":"Guru Arjan Dev Ji","raag":"Raag Maajh","ang":96,"source":"Sri Guru Granth Sahib Ji","nitnem":false,"lines":[{"g":"ਮਾਝ ਮਹਲਾ ੫ ਚਉਪਦੇ ਘਰੁ ੧ ॥","t":"maajh mahalaa panjavaa chaupadhe ghar pehilaa ||","pa":"","hi":"","en":"Maajh, Fifth Mehla, Chau-Padhay, First House:"},{"g":"ਮੇਰਾ ਮਨੁ ਲੋਚੈ ਗੁਰ ਦਰਸਨ ਤਾਈ ॥","t":"meraa man lochai gur dharasan taiee ||","pa":"ਗੁਰੂ ਦਾ ਦਰਸਨ ਕਰਨ ਲਈ ਮੇਰਾ ਮਨ ਬੜੀ ਤਾਂਘ ਕਰ ਰਿਹਾ ਹੈ","hi":"गुरू का दर्शन करने के लिए मेरा मन बड़ी तमन्ना कर रहा है","en":"My mind longs for the Blessed Vision of the Guru's Darshan."},{"g":"ਬਿਲਪ ਕਰੇ ਚਾਤ੍ਰਿਕ ਕੀ ਨਿਆਈ ॥","t":"bilap kare chaatirak kee niaaiee ||","pa":"(ਜਿਵੇਂ ਪਪੀਹਾ ਸ੍ਵਾਂਤੀ ਬੂੰਦ ਲਈ ਤਰਲੇ ਲੈਂਦਾ ਹੈ) ਪਪੀਹੇ ਵਾਂਗ (ਮੇਰਾ ਮਨ ਗੁਰੂ ਦੇ ਦਰਸਨ ਲਈ) ਤਰਲੇ ਲੈ ਰਿਹਾ ਹੈ","hi":"(जैसे पपीहा स्वाति बूंद के लिए तड़पता है) पपीहे की तरह (मेरा मन गुरू के दर्शनों के लिए) तड़प रहा है।","en":"It cries out like the thirsty song-bird."},{"g":"ਤ੍ਰਿਖਾ ਨ ਉਤਰੈ ਸਾਂਤਿ ਨ ਆਵੈ ਬਿਨੁ ਦਰਸਨ ਸੰਤ ਪਿਆਰੇ ਜੀਉ ॥੧॥","t":"tirakhaa na utarai saa(n)t na aavai bin dharasan sa(n)t piaare jeeau ||1||","pa":"ਪਿਆਰੇ ਸੰਤ-ਗੁਰੂ ਦੇ ਦਰਸਨ ਤੋਂ ਬਿਨਾ (ਦਰਸਨ ਦੀ ਮੇਰੀ ਆਤਮਕ) ਤ੍ਰੇਹ ਮਿਟਦੀ ਨਹੀਂ, ਮੇਰੇ ਮਨ ਨੂੰ ਧੀਰਜ ਨਹੀਂ ਆਉਂਦੀ ।੧।","hi":"प्यारे संत-गुरू के दर्शन के बिना (दशर्नों की मेरी आत्मिक) प्यास तृप्त नहीं होती। मेरे मन को धैर्य नहीं आता।","en":"My thirst is not quenched, and I can find no peace, without the Blessed Vision of the Beloved Saint. ||1||"},{"g":"ਹਉ ਘੋਲੀ ਜੀਉ ਘੋਲਿ ਘੁਮਾਈ ਗੁਰ ਦਰਸਨ ਸੰਤ ਪਿਆਰੇ ਜੀਉ ॥੧॥ ਰਹਾਉ ॥","t":"hau gholee jeeau ghol ghumaiee gur dharasan sa(n)t piaare jeeau ||1|| rahaau ||","pa":"ਮੈਂ ਪਿਆਰੇ ਸੰਤ-ਗੁਰੂ ਦੇ ਦਰਸਨ ਤੋਂ ਕੁਰਬਾਨ ਹਾਂ, ਸਦਕੇ ਹਾਂ ।੧।ਰਹਾਉ।","hi":"मैं पिआरे संत-गुरू के दर्शन से कुर्बान हूं~ सदके हूँ।1।रहाउ।","en":"I am a sacrifice, my soul is a sacrifice, to the Blessed Vision of the Beloved Saint Guru. ||1||Pause||"},{"g":"ਤੇਰਾ ਮੁਖੁ ਸੁਹਾਵਾ ਜੀਉ ਸਹਜ ਧੁਨਿ ਬਾਣੀ ॥","t":"teraa mukh suhaavaa jeeau sahaj dhun baanee ||","pa":"ਹੇ ਧਨੁਖ-ਧਾਰੀ ਪ੍ਰਭੂ ਜੀ ! ਤੇਰਾ ਮੂੰਹ (ਤੇਰੇ ਮੂੰਹ ਦਾ ਦਰਸਨ) ਸੁਖ ਦੇਣ ਵਾਲਾ ਹੈ (ਠੰਢ ਪਾਣ ਵਾਲਾ ਹੈ) ਤੇਰੀ ਸਿਫ਼ਤਿ‑ਸਾਲਾਹ (ਮੇਰੇ ਅੰਦਰ) ਆਤਮਕ ਅਡੋਲਤਾ ਦੀ ਲਹਰ ਪੈਦਾ ਕਰਦੀ ਹੈ","hi":"हे धर्नुधारी प्रभू जी ! तेरा मुख (तेरे मुंह का दर्शन) सुख देने वाला है (ठण्डक देने वाला है) तेरी सिफत सलाह (मेरे अंदर) आत्मिक अडोलता की लहर पैदा करती है।","en":"Your Face is so Beautiful, and the Sound of Your Words imparts intuitive wisdom."},{"g":"ਚਿਰੁ ਹੋਆ ਦੇਖੇ ਸਾਰਿੰਗਪਾਣੀ ॥","t":"chir hoaa dhekhe saari(n)gapaanee ||","pa":"ਹੇ ਧਨੁਖ-ਧਾਰੀ ! ਤੇਰੇ ਦਰਸਨ ਕੀਤਿਆਂ ਚਿਰ ਹੋ ਗਿਆ ਹੈ","hi":"हे धर्नुधारी ! तेरे दर्शन किए काफी समय हो चुका है।","en":"It is so long since this rainbird has had even a glimpse of water."},{"g":"ਧੰਨੁ ਸੁ ਦੇਸੁ ਜਹਾ ਤੂੰ ਵਸਿਆ ਮੇਰੇ ਸਜਣ ਮੀਤ ਮੁਰਾਰੇ ਜੀਉ ॥੨॥","t":"dha(n)nu su dhes jahaa too(n) vasiaa mere sajan meet muraare jeeau ||2||","pa":"ਹੇ ਮੇਰੇ ਸੱਜਣ ਪ੍ਰਭੂ ! ਹੇ ਮੇਰੇ ਮਿਤ੍ਰ ਪ੍ਰਭੂ ! ਉਹ ਹਿਰਦਾ-ਦੇਸ ਭਾਗਾਂ ਵਾਲਾ ਹੈ ਜਿਸ ਵਿਚ ਤੂੰ (ਸਦਾ) ਵੱਸਦਾ ਹੈਂ ।੨।","hi":"हे मेरे सज्जन प्रभू ! वह हृदय-देश भाग्यशाली है जिसमें तू (सदा) बसता है।2।","en":"Blessed is that land where You dwell, O my Friend and Intimate Divine Guru. ||2||"},{"g":"ਹਉ ਘੋਲੀ ਹਉ ਘੋਲਿ ਘੁਮਾਈ ਗੁਰ ਸਜਣ ਮੀਤ ਮੁਰਾਰੇ ਜੀਉ ॥੧॥ ਰਹਾਉ ॥","t":"hau gholee hau ghol ghumaiee gur sajan meet muraare jeeau ||1|| rahaau ||","pa":"ਹੇ ਮੇਰੇ ਸੱਜਣ ਗੁਰੂ ! ਹੇ ਮੇਰੇ ਮਿਤ੍ਰ ਪ੍ਰਭੂ ! ਮੈਂ ਤੈਥੋਂ ਕੁਰਬਾਨ ਹਾਂ, ਸਦਕੇ ਹਾਂ ।੧।ਰਹਾਉ।","hi":"हे मेरे सज्जन गुरू ! हे मेरे मित्र प्रभू ! मैं तेरे पर कुर्बान हूँ~ सदके हूँ।1।रहाउ।","en":"I am a sacrifice, I am forever a sacrifice, to my Friend and Intimate Divine Guru. ||1||Pause||"},{"g":"ਇਕ ਘੜੀ ਨ ਮਿਲਤੇ ਤਾ ਕਲਿਜੁਗੁ ਹੋਤਾ ॥","t":"eik ghaRee na milate taa kalijug hotaa ||","pa":"ਜਦੋਂ ਮੈਂ ਤੈਨੂੰ ਇਕ ਘੜੀ ਭਰ ਭੀ ਨਹੀਂ ਮਿਲਦਾ ਤਾਂ ਮੇਰੇ ਭਾ ਦਾ ਕਲਿਜੁਗ ਹੋ ਜਾਂਦਾ ਹੈ","hi":"हे प्यारे भगवान ! जब मैं तुझे एक घड़ी भर भी नहीं मिलता तो मुझे जैसे कलियुग सा प्रतीत होने लगता है","en":"When I could not be with You for just one moment, the Dark Age of Kali Yuga dawned for me."},{"g":"ਹੁਣਿ ਕਦਿ ਮਿਲੀਐ ਪ੍ਰਿਅ ਤੁਧੁ ਭਗਵੰਤਾ ॥","t":"hun kadh mileeaai pria tudh bhagava(n)taa ||","pa":"ਹੇ ਪਿਆਰੇ ਭਗਵਾਨ ! (ਮੈਂ ਤੇਰੇ ਵਿਛੋੜੇ ਵਿਚ ਬਿਹਬਲ ਹਾਂ, ਦੱਸ ਹੁਣ ਤੈਨੂੰ ਮੈਂ ਕਦੋਂ ਮਿਲ ਸਕਾਂਗਾ)","hi":"मैं तेरे विछोड़े में विहवल हूँ~ बताओ अब मैं आपको कब मिल सकूँगा। (हे भाई ! गुरू की शरण के बिना परमात्मा से मिलाप नहीं हो सकता~ तभी तो)","en":"When will I meet You, O my Beloved Lord?"},{"g":"ਮੋਹਿ ਰੈਣਿ ਨ ਵਿਹਾਵੈ ਨੀਦ ਨ ਆਵੈ ਬਿਨੁ ਦੇਖੇ ਗੁਰ ਦਰਬਾਰੇ ਜੀਉ ॥੩॥","t":"moh rain na vihaavai needh na aavai bin dhekhe gur dharabaare jeeau ||3||","pa":"(ਹੇ ਭਾਈ ! ਗੁਰੂ ਦੀ ਸਰਨ ਤੋਂ ਬਿਨਾ ਪਰਮਾਤਮਾ ਨਾਲ ਮਿਲਾਪ ਨਹੀਂ ਹੋ ਸਕਦਾ, ਤਾਹੀਏਂ) ਗੁਰੂ ਦੇ ਦਰਬਾਰ ਦਾ ਦਰਸਨ ਕਰਨ ਤੋਂ ਬਿਨਾ ਮੇਰੀ (ਜ਼ਿੰਦਗੀ ਦੀ) ਰਾਤ (ਸੌਖੀ) ਨਹੀਂ ਲੰਘਦੀ, ਮੇਰੇ ਅੰਦਰ ਸ਼ਾਂਤੀ ਨਹੀਂ ਆਉਂਦੀ ।੩।","hi":"गुरू के दरबार का दर्शन करने के बिना मेरी (जिंदगी की) रात (आसान) नहीं गुजरती~ मेरे अंदर शांति नहीं आती।3।","en":"I cannot endure the night, and sleep does not come, without the Sight of the Beloved Guru's Court. ||3||"},{"g":"ਹਉ ਘੋਲੀ ਜੀਉ ਘੋਲਿ ਘੁਮਾਈ ਤਿਸੁ ਸਚੇ ਗੁਰ ਦਰਬਾਰੇ ਜੀਉ ॥੧॥ ਰਹਾਉ ॥","t":"hau gholee jeeau ghol ghumaiee tis sache gur dharabaare jeeau ||1|| rahaau ||","pa":"ਮੈਂ ਗੁਰੂ ਦੇ ਦਰਬਾਰ ਤੋਂ ਸਦਕੇ ਹਾਂ ਕੁਰਬਾਨ ਹਾਂ ਜੋ ਸਦਾ ਅਟੱਲ ਰਹਿਣ ਵਾਲਾ ਹੈ ।੧।ਰਹਾਉ।","hi":"मैं गुरू के दरबार से सदके हूँ कुर्बान हूँ जो सदैव अटॅल रहने वाला है।1।रहाउ।","en":"I am a sacrifice, my soul is a sacrifice, to that True Court of the Beloved Guru. ||1||Pause||"},{"g":"ਭਾਗੁ ਹੋਆ ਗੁਰਿ ਸੰਤੁ ਮਿਲਾਇਆ ॥","t":"bhaag hoaa gur sa(n)t milaiaa ||","pa":"ਮੇਰੇ ਭਾਗ ਜਾਗ ਪਏ ਹਨ, ਗੁਰੂ ਨੇ ਮੈਨੂੰ ਸ਼ਾਂਤੀ ਦਾ ਸੋਮਾ ਪਰਮਾਤਮਾ ਮਿਲਾ ਦਿੱਤਾ ਹੈ","hi":"मेरे भाग्य जाग पड़े हैं~ गुरू ने मुझे शांति का स्रोत परमात्मा मिला दिया है","en":"By good fortune, I have met the Saint Guru."},{"g":"ਪ੍ਰਭੁ ਅਬਿਨਾਸੀ ਘਰ ਮਹਿ ਪਾਇਆ ॥","t":"prabh abinaasee ghar meh paiaa ||","pa":"(ਗੁਰੂ ਦੀ ਕਿਰਪਾ ਨਾਲ ਉਸ) ਅਬਿਨਾਸੀ ਪ੍ਰਭੂ ਨੂੰ ਮੈਂ ਆਪਣੇ ਹਿਰਦੇ ਵਿਚ ਹੀ ਲੱਭ ਲਿਆ ਹੈ ।","hi":"(गुरू की कृपा से उस) अबिनाशी प्रभू को मैंने अपने हृदय में ढूंढ लिया है।","en":"I have found the Immortal Lord within the home of my own self."},{"g":"ਸੇਵ ਕਰੀ ਪਲੁ ਚਸਾ ਨ ਵਿਛੁੜਾ ਜਨ ਨਾਨਕ ਦਾਸ ਤੁਮਾਰੇ ਜੀਉ ॥੪॥","t":"sev karee pal chasaa na vichhuRaa jan naanak dhaas tumaare jeeau ||4||","pa":"ਹੇ ਦਾਸ ਨਾਨਕ ! (ਆਖ—ਹੇ ਪ੍ਰਭੂ ! ਮਿਹਰ ਕਰ) ਮੈਂ ਤੇਰੇ ਦਾਸਾਂ ਦੀ (ਨਿੱਤ) ਸੇਵਾ ਕਰਦਾ ਰਹਾਂ, (ਤੇਰੇ ਦਾਸਾਂ ਤੋਂ) ਮੈਂ ਇਕ ਪਲ ਭਰ ਭੀ ਨਾਹ ਵਿੱਛੁੜਾਂ, ਇਕ ਚਸਾ-ਭਰ ਭੀ ਨਾਹ ਵਿੱਛੁੜਾਂ ।੪।","hi":"हे दास नानक ! (कह–हे प्रभू ! मेहर कर) मैं तेरे दासों की (नित्य) सेवा करता रहूँ~ (तेरे दासों से) मैं एक पल भर भी ना बिछड़ जाऊँ~ एक रत्ती भर भी ना अलग होऊँ।4।","en":"I will now serve You forever, and I shall never be separated from You, even for an instant. Servant Nanak is Your slave, O Beloved Master. ||4||"},{"g":"ਹਉ ਘੋਲੀ ਜੀਉ ਘੋਲਿ ਘੁਮਾਈ ਜਨ ਨਾਨਕ ਦਾਸ ਤੁਮਾਰੇ ਜੀਉ ॥ ਰਹਾਉ ॥੧॥੮॥","t":"hau gholee jeeau ghol ghumaiee jan naanak dhaas tumaare jeeau || rahaau ||1||8||","pa":"ਹੇ ਦਾਸ ਨਾਨਕ ! (ਆਖ—ਹੇ ਪ੍ਰਭੂ !) ਮੈਂ ਤੇਰੇ ਦਾਸਾਂ ਤੋਂ ਸਦਕੇ ਹਾਂ ਕੁਰਬਾਨ ਹਾਂ ।੧।ਰਹਾਉ।","hi":"हे दास नानक ! (कह– हे प्रभू !) मैं तेरे दासों से सदके हूँ कुर्बान हूँ।1।रहाउ।","en":"I am a sacrifice, my soul is a sacrifice; servant Nanak is Your slave, Lord. ||Pause||1||8||"}],"audioUrl":null,"youtube":null},{"id":"shabad-1748","type":"Shabad","title":"So kiau ma(n)dhaa aakheeaai jit ja(n)meh raajaan ","gurmukhiTitle":"ਸੋ ਕਿਉ ਮੰਦਾ ਆਖੀਐ ਜਿਤੁ ਜੰਮਹਿ ਰਾਜਾਨ","author":"Guru Nanak Dev Ji","raag":"Raag Aasaa","ang":473,"source":"Sri Guru Granth Sahib Ji","nitnem":false,"lines":[{"g":"ਮਃ ੧ ॥","t":"mahalaa pehilaa ||","pa":"","hi":"","en":"First Mehla:"},{"g":"ਭੰਡਿ ਜੰਮੀਐ ਭੰਡਿ ਨਿੰਮੀਐ ਭੰਡਿ ਮੰਗਣੁ ਵੀਆਹੁ ॥","t":"bha(n)dd ja(n)meeaai bha(n)dd ni(n)meeaai bha(n)dd ma(n)gan veeaahu ||","pa":"ਇਸਤ੍ਰੀ ਤੋਂ ਜਨਮ ਲਈਦਾ ਹੈ, ਇਸਤ੍ਰੀ (ਦੇ ਪੇਟ) ਵਿਚ ਹੀ ਪ੍ਰਾਣੀ ਦਾ ਸਰੀਰ ਬਣਦਾ ਹੈ । ਇਸਤ੍ਰੀ ਦੀ (ਹੀ) ਰਾਹੀਂ ਕੁੜਮਾਈ ਤੇ ਵਿਆਹ ਹੁੰਦਾ ਹੈ ।","hi":"स्त्री से जनम लेते हैं।स्त्री (के पेट) में ही प्राणी का शरीर बनता है।स्त्री के (ही) द्वारा मंगनी और विवाह होता है।","en":"From woman, man is born; within woman, man is conceived; to woman he is engaged and married."},{"g":"ਭੰਡਹੁ ਹੋਵੈ ਦੋਸਤੀ ਭੰਡਹੁ ਚਲੈ ਰਾਹੁ ॥","t":"bha(n)ddahu hovai dhosatee bha(n)ddahu chalai raahu ||","pa":"ਇਸਤ੍ਰੀ ਦੀ ਰਾਹੀਂ (ਹੋਰ ਲੋਕਾਂ ਨਾਲ) ਸੰੰਬੰਧ ਬਣਦਾ ਹੈ । ਤੇ ਇਸਤ੍ਰੀ ਤੋਂ ਹੀ (ਜਗਤ ਦੀ ਉਤਪੱਤੀ ਦਾ) ਰਸਤਾ ਚੱਲਦਾ ਹੈ ।","hi":"स्त्री के द्वारा (और लोगों से) संबंध बनता है और स्त्री से ही (जगत की उत्पक्ति का) रास्ता चलता है।","en":"Woman becomes his friend; through woman, the future generations come."},{"g":"ਭੰਡੁ ਮੁਆ ਭੰਡੁ ਭਾਲੀਐ ਭੰਡਿ ਹੋਵੈ ਬੰਧਾਨੁ ॥","t":"bha(n)dd muaa bha(n)dd bhaaleeaai bha(n)dd hovai ba(n)dhaan ||","pa":"ਜੇ ਇਸਤ੍ਰੀ ਮਰ ਜਾਏ ਤਾਂ ਹੋਰ ਇਸਤ੍ਰੀ ਦੀ ਭਾਲ ਕਰੀਦੀ ਹੈ, ਇਸਤ੍ਰੀ ਤੋਂ ਹੀ (ਹੋਰਨਾਂ ਨਾਲ) ਰਿਸ਼ਤੇਦਾਰੀ ਬਣਦੀ ਹੈ ।","hi":"अगर स्त्री मर जाए तो और स्त्री की तलाश करते हैं।स्त्री से ही (औरों से) रिश्तेदारी बनती है।","en":"When his woman dies, he seeks another woman; to woman he is bound."},{"g":"ਸੋ ਕਿਉ ਮੰਦਾ ਆਖੀਐ ਜਿਤੁ ਜੰਮਹਿ ਰਾਜਾਨ ॥","t":"so kiau ma(n)dhaa aakheeaai jit ja(n)meh raajaan ||","pa":"ਜਿਸ ਇਸਤ੍ਰੀ (ਜਾਤੀ) ਤੋਂ ਰਾਜੇ (ਭੀ) ਜੰਮਦੇ ਹਨ, ਉਸ ਨੂੰ ਮੰਦਾ ਆਖਣਾ ਠੀਕ ਨਹੀਂ ਹੈ ।","hi":"जिस स्त्री (जाति) से राजा (भी) पैदा होते हैं।उसे बुरा कहना ठीक नहीं है।","en":"So why call her bad? From her, kings are born."},{"g":"ਭੰਡਹੁ ਹੀ ਭੰਡੁ ਊਪਜੈ ਭੰਡੈ ਬਾਝੁ ਨ ਕੋਇ ॥","t":"bha(n)ddahu hee bha(n)dd uoopajai bha(n)ddai baajh na koi ||","pa":"ਇਸਤ੍ਰੀ ਤੋਂ ਹੀ ਇਸਤ੍ਰੀ ਪੈਦਾ ਹੁੰਦੀ ਹੈ (ਜਗਤ ਵਿਚ) ਕੋਈ ਜੀਵ ਇਸਤ੍ਰੀ ਤੋਂ ਬਿਨਾ ਪੈਦਾ ਨਹੀਂ ਹੋ ਸਕਦਾ ।","hi":"स्त्री से ही स्त्री पैदा होती है (जगत में) कोई भी जीव स्त्री के बिना पैदा नहीं हो सकता।","en":"From woman, woman is born; without woman, there would be no one at all."},{"g":"ਨਾਨਕ ਭੰਡੈ ਬਾਹਰਾ ਏਕੋ ਸਚਾ ਸੋਇ ॥","t":"naanak bha(n)ddai baaharaa eko sachaa soi ||","pa":"ਹੇ ਨਾਨਕ! ਕੇਵਲ ਇਕ ਸੱਚਾ ਪ੍ਰਭੂ ਹੀ ਹੈ, ਜੋ ਇਸਤ੍ਰੀ ਤੋਂ ਨਹੀਂ ਜੰਮਿਆ ।","hi":"हे नानक ! केवल एक सच्चा प्रभू ही है।जो स्त्री से पैदा नहीं हुआ।","en":"O Nanak, only the True Lord is without a woman."},{"g":"ਜਿਤੁ ਮੁਖਿ ਸਦਾ ਸਾਲਾਹੀਐ ਭਾਗਾ ਰਤੀ ਚਾਰਿ ॥","t":"jit mukh sadhaa saalaaheeaai bhaagaa ratee chaar ||","pa":"(ਭਾਵੇਂ ਮਨੁੱਖ ਹੋਵੇ, ਭਾਵੇਂ ਇਸਤ੍ਰੀ, ਜੋ ਭੀ) ਆਪਣੇ ਮੂੰਹ ਨਾਲ ਸਦਾ ਪ੍ਰਭੂ ਦੇ ਗੁਣ ਗਾਉਂਦਾ ਹੈ, ਉਸ ਦੇ ਮੱਥੇ ਉੱੱਤੇ ਭਾਗਾਂ ਦੀ ਮਣੀ ਹੈ, ਭਾਵ ਉਹਦਾ ਮੱਥਾ ਭਾਗਾਂ ਵਾਲਾ ਹੈ ।","hi":"(चाहे मनुष्य हो।चाहे स्त्री।जो भी) अपने मुंह से सदा प्रभू के गुण गाता है।","en":"That mouth which praises the Lord continually is blessed and beautiful."},{"g":"ਨਾਨਕ ਤੇ ਮੁਖ ਊਜਲੇ ਤਿਤੁ ਸਚੈ ਦਰਬਾਰਿ ॥੨॥","t":"naanak te mukh uoojale tit sachai dharabaar ||2||","pa":"ਹੇ ਨਾਨਕ! ਉਹੀ ਮੁਖ ਉਸੇ ਸੱਚੇ ਪ੍ਰਭੂ ਦੇ ਦਰਬਾਰ ਵਿਚ ਸੋਹਣੇ ਲੱਗਦੇ ਹਨ ।੨।","hi":"उसके माथे पे भाग्यों की मणि है।भाव उनका माथा भाग्योंशाली है।हे नानक ! वही मुख उस सच्चे प्रभू के दरबार में सुंदर लगते हैं।","en":"O Nanak, those faces shall be radiant in the Court of the True Lord. ||2||"}],"audioUrl":null,"youtube":null},{"id":"shabad-4892","type":"Shabad","title":"Aval aleh noor upaiaa kudharat ke sabh ba(n)dhe ","gurmukhiTitle":"ਅਵਲਿ ਅਲਹ ਨੂਰੁ ਉਪਾਇਆ ਕੁਦਰਤਿ ਕੇ ਸਭ ਬੰਦੇ","author":"Bhagat Kabir Ji","raag":"Raag Prabhaatee","ang":1349,"source":"Sri Guru Granth Sahib Ji","nitnem":false,"lines":[{"g":"ਪ੍ਰਭਾਤੀ ॥","t":"prabhaatee ||","pa":"","hi":"","en":"Prabhaatee:"},{"g":"ਅਵਲਿ ਅਲਹ ਨੂਰੁ ਉਪਾਇਆ ਕੁਦਰਤਿ ਕੇ ਸਭ ਬੰਦੇ ॥","t":"aval aleh noor upaiaa kudharat ke sabh ba(n)dhe ||","pa":"ਸਭ ਤੋਂ ਪਹਿਲਾਂ ਖ਼ੁਦਾ ਦਾ ਨੂਰ ਹੀ ਹੈ ਜਿਸ ਨੇ (ਜਗਤ) ਪੈਦਾ ਕੀਤਾ ਹੈ, ਇਹ ਸਾਰੇ ਜੀਅ-ਜੰਤ ਰੱਬ ਦੀ ਕੁਦਰਤ ਦੇ ਹੀ ਬਣਾਏ ਹੋਏ ਹਨ । ਇਕ ਪ੍ਰਭੂ ਦੀ ਹੀ ਜੋਤ ਤੋਂ ਸਾਰਾ ਜਗਤ ਪੈਦਾ ਹੋਇਆ ਹੈ ।","hi":"सबसे पहले ख़ुदा का नूर ही है जिसने (जगत) पैदा किया है। यह सारे जीव-जंतु रॅब के ही बनाए हुए हैं।","en":"First, Allah created the Light; then, by His Creative Power, He made all mortal beings."},{"g":"ਏਕ ਨੂਰ ਤੇ ਸਭੁ ਜਗੁ ਉਪਜਿਆ ਕਉਨ ਭਲੇ ਕੋ ਮੰਦੇ ॥੧॥","t":"ek noor te sabh jag upajiaa kaun bhale ko ma(n)dhe ||1||","pa":"(ਤਾਂ ਫਿਰ ਕਿਸੇ ਜਾਤ ਮਜ਼ਹਬ ਦੇ ਭੁਲੇਖੇ ਵਿਚ ਪੈ ਕੇ) ਕਿਸੇ ਨੂੰ ਚੰਗਾ ਤੇ ਕਿਸੇ ਨੂੰ ਮੰਦਾ ਨਾਹ ਸਮਝੋ ।੧।","hi":"एक प्रभू की ही जोति से सारा जगत पैदा होया हुआ है। (तो फिर किसी जाति-मज़हब के भुलेखे में पड़ कर) किसी को अच्छा और किसी को बुरा ना समझो। 1।","en":"From the One Light, the entire universe welled up. So who is good, and who is bad? ||1||"},{"g":"ਲੋਗਾ ਭਰਮਿ ਨ ਭੂਲਹੁ ਭਾਈ ॥","t":"logaa bharam na bhoolahu bhaiee ||","pa":"ਹੇ ਲੋਕੋ! ਹੇ ਭਾਈ! (ਰੱਬ ਦੀ ਹਸਤੀ ਬਾਰੇ) ਕਿਸੇ ਭੁਲੇਖੇ ਵਿਚ ਪੈ ਕੇ ਖ਼ੁਆਰ ਨਾਹ ਹੋਵੋ ।","hi":"हे लोगो ! हे भाई ! (रॅब की हस्ती के बारे) किसी भूलेखे में पड़ कर दुखी मत होवो।","en":"O people, O Siblings of Destiny, do not wander deluded by doubt."},{"g":"ਖਾਲਿਕੁ ਖਲਕ ਖਲਕ ਮਹਿ ਖਾਲਿਕੁ ਪੂਰਿ ਰਹਿਓ ਸ੍ਰਬ ਠਾਂਈ ॥੧॥ ਰਹਾਉ ॥","t":"khaalik khalak khalak meh khaalik poor rahio srab Thaa(n)iee ||1|| rahaau ||","pa":"ਉਹ ਰੱਬ ਸਾਰੀ ਖ਼ਲਕਤ ਨੂੰ ਪੈਦਾ ਕਰਨ ਵਾਲਾ ਹੈ ਤੇ ਸਾਰੀ ਖ਼ਲਕਤ ਵਿਚ ਮੌਜੂਦ ਹੈ, ਉਹ ਸਭ ਥਾਂ ਭਰਪੂਰ ਹੈ ।੧।ਰਹਾਉ।","hi":"वह रॅब सारी ख़लकत को पैदा करने वाला है और सारी ख़लकत़ में मौजूद है वह सब जगह भरपूर है। 1। रहाउ।","en":"The Creation is in the Creator, and the Creator is in the Creation, totally pervading and permeating all places. ||1||Pause||"},{"g":"ਮਾਟੀ ਏਕ ਅਨੇਕ ਭਾਂਤਿ ਕਰਿ ਸਾਜੀ ਸਾਜਨਹਾਰੈ ॥","t":"maaTee ek anek bhaa(n)t kar saajee saajanahaarai ||","pa":"ਸਿਰਜਨਹਾਰ ਨੇ ਇੱਕੋ ਹੀ ਮਿੱਟੀ ਤੋਂ (ਭਾਵ, ਇੱਕੋ ਜਿਹੇ ਹੀ ਤੱਤਾਂ ਤੋਂ) ਅਨੇਕਾਂ ਕਿਸਮਾਂ ਦੇੁ ਜੀਆ-ਜੰਤ ਪੈਦਾ ਕਰ ਦਿੱਤੇ ਹਨ ।","hi":"सृजनहार ने एक ही मिट्टी से (भाव। एक जैसे तत्वों से) अनेकों किस्मों के जीव-जन्तु पैदा कर दिए हैं।","en":"The clay is the same, but the Fashioner has fashioned it in various ways."},{"g":"ਨਾ ਕਛੁ ਪੋਚ ਮਾਟੀ ਕੇ ਭਾਂਡੇ ਨਾ ਕਛੁ ਪੋਚ ਕੁੰਭਾਰੈ ॥੨॥","t":"naa kachh poch maaTee ke bhaa(n)dde naa kachh poch ku(n)bhaarai ||2||","pa":"(ਜਿੱਥੋਂ ਤਕ ਜੀਵਾਂ ਦੇ ਅਸਲੇ ਦਾ ਸੰਬੰਧ ਹੈ) ਨਾਹ ਇਹਨਾਂ ਮਿੱਟੀ ਦੇ ਭਾਂਡਿਆਂ (ਭਾਵ, ਜੀਵਾਂ) ਵਿਚ ਕੋਈ ਊਣਤਾ ਹੈ, ਤੇ ਨਾਹ (ਇਹਨਾਂ ਭਾਂਡਿਆਂ ਦੇ ਬਣਾਣ ਵਾਲੇ) ਘੁਮਿਆਰ ਵਿਚ ।੨।","hi":"(जहाँ तक जीवों की अस्लियत का खरे होने का सम्बंध है) ना इन मिट्टी के बर्तनों (भाव। जीवों) में कोई कमी है। और ना (इन बर्तनों के बनाने वाले) कुम्हार में। 2।","en":"There is nothing wrong with the pot of clay - there is nothing wrong with the Potter. ||2||"},{"g":"ਸਭ ਮਹਿ ਸਚਾ ਏਕੋ ਸੋਈ ਤਿਸ ਕਾ ਕੀਆ ਸਭੁ ਕਛੁ ਹੋਈ ॥","t":"sabh meh sachaa eko soiee tis kaa keeaa sabh kachh hoiee ||","pa":"ਉਹ ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲਾ ਪ੍ਰਭੂ ਸਭ ਜੀਵਾਂ ਵਿਚ ਵੱਸਦਾ ਹੈ । ਜੋ ਕੁਝ ਜਗਤ ਵਿਚ ਹੋ ਰਿਹਾ ਹੈ, ਉਸੇ ਦਾ ਕੀਤਾ ਹੋ ਰਿਹਾ ਹੈ ।","hi":"वह सदा कायम रहने वाला प्रभू सब जीवों में बसता है। जो कुछ जगत में हो रहा है। उसी का किया हुआ हो रहा है।","en":"The One True Lord abides in all; by His making, everything is made."},{"g":"ਹੁਕਮੁ ਪਛਾਨੈ ਸੁ ਏਕੋ ਜਾਨੈ ਬੰਦਾ ਕਹੀਐ ਸੋਈ ॥੩॥","t":"hukam pachhaanai su eko jaanai ba(n)dhaa kaheeaai soiee ||3||","pa":"ਉਹੀ ਮਨੁੱਖ ਰੱਬ ਦਾ (ਪਿਆਰਾ) ਬੰਦਾ ਕਿਹਾ ਜਾ ਸਕਦਾ ਹੈ, ਜੋ ਉਸ ਦੀ ਰਜ਼ਾ ਨੂੰ ਪਛਾਣਦਾ ਹੈ ਤੇ ਉਸ ਇਕ ਨਾਲ ਸਾਂਝ ਪਾਂਦਾ ਹੈ ।੩।","hi":"वही मनुष्य रॅब का (प्यारा) बँदा कहा जा सकता है। जो उसकी रज़ा को पहचानता है और उस एक के साथ सांझ डालता है। 3।","en":"Whoever realizes the Hukam of His Command, knows the One Lord. He alone is said to be the Lord's slave. ||3||"},{"g":"ਅਲਹੁ ਅਲਖੁ ਨ ਜਾਈ ਲਖਿਆ ਗੁਰਿ ਗੁੜੁ ਦੀਨਾ ਮੀਠਾ ॥","t":"alahu alakh na jaiee lakhiaa gur guR dheenaa meeThaa ||","pa":"ਉਹ ਰੱਬ ਐਸਾ ਹੈ ਜਿਸ ਦਾ ਮੁਕੰਮਲ ਸਰੂਪ ਬਿਆਨ ਤੋਂ ਪਰੇ ਹੈ, ਉਸ ਦੇ ਗੁਣ ਕਹੇ ਨਹੀਂ ਜਾ ਸਕਦੇ । ਕਬੀਰ ਆਖਦਾ ਹੈ—ਮੇਰੇ ਗੁਰੂ ਨੇ (ਪ੍ਰਭੂ ਦੇ ਗੁਣਾਂ ਦੀ ਸੂਝ-ਰੂਪ) ਮਿੱਠਾ ਗੁੜ ਮੈਨੂੰ ਦਿੱਤਾ ਹੈ (ਜਿਸ ਦਾ ਸੁਆਦ ਤਾਂ ਮੈਂ ਨਹੀਂ ਦੱਸ ਸਕਦਾ,","hi":"वह रॅब ऐसा है जिसका मुकम्मल स्वरूप बयान से परे है। उसके गुण कहे नहीं जा सकते।","en":"The Lord Allah is Unseen; He cannot be seen. The Guru has blessed me with this sweet molasses."},{"g":"ਕਹਿ ਕਬੀਰ ਮੇਰੀ ਸੰਕਾ ਨਾਸੀ ਸਰਬ ਨਿਰੰਜਨੁ ਡੀਠਾ ॥੪॥੩॥","t":"keh kabeer meree sa(n)kaa naasee sarab nira(n)jan ddeeThaa ||4||3||","pa":"ਪਰ) ਮੈਂ ਉਸ ਮਾਇਆ ਰਹਿਤ ਪ੍ਰਭੂ ਨੂੰ ਹਰ ਥਾਂ ਵੇਖ ਲਿਆ ਹੈ, ਮੈਨੂੰ ਇਸ ਵਿਚ ਕੋਈ ਸ਼ੱਕ ਨਹੀਂ ਰਿਹਾ (ਮੇਰਾ ਅੰਦਰ ਕਿਸੇ ਜਾਤ ਜਾਂ ਮਜ਼ਹਬ ਦੇ ਬੰਦਿਆਂ ਦੀ ਉੱਚਤਾ ਜਾਂ ਨੀਚਤਾ ਦਾ ਕਰਮ ਨਹੀਂ ਰਿਹਾ) ।੪।੩।","hi":"कबीर कहता है- मेरे गुरू ने (प्रभू के गुणों की सूझ रूपी) मीठा गुड़ मुझे दिया है (जिसका स्वाद तो मैं नहीं बता सकता। पर) मैंने उस माया-रहित प्रभू को हर जगह देख लिया है। मुझे इस में कोई शक नहीं रहा (मेरा अंदर किसी जाति अथवा मज़हब के लोगों की उच्चता व नीचता का कर्म नहीं रहा)। 4। 3।","en":"Says Kabeer, my anxiety and fear have been taken away; I see the Immaculate Lord pervading everywhere. ||4||3||"}],"audioUrl":null,"youtube":null},{"id":"shabad-51","type":"Shabad","title":"Gagan mai thaal rav cha(n)dh dheepak bane taarikaa ma(n)ddal janak motee ","gurmukhiTitle":"ਗਗਨ ਮੈ ਥਾਲੁ ਰਵਿ ਚੰਦੁ ਦੀਪਕ ਬਨੇ ਤਾਰਿਕਾ ਮੰਡਲ ਜਨਕ ਮੋਤੀ","author":"Guru Nanak Dev Ji","raag":"Sohila","ang":13,"source":"Sri Guru Granth Sahib Ji","nitnem":false,"lines":[{"g":"ਰਾਗੁ ਧਨਾਸਰੀ ਮਹਲਾ ੧ ॥","t":"raag dhanaasaree mahalaa pehilaa ||","pa":"","hi":"रागु धनासरी महला १ ॥","en":"Raag Dhanaasaree, First Mehla:"},{"g":"ਗਗਨ ਮੈ ਥਾਲੁ ਰਵਿ ਚੰਦੁ ਦੀਪਕ ਬਨੇ ਤਾਰਿਕਾ ਮੰਡਲ ਜਨਕ ਮੋਤੀ ॥","t":"gagan mai thaal rav cha(n)dh dheepak bane taarikaa ma(n)ddal janak motee ||","pa":"ਸਾਰਾ ਆਕਾਸ਼ (ਮਾਨੋ) ਥਾਲ ਹੈ । ਸੂਰਜ ਤੇ ਚੰਦ (ਉਸ ਥਾਲ ਵਿਚ) ਦੀਵੇ ਬਣੇ ਹੋਏ ਹਨ । ਤਾਰਿਆਂ ਦੇ ਸਮੂਹ, ਮਾਨੋ, (ਥਾਲ ਵਿਚ) ਮੋਤੀ ਰੱਖੇ ਹੋਏ ਹਨ ।","hi":"सारा आकाश (जैसे कि) थाल है। सूरज और चाँद (उस थाल में) दिये बने हुए हैं। तारों के समूह~ जैसे~ थाल में मोती रखे हुए हैं।","en":"Upon that cosmic plate of the sky, the sun and the moon are the lamps. The stars and their orbs are the studded pearls."},{"g":"ਧੂਪੁ ਮਲਆਨਲੋ ਪਵਣੁ ਚਵਰੋ ਕਰੇ ਸਗਲ ਬਨਰਾਇ ਫੂਲੰਤ ਜੋਤੀ ॥੧॥","t":"dhoop malaanalo pavan chavaro kare sagal banarai foola(n)t jotee ||1||","pa":"ਮਲਯ ਪਰਬਤ ਵਲੋਂ ਆਉਣ ਵਾਲੀ ਹਵਾ, ਮਾਨੋ, ਧੂਪ (ਧੁਖ ਰਿਹਾ) ਹੈ । ਹਵਾ ਚੌਰ ਕਰ ਰਹੀ ਹੈ । ਸਾਰੀ ਬਨਸਪਤੀ ਜੋਤਿ-ਰੂਪ (ਪ੍ਰਭੂ ਦੀ ਆਰਤੀ) ਵਾਸਤੇ ਫੁੱਲ ਦੇ ਰਹੀ ਹੈ ।੧।","hi":"मलय पर्वत से आने वाली हवा~ जैसे धूप (धूणे की सुगंध) है। हवा चौर कर रही है। सारी बनस्पति जोति-रूप (प्रभू की आरती) वास्ते फूल दे रही है।1।","en":"The fragrance of sandalwood in the air is the temple incense, and the wind is the fan. All the plants of the world are the altar flowers in offering to You, O Luminous Lord. ||1||"},{"g":"ਕੈਸੀ ਆਰਤੀ ਹੋਇ ॥ ਭਵ ਖੰਡਨਾ ਤੇਰੀ ਆਰਤੀ ॥","t":"kaisee aaratee hoi || bhav kha(n)ddanaa teree aaratee ||","pa":"ਹੇ ਜੀਵਾਂ ਦੇ ਜਨਮ ਮਰਨ ਨਾਸ ਕਰਨ ਵਾਲੇ ! (ਕੁਦਰਤਿ ਵਿਚ) ਤੇਰੀ ਕੈਸੀ ਸੁੰਦਰ ਆਰਤੀ ਹੋ ਰਹੀ ਹੈ !","hi":"कैसी सुंदर तेरी आरती हो रही है ! हे जीवों के जनम~ मरन~ नाश करने वाले! (कुदरति में) तेरी आरती हो रही है","en":"What a beautiful Aartee, lamp-lit worship service this is! O Destroyer of Fear, this is Your Ceremony of Light."},{"g":"ਅਨਹਤਾ ਸਬਦ ਵਾਜੰਤ ਭੇਰੀ ॥੧॥ ਰਹਾਉ ॥","t":"anahataa sabadh vaaja(n)t bheree ||1|| rahaau ||","pa":"(ਸਭ ਜੀਵਾਂ ਵਿਚ ਰੁਮਕ ਰਹੀ) ਇੱਕੋ ਜੀਵਨ-ਰੌ, ਮਾਨੋ, ਤੇਰੀ ਆਰਤੀ ਵਾਸਤੇ ਨਾਗਾਰੇ ਵੱਜ ਰਹੇ ਹਨ ।੧।ਰਹਾਉ।","hi":"सभ जीवों में चल रहीं) एक ही जीवन तरंगें~ मानों तेरी आरती के वास्ते नगारे बज रहे है।1।रहाउ।","en":"The Unstruck Sound-current of the Shabad is the vibration of the temple drums. ||1||Pause||"},{"g":"ਸਹਸ ਤਵ ਨੈਨ ਨਨ ਨੈਨ ਹਹਿ ਤੋਹਿ ਕਉ ਸਹਸ ਮੂਰਤਿ ਨਨਾ ਏਕ ਤੋੁਹੀ ॥","t":"sahas tav nain nan nain heh toh kau sahas moorat nanaa ek tuohee ||","pa":"(ਸਭ ਜੀਵਾਂ ਵਿਚ ਵਿਆਪਕ ਹੋਣ ਕਰਕੇ) ਹਜ਼ਾਰਾਂ ਤੇਰੀਆਂ ਅੱਖਾਂ ਹਨ (ਪਰ, ਨਿਰਾਕਾਰ ਹੋਣ ਕਰਕੇ, ਹੇ ਪ੍ਰਭੂ !) ਤੇਰੀਆਂ ਕੋਈ ਅੱਖਾਂ ਨਹੀਂ । ਹਜ਼ਾਰਾਂ ਤੇਰੀਆਂ ਸ਼ਕਲਾਂ ਹਨ, ਪਰ ਤੇਰੀ ਕੋਈ ਭੀ ਸ਼ਕਲ ਨਹੀਂ ਹੈ ।","hi":"(सभ जीवों में व्यापक होने के कारण) हजारों तेरी आँखें हैं (पर~ निराकार होने की वजह से~ हे प्रभू) तेरी कोई आँख नहीं। हजारों तेरी शक्लें हैं~ पर तेरी कोई भी शक्ल नहीं है।","en":"You have thousands of eyes, and yet You have no eyes. You have thousands of forms, and yet You do not have even one."},{"g":"ਸਹਸ ਪਦ ਬਿਮਲ ਨਨ ਏਕ ਪਦ ਗੰਧ ਬਿਨੁ ਸਹਸ ਤਵ ਗੰਧ ਇਵ ਚਲਤ ਮੋਹੀ ॥੨॥","t":"sahas padh bimal nan ek padh ga(n)dh bin sahas tav ga(n)dh iv chalat mohee ||2||","pa":"ਹਜ਼ਾਰਾਂ ਤੇਰੇ ਸੋਹਣੇ ਪੈਰ ਹਨ, (ਪਰ ਨਿਰਾਕਾਰ ਹੋਣ ਕਰਕੇ) ਤੇਰਾ ਇੱਕ ਭੀ ਪੈਰ ਨਹੀਂ । ਹਜ਼ਾਰਾਂ ਤੇਰੇ ਨੱਕ ਹਨ, ਪਰ ਤੂੰ ਨੱਕ ਤੋਂ ਬਿਨਾ ਹੀ ਹੈਂ । ਤੇਰੇ ਅਜੇਹੇ ਕੌਤਕਾਂ ਨੇ ਮੈਨੂੰ ਹੈਰਾਨ ਕੀਤਾ ਹੋਇਆ ਹੈ ।੧।","hi":"हजारों तेरे सुंदर पैर हैं (पर निराकार होने के कारण) तेरा एक भी पैर नहीं। हजारों तेरे नाक हैं~ पर तू नाक के बिना ही है। तेरे ऐसे चमत्कारों ने मुझे हैरान किया हुआ है।1।","en":"You have thousands of Lotus Feet, and yet You do not have even one foot. You have no nose, but you have thousands of noses. This Play of Yours entrances me. ||2||"},{"g":"ਸਭ ਮਹਿ ਜੋਤਿ ਜੋਤਿ ਹੈ ਸੋਇ ॥","t":"sabh meh jot jot hai soi ||","pa":"ਸਾਰੇ ਜੀਵਾਂ ਵਿਚ ਇਕੋ ਉਹੀ ਪਰਮਾਤਮਾ ਦੀ ਜੋਤੀ ਵਰਤ ਰਹੀ ਹੈ ।","hi":"सारे जीवों में एक वही परमात्मा की ज्योति बरत रही है।","en":"Amongst all is the Light-You are that Light."},{"g":"ਤਿਸ ਦੈ ਚਾਨਣਿ ਸਭ ਮਹਿ ਚਾਨਣੁ ਹੋਇ ॥","t":"tis dhai chaanan sabh meh chaanan hoi ||","pa":"ਉਸ ਜੋਤਿ ਦੇ ਪਰਕਾਸ਼ ਨਾਲ ਸਾਰੇ ਜੀਵਾਂ ਵਿਚ ਚਾਨਣ (ਸੂਝ-ਬੂਝ) ਹੈ ।","hi":"उस ज्योति के प्रकाश से सारे जीवों में प्रकाश (सूझ-बूझ) है।","en":"By this Illumination, that Light is radiant within all."},{"g":"ਗੁਰ ਸਾਖੀ ਜੋਤਿ ਪਰਗਟੁ ਹੋਇ ॥","t":"gur saakhee jot paragaT hoi ||","pa":"ਪਰ ਇਸ ਜੋਤਿ ਦਾ ਗਿਆਨ ਗੁਰੂ ਦੀ ਸਿੱਖਿਆ ਨਾਲ ਹੀ ਹੁੰਦਾ ਹੈ । (ਗੁਰੂ ਰਾਹੀਂ ਇਹ ਸਮਝ ਪੈਂਦੀ ਹੈ ਕਿ ਹਰੇਕ ਦੇ ਅੰਦਰ ਪਰਮਾਤਮਾ ਦੀ ਜੋਤਿ ਹੈ) ।","hi":"पर~ इस ज्योति का ज्ञान गुरू की शिक्षा से ही होता है।","en":"Through the Guru's Teachings, the Light shines forth."},{"g":"ਜੋ ਤਿਸੁ ਭਾਵੈ ਸੁ ਆਰਤੀ ਹੋਇ ॥੩॥","t":"jo tis bhaavai su aaratee hoi ||3||","pa":"(ਇਸ ਸਰਬ-ਵਿਆਪਕ ਜੋਤਿ ਦੀ) ਆਰਤੀ ਇਹ ਹੈ ਕਿ ਜੋ ਕੁਝ ਉਸ ਦੀ ਰਜ਼ਾ ਵਿਚ ਹੋ ਰਿਹਾ ਹੈ, ਉਹ ਜੀਵ ਨੂੰ ਚੰਗਾ ਲੱਗੇ (ਪ੍ਰਭੂ ਦੀ ਰਜ਼ਾ ਵਿਚ ਤੁਰਨਾ ਪ੍ਰਭੂ ਦੀ ਆਰਤੀ ਕਰਨੀ ਹੈ) ।੩।","hi":"(गुरू के द्वारा ही ये समझ पड़ती है कि हरेक के अंदर परमात्मा की ज्योति है) (इस सर्व-व्यापक ज्योति की) आरती ये है कि जो कुछ भी उसकी रजा में हो रहा है~ वह जीव को अच्छा लगे (प्रभू की रजा में रहना ही प्रभू की आरती करना है)।3।","en":"That which is pleasing to Him is the lamp-lit worship service. ||3||"},{"g":"ਹਰਿ ਚਰਣ ਕਵਲ ਮਕਰੰਦ ਲੋਭਿਤ ਮਨੋ ਅਨਦਿਨੋੁ ਮੋਹਿ ਆਹੀ ਪਿਆਸਾ ॥","t":"har charan kaval makara(n)dh lobhit mano anadhinuo moh aahee piaasaa ||","pa":"ਹੇ ਹਰੀ ! ਤੇਰੇ ਚਰਨ-ਰੂਪ ਕੌਲ-ਫੱੁਲਾਂ ਦੇ ਰਸ ਲਈ ਮੇਰਾ ਮਨ ਲਲਚਾਂਦਾ ਹੈ, ਹਰ ਰੋਜ਼ ਮੈਨੂੰ ਇਸੇ ਰਸ ਦੀ ਪਿਆਸ ਲੱਗੀ ਹੋਈ ਹੈ ।","hi":"हे हरी! तुम्हारे चरन-रूपी कमल फूलों के लिए मेरा मन ललचाता है~ हर रोज मुझे इस रस की प्यास लगी हुई है।","en":"My mind is enticed by the honey-sweet Lotus Feet of the Lord. Day and night, I thirst for them."},{"g":"ਕ੍ਰਿਪਾ ਜਲੁ ਦੇਹਿ ਨਾਨਕ ਸਾਰਿੰਗ ਕਉ ਹੋਇ ਜਾ ਤੇ ਤੇਰੈ ਨਾਇ ਵਾਸਾ ॥੪॥੩॥","t":"kirapaa jal dheh naanak saari(n)g kau hoi jaa te terai nai vaasaa ||4||3||","pa":"ਮੈਨੂੰ ਨਾਨਕ ਪਪੀਹੇ ਨੂੰ ਆਪਣੀ ਮਿਹਰ ਦਾ ਜਲ ਦੇਹ, ਜਿਸ (ਦੀ ਬਰਕਤਿ) ਨਾਲ ਮੈਂ ਤੇਰੇ ਨਾਮ ਵਿਚ ਟਿਕਿਆ ਰਹਾਂ ।੪।੩।","hi":"मुझ नानक पपीहे को अपनी मेहर का जल दे~ जिस (की बरकति) से मैं तेरे नाम में टिका रहूँ।4।3।","en":"Bestow the Water of Your Mercy upon Nanak, the thirsty song-bird, so that he may come to dwell in Your Name. ||4||3||"}],"audioUrl":null,"youtube":null},{"id":"shabad-4713","type":"Shabad","title":"Naa ko bairee nahee bigaanaa sagal sa(n)g ham kau ban aaiee ","gurmukhiTitle":"ਨਾ ਕੋ ਬੈਰੀ ਨਹੀ ਬਿਗਾਨਾ ਸਗਲ ਸੰਗਿ ਹਮ ਕਉ ਬਨਿ ਆਈ","author":"Guru Arjan Dev Ji","raag":"Raag Kaanraa","ang":1299,"source":"Sri Guru Granth Sahib Ji","nitnem":false,"lines":[{"g":"ਕਾਨੜਾ ਮਹਲਾ ੫ ॥","t":"kaanaRaa mahalaa panjavaa ||","pa":"","hi":"हे नानक ! गुरू की कृपा से (नाम-दवाई खा के वे सिर्फ खुद ही नहीं तैरते। उनकी) कुल के लोग भी (संसार-समुंद्र से पार) लांघ जाते हैं। उन पर माया का प्रभाव नहीं पड़ता। 4। 7।","en":"Kaanraa, Fifth Mehla:"},{"g":"ਬਿਸਰਿ ਗਈ ਸਭ ਤਾਤਿ ਪਰਾਈ ॥","t":"bisar giee sabh taat paraiee ||","pa":"(ਤਦੋਂ ਤੋਂ) ਦੂਜਿਆਂ ਦਾ ਸੁਖ ਵੇਖ ਕੇ ਅੰਦਰੇ ਅੰਦਰ ਸੜਨ ਦੀ ਸਾਰੀ ਆਦਤ ਭੁੱਲ ਗਈ ਹੈ ।੧।ਰਹਾਉ।","hi":"","en":"I have totally forgotten my jealousy of others,"},{"g":"ਜਬ ਤੇ ਸਾਧਸੰਗਤਿ ਮੋਹਿ ਪਾਈ ॥੧॥ ਰਹਾਉ ॥","t":"jab te saadhasa(n)gat moh paiee ||1|| rahaau ||","pa":"ਹੇ ਭਾਈ! ਜਦੋਂ ਤੋਂ ਮੈਂ ਗੁਰੂ ਦੀ ਸੰਗਤਿ ਪ੍ਰਾਪਤ ਕੀਤੀ ਹੈ,","hi":"(तब से) दूसरों का सुख देख के अंदर-अंदर से जलने की आदत भूल गई है -","en":"since I found the Saadh Sangat, the Company of the Holy. ||1||Pause||"},{"g":"ਨਾ ਕੋ ਬੈਰੀ ਨਹੀ ਬਿਗਾਨਾ ਸਗਲ ਸੰਗਿ ਹਮ ਕਉ ਬਨਿ ਆਈ ॥੧॥","t":"naa ko bairee nahee bigaanaa sagal sa(n)g ham kau ban aaiee ||1||","pa":"ਹੇ ਭਾਈ! (ਹੁਣ) ਮੈਨੂੰ ਕੋਈ ਵੈਰੀ ਨਹੀਂ ਦਿੱਸਦਾ, ਕੋਈ ਓਪਰਾ ਨਹੀਂ ਦਿੱਸਦਾ; ਸਭਨਾਂ ਨਾਲ ਮੇਰਾ ਪਿਆਰ ਬਣਿਆ ਹੋਇਆ ਹੈ ।੧।","hi":"हे भाई ! जब से मैंने गुरू की संगति प्राप्त की है। । 1। रहाउ।","en":"No one is my enemy, and no one is a stranger. I get along with everyone. ||1||"},{"g":"ਜੋ ਪ੍ਰਭ ਕੀਨੋ ਸੋ ਭਲ ਮਾਨਿਓ ਏਹ ਸੁਮਤਿ ਸਾਧੂ ਤੇ ਪਾਈ ॥੨॥","t":"jo prabh keeno so bhal maanio eh sumat saadhoo te paiee ||2||","pa":"ਹੇ ਭਾਈ! (ਹੁਣ) ਜੋ ਕੁਝ ਪਰਮਾਤਮਾ ਕਰਦਾ ਹੈ, ਮੈਂ ਉਸ ਨੂੰ (ਸਭ ਜੀਵਾਂ ਲਈ) ਭਲਾ ਹੀ ਮੰਨਦਾ ਹਾਂ । ਇਹ ਚੰਗੀ ਅਕਲ ਮੈਂ (ਆਪਣੇ) ਗੁਰੂ ਪਾਸੋਂ ਸਿੱਖੀ ਹੈ ।੨।","hi":"हे भाई ! (अब) मुझे कोई वैरी नहीं दिखता। कोई पराया नहीं दिखता; सबके साथ मेरा प्यार बना हुआ है। 1।","en":"Whatever God does, I accept that as good. This is the sublime wisdom I have obtained from the Holy. ||2||"},{"g":"ਸਭ ਮਹਿ ਰਵਿ ਰਹਿਆ ਪ੍ਰਭੁ ਏਕੈ ਪੇਖਿ ਪੇਖਿ ਨਾਨਕ ਬਿਗਸਾਈ ॥੩॥੮॥","t":"sabh meh rav rahiaa prabh ekai pekh pekh naanak bigasaiee ||3||8||","pa":"ਹੇ ਨਾਨਕ! (ਆਖ—ਜਦੋਂ ਤੋਂ ਸਾਧ ਸੰਗਤਿ ਮਿਲੀ ਹੈ, ਮੈਨੂੰ ਇਉਂ ਦਿੱਸਦਾ ਹੈ ਕਿ) ਇਕ ਪਰਮਾਤਮਾ ਹੀ ਸਭ ਜੀਵਾਂ ਵਿਚ ਮੌਜੂਦ ਹੈ (ਤਾਹੀਏਂ ਸਭ ਨੂੰ) ਵੇਖ ਵੇਖ ਕੇ ਮੈਂ ਖ਼ੁਸ਼ ਹੁੰਦਾ ਹਾਂ ।੩।੮","hi":"हे भाई ! (अब) जो कुछ परमात्मा करता है। मैं उसको (सब जीवों के लिए) भला मानता हूँ। ये सुमति मैंने (अपने) गुरू से सीखी है। 2।","en":"The One God is pervading in all. Gazing upon Him, beholding Him, Nanak blossoms forth in happiness. ||3||8||"}],"audioUrl":null,"youtube":null},{"id":"shabad-3085","type":"Shabad","title":"Taatee vaau na lagiee paarabraham saranaiee ","gurmukhiTitle":"ਤਾਤੀ ਵਾਉ ਨ ਲਗਈ ਪਾਰਬ੍ਰਹਮ ਸਰਣਾਈ","author":"Guru Arjan Dev Ji","raag":"Raag Bilaaval","ang":819,"source":"Sri Guru Granth Sahib Ji","nitnem":false,"lines":[{"g":"ਬਿਲਾਵਲੁ ਮਹਲਾ ੫ ॥","t":"bilaaval mahalaa panjavaa ||","pa":"","hi":"","en":"Bilaaval, Fifth Mehla:"},{"g":"ਤਾਤੀ ਵਾਉ ਨ ਲਗਈ ਪਾਰਬ੍ਰਹਮ ਸਰਣਾਈ ॥","t":"taatee vaau na lagiee paarabraham saranaiee ||","pa":"ਹੇ ਭਾਈ! ਪਰਮਾਤਮਾ ਦੀ ਸਰਨ ਪਿਆਂ (ਵਿਆਧੀਆਂ ਦਾ) ਸੇਕ ਨਹੀਂ ਲੱਗਦਾ ।","hi":"हे भाई ! परमात्मा की शरण पड़ने से (व्याधियों का) सेक नहीं लगता।","en":"The hot wind does not even touch one who is under the Protection of the Supreme Lord God."},{"g":"ਚਉਗਿਰਦ ਹਮਾਰੈ ਰਾਮ ਕਾਰ ਦੁਖੁ ਲਗੈ ਨ ਭਾਈ ॥੧॥","t":"chaugiradh hamaarai raam kaar dhukh lagai na bhaiee ||1||","pa":"ਹੇ ਭਾਈ! ਅਸਾਂ ਜੀਵਾਂ ਦੇ ਦੁਆਲੇ ਪਰਮਾਤਮਾ ਦਾ ਨਾਮ (ਮਾਨੋ) ਇਕ ਲਕੀਰ ਹੈ (ਜਿਸ ਦੀ ਬਰਕਤਿ ਨਾਲ) ਕੋਈ ਦੁੱਖ ਪੋਹ ਨਹੀਂ ਸਕਦਾ ।੧।","hi":"हे भाई ! हम जीवों के चारों तरफ परमात्मा का नाम (मानो) एक लकीर है (जिसकी बरकति से) कोई दुख छू नहीं सकता। 1।","en":"On all four sides I am surrounded by the Lord's Circle of Protection; pain does not afflict me, O Siblings of Destiny. ||1||"},{"g":"ਸਤਿਗੁਰੁ ਪੂਰਾ ਭੇਟਿਆ ਜਿਨਿ ਬਣਤ ਬਣਾਈ ॥","t":"satigur pooraa bheTiaa jin banat banaiee ||","pa":"ਹੇ ਭਾਈ! ਜਿਸ ਗੁਰੂ ਨੇ (ਪਰਮਾਤਮਾ ਦਾ ਨਾਮ-ਦਵਾਈ ਦੇ ਕੇ ਜੀਵਾਂ ਦੇ ਰੋਗ ਦੂਰ ਕਰਨ ਦੀ) ਵਿਓਂਤ ਬਣਾ ਰੱਖੀ ਹੈ, ਉਹ ਪੂਰਾ ਗੁਰੂ (ਜਿਸ ਮਨੁੱਖ ਨੂੰ) ਮਿਲ ਪੈਂਦਾ ਹੈ","hi":"हे भाई ! जिस गुरू ने (परमात्मा का नाम-दवा दे के जीवों के रोग दूर करने की) बिउंत बना रखी है।","en":"I have met the Perfect True Guru, who has done this deed."},{"g":"ਰਾਮ ਨਾਮੁ ਅਉਖਧੁ ਦੀਆ ਏਕਾ ਲਿਵ ਲਾਈ ॥੧॥ ਰਹਾਉ ॥","t":"raam naam aaukhadh dheeaa ekaa liv laiee ||1|| rahaau ||","pa":"ਅਤੇ ਪਰਮਾਤਮਾ ਦਾ ਨਾਮ-ਦਵਾਈ ਦੇਂਦਾ ਹੈ, ਉਹ ਮਨੁੱਖ ਸਦਾ ਪਰਮਾਤਮਾ ਵਿਚ ਸੁਰਤਿ ਜੋੜੀ ਰੱਖਦਾ ਹੈ ।੧।ਰਹਾਉ।","hi":"वह पूरा गुरू (जिस मनुष्य को) मिल जाता है और परमात्मा का नाम दवाई देता है। वह मनुष्य सदा परमात्मा में सुरति जोड़े रखता है। 1। रहाउ।","en":"He has given me the medicine of the Lord's Name, and I enshrine love for the One Lord. ||1||Pause||"},{"g":"ਰਾਖਿ ਲੀਏ ਤਿਨਿ ਰਖਨਹਾਰਿ ਸਭ ਬਿਆਧਿ ਮਿਟਾਈ ॥","t":"raakh le'ee tin rakhanahaar sabh biaadh miTaiee ||","pa":"ਹੇ ਨਾਨਕ! ਆਖ—(ਜਿਸ ਮਨੁੱਖ ਨੂੰ ਗੁਰੂ ਮਿਲ ਪਿਆ ਉਸ ਨੂੰ) ਉਸ ਰੱਖਣਹਾਰ ਪ੍ਰਭੂ ਨੇ ਬਚਾ ਲਿਆ, (ਉਸ ਦੇ ਅੰਦਰੋਂ) ਹਰੇਕ ਰੋਗ ਦੂਰ ਕਰ ਦਿੱਤਾ,","hi":"हे नानक ! कह- (जिस मनुष्य को गुरू मिल गया उसको) उस रखवाले प्रभू ने बचा लिया। (उसके अंदर से) हरेक रोग दूर कर दिया।","en":"The Savior Lord has saved me, and eradicated all my sickness."},{"g":"ਕਹੁ ਨਾਨਕ ਕਿਰਪਾ ਭਈ ਪ੍ਰਭ ਭਏ ਸਹਾਈ ॥੨॥੧੫॥੭੯॥","t":"kahu naanak kirapaa bhiee prabh bhe sahaiee ||2||15||79||","pa":"ਉਸ ਮਨੁੱਖ ਉਤੇ ਪ੍ਰਭੂ ਦੀ ਕਿਰਪਾ ਹੋ ਗਈ, ਪ੍ਰਭੂ ਉਸ ਮਨੁੱਖ ਦਾ ਮਦਦਗਾਰ ਬਣ ਗਿਆ ।੨।੧੫।੭੯।","hi":"उस मनुष्य पर प्रभू की कृपा हो गई। प्रभू उस मनुष्य का मददगार बन गया। 2। 15। 79।","en":"Says Nanak, God has showered me with His Mercy; He has become my help and support. ||2||15||79||"}],"audioUrl":null,"youtube":null},{"id":"shabad-1648","type":"Shabad","title":"Man too(n) jot saroop hai aapanaa mool pachhaan ","gurmukhiTitle":"ਮਨ ਤੂੰ ਜੋਤਿ ਸਰੂਪੁ ਹੈ ਆਪਣਾ ਮੂਲੁ ਪਛਾਣੁ","author":"Guru Amar Das Ji","raag":"Raag Aasaa","ang":440,"source":"Sri Guru Granth Sahib Ji","nitnem":false,"lines":[{"g":"ਮਨ ਤੂੰ ਜੋਤਿ ਸਰੂਪੁ ਹੈ ਆਪਣਾ ਮੂਲੁ ਪਛਾਣੁ ॥","t":"man too(n) jot saroop hai aapanaa mool pachhaan ||","pa":"ਹੇ ਮੇਰੇ ਮਨ! ਤੂੰ ਉਸ ਪਰਮਾਤਮਾ ਦੀ ਅੰਸ ਹੈਂ ਜੋ ਨਿਰਾ ਨੂਰ ਹੀ ਨੂਰ ਹੈ (ਹੇ ਮਨ!) ਆਪਣੇ ਉਸ ਅਸਲੇ ਨਾਲ ਸਾਂਝ ਬਣਾ ।","hi":"हे मेरे मन ! तू उस परमात्मा की अंश है जो निरा नूर ही नूर है (हे मन !) अपनी उस अस्लियत से सांझ बना।","en":"O my mind, you are the embodiment of the Divine Light - recognize your own origin."},{"g":"ਮਨ ਹਰਿ ਜੀ ਤੇਰੈ ਨਾਲਿ ਹੈ ਗੁਰਮਤੀ ਰੰਗੁ ਮਾਣੁ ॥","t":"man har jee terai naal hai gurmatee ra(n)g maan ||","pa":"ਹੇ ਮਨ! ਉਹ ਪਰਮਾਤਮਾ ਸਦਾ ਤੇਰੇ ਅੰਗ-ਸੰਗ ਵੱਸਦਾ ਹੈ, ਗੁਰੂ ਦੀ ਮਤਿ ਲੈ ਕੇ ਉਸ ਦੇ ਮਿਲਾਪ ਦਾ ਸੁਆਦ ਲੈ ।","hi":"हे मन ! वह परमात्मा सदा तेरे अंग-संग बसता है।गुरू की मति ले के उसके मिलाप का स्वाद ले।","en":"O my mind, the Dear Lord is with you; through the Guru's Teachings, enjoy His Love."},{"g":"ਮੂਲੁ ਪਛਾਣਹਿ ਤਾਂ ਸਹੁ ਜਾਣਹਿ ਮਰਣ ਜੀਵਣ ਕੀ ਸੋਝੀ ਹੋਈ ॥","t":"mool pachhaaneh taa(n) sahu jaaneh maran jeevan kee sojhee hoiee ||","pa":"ਹੇ ਮਨ! ਜੇ ਤੂੰ ਆਪਣਾ ਅਸਲਾ ਸਮਝ ਲਏਂ ਤਾਂ ਉਸ ਖਸਮ-ਪ੍ਰਭੂ ਨਾਲ ਤੇਰੀ ਡੂੰਘੀ ਜਾਣ-ਪਛਾਣ ਬਣ ਜਾਏਗੀ, ਤਦੋਂ ਤੈਨੂੰ ਇਹ ਸਮਝ ਭੀ ਆ ਜਾਇਗੀ ਕਿ ਆਤਮਕ ਮੌਤ ਕੀਹ ਚੀਜ਼ ਹੈ ਤੇ ਆਤਮਕ ਜ਼ਿੰਦਗੀ ਕੀਹ ਹੈ ।","hi":"हे मन ! अगर तू अपनी अस्लियत समझ ले तो उस पति-प्रभू से तेरी गहरी जान-पहचान बन जाएगी।तब तुझे ये समझ भी आ जाएगा कि आत्मिक मौत क्या चीज है और आत्मिक जिंदगी क्या है।","en":"Acknowledge your origin, and then you shall know your Husband Lord, and so understand death and birth."},{"g":"ਗੁਰ ਪਰਸਾਦੀ ਏਕੋ ਜਾਣਹਿ ਤਾਂ ਦੂਜਾ ਭਾਉ ਨ ਹੋਈ ॥","t":"gur parasaadhee eko jaaneh taa(n) dhoojaa bhaau na hoiee ||","pa":"ਹੇ ਮਨ! ਜੇ ਗੁਰੂ ਦੀ ਕਿਰਪਾ ਨਾਲ ਇਕ ਪਰਮਾਤਮਾ ਨਾਲ ਡੂੰਘੀ ਸਾਂਝ ਪਾ ਲਏਂ, ਤਾਂ ਤੇਰੇ ਅੰਦਰ (ਪਰਮਾਤਮਾ ਤੋਂ ਬਿਨਾ) ਕੋਈ ਹੋਰ ਮੋਹ ਪ੍ਰਬਲ ਨਹੀਂ ਹੋ ਸਕੇਗਾ ।","hi":"हे मन ! अगर गुरू की कृपा से एक परमात्मा के साथ गहरी सांझ डाल ले।तो तेरे अंदर (परमात्मा के बिना) कोई और मोह प्रबल नहीं हो सकेगा।","en":"By Guru's Grace, know the One; then, you shall not love any other."},{"g":"ਮਨਿ ਸਾਂਤਿ ਆਈ ਵਜੀ ਵਧਾਈ ਤਾ ਹੋਆ ਪਰਵਾਣੁ ॥","t":"man saa(n)t aaiee vajee vadhaiee taa hoaa paravaan ||","pa":"ਜਦੋਂ ਮਨੁੱਖ ਦੇ ਮਨ ਵਿਚ ਸ਼ਾਂਤੀ ਪੈਦਾ ਹੋ ਜਾਂਦੀ ਹੈ ਜਦੋਂ ਇਸ ਦੇ ਅੰਦਰ ਚੜ੍ਹਦੀ ਕਲਾ ਪ੍ਰਬਲ ਹੋ ਜਾਂਦੀ ਹੈ ਤਦੋਂ ਇਹ ਪ੍ਰਭੂ ਦੀ ਹਜ਼ੂਰੀ ਵਿਚ ਕਬੂਲ ਹੋ ਜਾਂਦਾ ਹੈ ।","hi":"जब मनुष्य के मन में शांति पैदा हो जाती है जब इसके अंदर चढ़दीकला प्रबल हो जाती तब ये प्रभू की हजूरी में कबूल हो जाता है।","en":"Peace comes to the mind, and gladness resounds; then, you shall be acclaimed."},{"g":"ਇਉ ਕਹੈ ਨਾਨਕੁ ਮਨ ਤੂੰ ਜੋਤਿ ਸਰੂਪੁ ਹੈ ਅਪਣਾ ਮੂਲੁ ਪਛਾਣੁ ॥੫॥","t":"eiau kahai naanak man too(n) jot saroop hai apanaa mool pachhaan ||5||","pa":"ਨਾਨਕ ਇਉਂ ਦੱਸਦਾ ਹੈ—ਹੇ ਮੇਰੇ ਮਨ! ਤੂੰ ਉਸ ਪਰਮਾਤਮਾ ਦੀ ਅੰਸ ਹੈਂ ਜੋ ਨਿਰਾ ਚਾਨਣ ਹੀ ਚਾਨਣ ਹੈ (ਹੇ ਮਨ! ਆਪਣੇ ਉਸ ਅਸਲੇ ਨਾਲ ਸਾਂਝ ਬਣਾ ।੫।","hi":"नानक ऐसे बताता है–हे मेरे मन ! तू उस परमात्मा की अंश है जो निरा प्रकाश ही प्रकाश है (हे मन ! अपने उस असल से सांझ बना।असल को पहचान)। 5।","en":"Thus says Nanak: O my mind, you are the very image of the Luminous Lord; recognize the true origin of your self. ||5||"}],"audioUrl":null,"youtube":null},{"id":"shabad-3297","type":"Shabad","title":"Koiee bolai raam raam koiee khudhai ","gurmukhiTitle":"ਕੋਈ ਬੋਲੈ ਰਾਮ ਰਾਮ ਕੋਈ ਖੁਦਾਇ","author":"Guru Arjan Dev Ji","raag":"Raag Raamkalee","ang":885,"source":"Sri Guru Granth Sahib Ji","nitnem":false,"lines":[{"g":"ਰਾਮਕਲੀ ਮਹਲਾ ੫ ॥","t":"raamakalee mahalaa panjavaa ||","pa":"","hi":"","en":"Raamkalee, Fifth Mehla:"},{"g":"ਕੋਈ ਬੋਲੈ ਰਾਮ ਰਾਮ ਕੋਈ ਖੁਦਾਇ ॥","t":"koiee bolai raam raam koiee khudhai ||","pa":"ਹੇ ਭਾਈ! ਕੋਈ ਮਨੁੱਖ (ਪਰਮਾਤਮਾ ਦਾ ਨਾਮ) ‘ਰਾਮ ਰਾਮ’ ਉਚਾਰਦਾ ਹੈ, ਕੋਈ ਉਸ ਨੂੰ ‘ਖ਼ੁਦਾਇ, ਖ਼ੁਦਾਇ’ ਆਖਦਾ ਹੈ ।","hi":"हे भाई ! कोई मनुष्य (परमात्मा का नाम) 'राम राम' उचारता है। कोई उसको 'ख़ुदाय खुदाय' कहता है।","en":"Some call Him, 'Raam, Raam', and some call Him, 'Khudaa-i'."},{"g":"ਕੋਈ ਸੇਵੈ ਗੁਸਈਆ ਕੋਈ ਅਲਾਹਿ ॥੧॥","t":"koiee sevai gusieeaa koiee alaeh ||1||","pa":"ਕੋਈ ਮਨੁੱਖ ਉਸ ਨੂੰ ‘ਗੋਸਾਈਂ’ ਆਖ ਕੇ ਉਸ ਦੀ ਭਗਤੀ ਕਰਦਾ ਹੈ, ਕੋਈ ‘ਅੱਲਾ’ ਆਖ ਕੇ ਬੰਦਗੀ ਕਰਦਾ ਹੈ ।੧।","hi":"कोई मनुष्य उसको 'गोसाई' कह के उसकी भक्ति करता है। कोई 'अल्ला' कह के बँदगी करता है। 1।","en":"Some serve Him as 'Gusain', others as 'Allaah'. ||1||"},{"g":"ਕਾਰਣ ਕਰਣ ਕਰੀਮ ॥","t":"kaaran karan kareem ||","pa":"ਹੇ ਸਾਰੇ ਜਗਤ ਦੇ ਮੂਲ! ਹੇ ਬਖ਼ਸ਼ਿੰਦ!","hi":"हे सारे जगत के मूल ! हे बख्शिंद ! हे कृपालु !","en":"He is the Cause of causes, the Generous Lord."},{"g":"ਕਿਰਪਾ ਧਾਰਿ ਰਹੀਮ ॥੧॥ ਰਹਾਉ ॥","t":"kirapaa dhaar raheem ||1|| rahaau ||","pa":"ਹੇ ਕਿਰਪਾਲ! ਹੇ ਰਹਿਮ ਕਰਨ ਵਾਲੇ! (ਜੀਵਾਂ ਨੇ ਆਪੋ ਆਪਣੇ ਧਰਮ-ਪੁਸਤਕਾਂ ਦੀ ਬੋਲੀ ਅਨੁਸਾਰ ਤੇਰੇ ਵਖ ਵਖ ਨਾਮ ਰੱਖੇ ਹੋਏ ਹਨ, ਪਰ ਤੂੰ ਸਭ ਦਾ ਸਾਂਝਾ ਹੈਂ) ।੧।ਰਹਾਉ।","hi":"हे रहम करने वाले ! (जीवों ने अपनी-अपनी धर्म-पुस्तकों की बोली के अनुसार तेरे अलग-अलग नाम रखे हुए हैं। पर तू सबका सांझा है)। 1। रहाउ।","en":"He showers His Grace and Mercy upon us. ||1||Pause||"},{"g":"ਕੋਈ ਨਾਵੈ ਤੀਰਥਿ ਕੋਈ ਹਜ ਜਾਇ ॥","t":"koiee naavai teerath koiee haj jai ||","pa":"ਹੇ ਭਾਈ! ਕੋਈ ਮਨੁੱਖ ਕਿਸੇ ਤੀਰਥ ਉਤੇ ਇਸ਼ਨਾਨ ਕਰਦਾ ਹੈ, ਕੋਈ ਮਨੁੱਖ (ਮੱਕੇ) ਹੱਜ ਕਰਨ ਵਾਸਤੇ ਜਾਂਦਾ ਹੈ ।","hi":"हे भाई ! कोई मनुष्य किसी तीर्थ पर स्नान करता है। कोई मनुष्य (मक्के) हज करने के लिए जाता है।","en":"Some bathe at sacred shrines of pilgrimage, and some make the pilgrimage to Mecca.|"},{"g":"ਕੋਈ ਕਰੈ ਪੂਜਾ ਕੋਈ ਸਿਰੁ ਨਿਵਾਇ ॥੨॥","t":"koiee karai poojaa koiee sir nivai ||2||","pa":"ਕੋਈ ਮਨੁੱਖ (ਪ੍ਰਭੂ ਦੀ ਮੂਰਤੀ ਬਣਾ ਕੇ) ਪੂਜਾ ਕਰਦਾ ਹੈ, ਕੋਈ ਨਮਾਜ਼ ਪੜ੍ਹਦਾ ਹੈ ।੨।","hi":"कोई मनुष्य (प्रभू की मूर्ति बना के) पूजा करता है। कोई नमाज़ पढ़ता है। 2।","en":"Some perform devotional worship services, and some bow their heads in prayer. ||2||"},{"g":"ਕੋਈ ਪੜੈ ਬੇਦ ਕੋਈ ਕਤੇਬ ॥","t":"koiee paRai bedh koiee kateb ||","pa":"ਹੇ ਭਾਈ! ਕੋਈ (ਹਿੰਦੂ) ਵੇਦ ਆਦਿਕ ਧਰਮ-ਪੁਸਤਕ ਪੜ੍ਹਦਾ ਹੈ, ਕੋਈ (ਮੁਸਲਮਾਨ ਆਦਿਕ) ਕੁਰਾਨ ਅੰਜੀਲ ਆਦਿਕ ਪੜ੍ਹਦਾ ਹੈ ।","hi":"हे भाई ! कोई (हिन्दू) वेद आदि धर्म-पुस्तक पढ़ता है। कोई (मुसलमान आदि) कुरान अंजील आदि पढ़ता है।","en":"Some read the Vedas, and some the Koran."},{"g":"ਕੋਈ ਓਢੈ ਨੀਲ ਕੋਈ ਸੁਪੇਦ ॥੩॥","t":"koiee oddai neel koiee supedh ||3||","pa":"ਕੋਈ (ਮੁਸਲਮਾਨ ਹੋ ਕੇ) ਨੀਲੇ ਕੱਪੜੇ ਪਹਿਨਦਾ ਹੈ, ਕੋਈ (ਹਿੰਦੂ) ਚਿੱਟੇ ਬਸਤ੍ਰ ਪਾਂਦਾ ਹੈ ।੩।","hi":"कोई (मुसलमान हो के) नीले कपड़े पहनता है। कोई (हिंदू) सफेद वस्त्र पहनता है। 3।","en":"Some wear blue robes, and some wear white. ||3||"},{"g":"ਕੋਈ ਕਹੈ ਤੁਰਕੁ ਕੋਈ ਕਹੈ ਹਿੰਦੂ ॥","t":"koiee kahai turak koiee kahai hi(n)dhoo ||","pa":"ਹੇ ਭਾਈ! ਕੋਈ ਮਨੁੱਖ ਆਖਦਾ ਹੈ ‘ਮੈਂ ਮੁਸਲਮਾਨ ਹਾਂ’, ਕੋਈ ਆਖਦਾ ਹੈ ‘ਮੈਂ ਹਿੰਦੂ ਹਾਂ’ ।","hi":"हे भाई ! कोई मनुष्य कहता है 'मैं मुसलमान हूँ'। कोई कहता है 'मैं हिन्दू हूँ'।","en":"Some call themselves Muslim, and some call themselves Hindu."},{"g":"ਕੋਈ ਬਾਛੈ ਭਿਸਤੁ ਕੋਈ ਸੁਰਗਿੰਦੂ ॥੪॥","t":"koiee baachhai bhisat koiee suragi(n)dhoo ||4||","pa":"ਕੋਈ ਮਨੁੱਖ (ਪਰਮਾਤਮਾ ਪਾਸੋਂ) ਬਹਿਸ਼ਤ ਮੰਗਦਾ ਹੈ, ਕੋਈ ਸੁਰਗ ਮੰਗਦਾ ਹੈ ।੪।","hi":"कोई मनुष्य (परमात्मा से) बहिष्त माँगता है। कोई स्वर्ग मांगता है। 4।","en":"Some yearn for paradise, and others long for heaven. ||4||"},{"g":"ਕਹੁ ਨਾਨਕ ਜਿਨਿ ਹੁਕਮੁ ਪਛਾਤਾ ॥","t":"kahu naanak jin hukam pachhaataa ||","pa":"ਹੇ ਨਾਨਕ! ਆਖ—ਜਿਸ ਮਨੁੱਖ ਨੇ ਪਰਮਾਤਮਾ ਦਾ ਹੁਕਮ ਪਛਾਣਿਆ ਹੈ,","hi":"हे नानक ! कह- जिस मनुष्य ने परमात्मा का हुकम पहचाना है।","en":"Says Nanak, one who realizes the Hukam of God's Will,"},{"g":"ਪ੍ਰਭ ਸਾਹਿਬ ਕਾ ਤਿਨਿ ਭੇਦੁ ਜਾਤਾ ॥੫॥੯॥","t":"prabh saahib kaa tin bhedh jaataa ||5||9||","pa":"ਉਸ ਨੇ ਮਾਲਕ-ਪ੍ਰਭੂ ਦਾ ਭੇਤ ਪਾ ਲਿਆ ਹੈ (ਕਿ ਉਸ ਨੂੰ ਕਿਵੇਂ ਪ੍ਰਸੰਨ ਕਰ ਸਕੀਦਾ ਹੈ) ।੯।","hi":"उसने मालिक प्रभू का भेद पा लिया है (कि उसे कैसे प्रसन्न किया जा सकता है)। 5। 9।","en":"knows the secrets of his Lord and Master. ||5||9||"}],"audioUrl":null,"youtube":null},{"id":"shabad-39","type":"Shabad","title":"Pavan guroo paanee pitaa maataa dharat mahat ","gurmukhiTitle":"ਪਵਣੁ ਗੁਰੂ ਪਾਣੀ ਪਿਤਾ ਮਾਤਾ ਧਰਤਿ ਮਹਤੁ","author":"Guru Nanak Dev Ji","raag":"Jap","ang":8,"source":"Sri Guru Granth Sahib Ji","nitnem":false,"lines":[{"g":"ਸਲੋਕੁ ॥","t":"salok ||","pa":"","hi":"श्लोक","en":"Shalok:"},{"g":"ਪਵਣੁ ਗੁਰੂ ਪਾਣੀ ਪਿਤਾ ਮਾਤਾ ਧਰਤਿ ਮਹਤੁ ॥","t":"pavan guroo paanee pitaa maataa dharat mahat ||","pa":"ਪ੍ਰਾਣ (ਸਰੀਰਾਂ ਲਈ ਇਉਂ ਹਨ ਜਿਵੇਂ) ਗੁਰੂ (ਜੀਵਾਂ ਦੇ ਆਤਮਾ ਲਈ) ਹੈ, ਪਾਣੀ (ਸਭ ਜੀਵਾਂ ਦਾ) ਪਿਉ ਹੈ ਅਤੇ ਧਰਤੀ (ਸਭ ਦੀ) ਵੱਡੀ ਮਾਂ ਹੈ।","hi":"प्राण (शरीर में इस प्रकार हैं जैसे) गुरू (जीवों की आत्मा के लिए) है। पानी (सभी जीवों का) पिता है और धरती (सबकी) बड़ी माँ है।","en":"Air is the Guru, Water is the Father, and Earth is the Great Mother of all."},{"g":"ਦਿਵਸੁ ਰਾਤਿ ਦੁਇ ਦਾਈ ਦਾਇਆ ਖੇਲੈ ਸਗਲ ਜਗਤੁ ॥","t":"dhivas raat dhui dhaiee dhaiaa khelai sagal jagat ||","pa":"ਦਿਨ ਅਤੇ ਰਾਤ ਦੋਵੇਂ ਖਿਡਾਵਾ ਤੇ ਖਿਡਾਵੀ ਹਨ, ਸਾਰਾ ਸੰਸਾਰ ਖੇਡ ਰਿਹਾ ਹੈ,","hi":"दिन और रात दोनों खेल खिलाने वाला और खिलाने वाली हैं~ सारा संसार खेल रहा है (भाव~ संसार के सारे जीव रात को सोने में और दिन के कार्य-व्यवहार में परखे जा रहे हैं)","en":"Day and night are each like the nanny and her caregiving husband, in whose lap the whole world is at play."},{"g":"ਚੰਗਿਆਈਆ ਬੁਰਿਆਈਆ ਵਾਚੈ ਧਰਮੁ ਹਦੂਰਿ ॥","t":"cha(n)giaaieeaa buriaaieeaa vaachai dharam hadhoor ||","pa":"ਧਰਮਰਾਜ ਅਕਾਲ ਪੁਰਖ ਦੀ ਹਜ਼ੂਰੀ ਵਿਚ (ਜੀਵਾਂ ਦੇ ਕੀਤੇ ਹੋਏ) ਚੰਗੇ ਤੇ ਮੰਦੇ ਕੰਮ ਵਿਚਾਰਦਾ ਹੈ।","hi":"धर्मराज अकाल पुरख की हज़ूरी में (जीवों के किये हुए) सही कामों को विचारता है।","en":"Good deeds and bad deeds-the record is read out in the Presence of the Lord of Dharma."},{"g":"ਕਰਮੀ ਆਪੋ ਆਪਣੀ ਕੇ ਨੇੜੈ ਕੇ ਦੂਰਿ ॥","t":"karamee aapo aapanee ke neRai ke dhoor ||","pa":"ਆਪੋ ਆਪਣੇ (ਇਹਨਾਂ ਕੀਤੇ ਹੋਏ) ਕਰਮਾਂ ਦੇ ਅਨੁਸਾਰ ਕਈ ਜੀਵ ਅਕਾਲ ਪੁਰਖ ਦੇ ਨੇੜੇ ਹੋ ਜਾਂਦੇ ਹਨ ਅਤੇ ਅਕਾਲ ਪੁਰਖ ਤੋਂ ਦੂਰਿ ਹੋ ਜਾਂਦੇ ਹਨ।","hi":"अपने अपने (इन किए हुये) कर्मों के अनुसार कई जीव अकाल-पुरख के नज़दीक हो जाते हैं और कई अकाल-पुरख से दूर रह जाते हैं।","en":"According to their own actions, some are drawn closer, and some are driven farther away."},{"g":"ਜਿਨੀ ਨਾਮੁ ਧਿਆਇਆ ਗਏ ਮਸਕਤਿ ਘਾਲਿ ॥","t":"jinee naam dhiaaiaa ge masakat ghaal ||","pa":"ਜਿਨ੍ਹਾਂ ਮਨੁੱਖਾਂ ਨੇ ਅਕਾਲ ਪੁਰਖ ਦਾ ਨਾਮ ਸਿਮਰਿਆ ਹੈ, ਉਹ ਆਪਣੀ ਮਿਹਨਤ ਸਫਲੀ ਕਰ ਗਏ ਹਨ,","hi":"हे नानक! जिन मनुष्यों ने अकाल-पुरख का नाम सिमरा है~ वे अपनी मेहनत सफल कर गये हैं।","en":"Those who have meditated on the Naam, the Name of the Lord, and departed after having worked by the sweat of their brows"},{"g":"ਨਾਨਕ ਤੇ ਮੁਖ ਉਜਲੇ ਕੇਤੀ ਛੁਟੀ ਨਾਲਿ ॥੧॥","t":"naanak te mukh ujale ketee chhuTee naal ||1||","pa":"ਹੇ ਨਾਨਕ ! ਉਹ ਉੱਜਲ ਮੁਖ ਵਾਲੇ ਹਨ ਅਤੇ (ਹੋਰ ਭੀ) ਕਈ ਜੀਵ ਉਹਨਾਂ ਦੀ ਸੰਗਤਿ ਵਿਚ (ਰਹਿ ਕੇ) (“ਕੂੜ ਦੀ ਪਾਲਿ” ਢਾਹ ਕੇ ਮਾਇਆ ਦੇ ਬੰਧਨਾਂ ਤੋਂ) ਆਜ਼ਾਦ ਹੋ ਗਏ ਹਨ।੧।","hi":"(अकाल-पुरख के दर पर) वे उज्जवल मुख वाले हैं और (और भी ) कई जीव~ उनकी संगत में (रह के) (‘कूड़ की पालि’ गिरा के माया के बंधनों से) आज़ाद हो गए हैं।1।","en":"-O Nanak, their faces are radiant in the Court of the Lord, and many are saved along with them! ||1||"}],"audioUrl":null,"youtube":null},{"id":"shabad-466","type":"Shabad","title":"Mere saahibaa kaun jaanai gun tere ","gurmukhiTitle":"ਮੇਰੇ ਸਾਹਿਬਾ ਕਉਣੁ ਜਾਣੈ ਗੁਣ ਤੇਰੇ","author":"Guru Nanak Dev Ji","raag":"Raag Gauree","ang":156,"source":"Sri Guru Granth Sahib Ji","nitnem":false,"lines":[{"g":"ਗਉੜੀ ਚੇਤੀ ਮਹਲਾ ੧ ॥","t":"gauRee chetee mahalaa pehilaa ||","pa":"","hi":"","en":"Gauree Chaytee, First Mehla:"},{"g":"ਕਤ ਕੀ ਮਾਈ ਬਾਪੁ ਕਤ ਕੇਰਾ ਕਿਦੂ ਥਾਵਹੁ ਹਮ ਆਏ ॥","t":"kat kee maiee baap kat keraa kidhoo thaavahu ham aae ||","pa":"(ਹੇ ਮੇਰੇ ਸਾਹਿਬ ! ਅਣਗਿਣਤ ਔਗੁਣਾਂ ਦੇ ਕਾਰਨ ਹੀ ਸਾਨੂੰ ਅਨੇਕਾਂ ਜੂਨਾਂ ਵਿਚ ਭਟਕਣਾ ਪੈਂਦਾ ਹੈ, ਅਸੀਂ ਕੀਹ ਦੱਸੀਏ ਕਿ) ਕਦੋਂ ਦੀ ਸਾਡੀ (ਕੋਈ) ਮਾਂ ਹੈ ਕਦੋਂ ਦਾ (ਭਾਵ, ਕਿਸ ਜੂਨ ਦਾ) ਸਾਡਾ ਕੋਈ ਪਿਉ ਹੈ, ਕਿਸ ਕਿਸ ਥਾਂ ਤੋਂ (ਜੂਨ ਵਿਚੋਂ ਹੋ ਕੇ) ਅਸੀ (ਹੁਣ ਇਸ ਮਨੁੱਖਾ ਜਨਮ ਵਿਚ) ਆਏ ਹਾਂ ?","hi":"(हे मेरे साहिब ! अनगिनत अवगुणों के कारण ही हमें अनेको योनियों में भटकना पड़ता है~ हम क्या बताएं कि) कब की हमारी (कोई) माँ है। कब का (भाव~ किस जून का) हमारा कोई बाप है किस किस जगह से (जूनियों में से हो के) हम (अब इस मनुष्य जनम में) आए हैं?","en":"Who is our mother, and who is our father? Where did we come from?"},{"g":"ਅਗਨਿ ਬਿੰਬ ਜਲ ਭੀਤਰਿ ਨਿਪਜੇ ਕਾਹੇ ਕੰਮਿ ਉਪਾਏ ॥੧॥","t":"agan bi(n)b jal bheetar nipaje kaahe ka(n)m upaae ||1||","pa":"(ਇਨ੍ਹਾਂ ਔਗੁਣਾਂ ਦੇ ਕਾਰਨ ਹੀ ਸਾਨੂੰ ਇਹ ਵਿਚਾਰ ਭੀ ਨਹੀਂ ਫੁਰਦੀ ਕਿ) ਅਸੀ ਕਿਸ ਮਨੋਰਥ ਵਾਸਤੇ ਪਿਤਾ ਦੇ ਬੀਰਜ ਨਾਲ ਮਾਂ ਦੇ ਪੇਟ ਦੀ ਅੱਗ ਵਿਚ ਨਿੰਮੇ, ਤੇ ਕਾਹਦੇ ਵਾਸਤੇ ਪੈਦਾ ਕੀਤੇ ਗਏ ।੧।","hi":"(इन अवगुणों के कारण ही हमें ये भी नहीं सूझता कि) हम किस मनोरथ उद्देश्य के लिए पिता के वीर्य से माँ के पेट की आग में तपे~ और किस वास्ते पैदा हुए। 1।","en":"We are formed from the fire of the womb within, and the bubble of water of the sperm. For what purpose are we created? ||1||"},{"g":"ਮੇਰੇ ਸਾਹਿਬਾ ਕਉਣੁ ਜਾਣੈ ਗੁਣ ਤੇਰੇ ॥","t":"mere saahibaa kaun jaanai gun tere ||","pa":"(ਉਹ ਐਸਾ) ਕੋਈ ਭੀ ਨਹੀਂ ਹੁੰਦਾ ਜੋ ਤੇਰੇ ਗੁਣਾਂ ਨਾਲ ਡੂੰਘੀ ਸਾਂਝ ਪਾ ਸਕੇ (ਜੋ ਤੇਰੀ ਸਿਫ਼ਤਿ-ਸਾਲਾਹ ਵਿਚ ਜੁੜ ਸਕੇ)","hi":"हे मेरे मालिक प्रभू ! (और~ जिस जीव के अंदर अनगिनत अवगुण हों~ वह ऐसा) कोई भी नहीं होता जो तेरे गुणों के साथ गहरी सांझ डाल सके (जो तेरी सिफत सालाह में जुड़ सके)।","en":"O my Master, who can know Your Glorious Virtues?"},{"g":"ਕਹੇ ਨ ਜਾਨੀ ਅਉਗਣ ਮੇਰੇ ॥੧॥ ਰਹਾਉ ॥","t":"kahe na jaanee aaugan mere ||1|| rahaau ||","pa":"ਹੇ ਮੇਰੇ ਮਾਲਕ ਪ੍ਰਭੂ ! ਮੇਰੇ ਅੰਦਰ ਇਤਨੇ ਔਗੁਣ ਹਨ ਕਿ ਉਹ ਗਿਣੇ ਨਹੀਂ ਜਾ ਸਕਦੇ ।","hi":"मेरे अंदर इतने अवगुण है कि वे गिने नहीं जा सकते। 1। रहाउ।","en":"My own demerits cannot be counted. ||1||Pause||"},{"g":"ਕੇਤੇ ਰੁਖ ਬਿਰਖ ਹਮ ਚੀਨੇ ਕੇਤੇ ਪਸੂ ਉਪਾਏ ॥","t":"kete rukh birakh ham cheene kete pasoo upaae ||","pa":"(ਅਣਗਿਣਤ ਔਗੁਣਾਂ ਦੇ ਕਾਰਨ) ਅਸਾਂ ਅਨੇਕਾਂ ਰੁੱਖਾਂ ਬਿਰਖਾਂ ਦੀਆਂ ਜੂਨਾਂ ਵੇਖੀਆਂ, ਅਨੇਕਾਂ ਵਾਰੀ ਪਸ਼ੂ-ਜੂਨਾਂ ਵਿਚ ਅਸੀ ਜੰਮੇ,","hi":"(अनगिनत अवगुणों के कारण) हमने अनेकों रुखों~ वृक्षों की जूनियां देखीं। अनेकों बार पशू जून में हम जन्मे।","en":"I took the form of so many plants and trees, and so many animals."},{"g":"ਕੇਤੇ ਨਾਗ ਕੁਲੀ ਮਹਿ ਆਏ ਕੇਤੇ ਪੰਖ ਉਡਾਏ ॥੨॥","t":"kete naag kulee meh aae kete pa(n)kh uddaae ||2||","pa":"ਅਨੇਕਾਂ ਵਾਰੀ ਸੱਪਾਂ ਦੀਆਂ ਕੁਲਾਂ ਵਿਚ ਪੈਦਾ ਹੋਏ, ਤੇ ਅਨੇਕਾਂ ਵਾਰੀ ਪੰਛੀ ਬਣ ਬਣ ਕੇ ਉਡਦੇ ਰਹੇ ।੨।","hi":"अनेकों बार साँपों की कुलों में पैदा हुए~ और अनेकों बार पंछी बन बन के उड़ते रहे। 2।","en":"Many times I entered the families of snakes and flying birds. ||2||"},{"g":"ਹਟ ਪਟਣ ਬਿਜ ਮੰਦਰ ਭੰਨੈ ਕਰਿ ਚੋਰੀ ਘਰਿ ਆਵੈ ॥","t":"haT paTan bij ma(n)dhar bha(n)nai kar choree ghar aavai ||","pa":"(ਜਨਮ ਜਨਮਾਂਤਰਾਂ ਵਿਚ ਕੀਤੇ ਕੁਕਰਮਾਂ ਦੇ ਅਸਰ ਹੇਠ ਹੀ) ਮਨੁੱਖ ਸ਼ਹਰਾਂ ਦੀਆਂ ਹੱਟੀਆਂ ਭੰਨਦਾ ਹੈ, ਪੱਕੇ ਘਰ ਭੰਨਦਾ ਹੈ (ਸੰਨ੍ਹ ਲਾਂਦਾ ਹੈ), ਚੋਰੀ ਕਰ ਕੇ (ਮਾਲ ਲੈ ਕੇ) ਆਪਣੇ ਘਰ ਆਉਂਦਾ ਹੈ,","hi":"(जनमों जन्मांतरों में किये कुकर्मों के असर में ही) मनुष्य शहरों की दुकानें तोड़ता है~ पक्के घर तोड़ता है (सेंध लगाता है)~ चोरी करके (माल ले के) अपने घर आता है~","en":"I broke into the shops of the city and well-guarded palaces; stealing from them, I snuck home again."},{"g":"ਅਗਹੁ ਦੇਖੈ ਪਿਛਹੁ ਦੇਖੈ ਤੁਝ ਤੇ ਕਹਾ ਛਪਾਵੈ ॥੩॥","t":"agahu dhekhai pichhahu dhekhai tujh te kahaa chhapaavai ||3||","pa":"(ਚੋਰੀ ਦਾ ਮਾਲ ਲਿਆਉਂਦਾ) ਅੱਗੇ ਪਿੱਛੇ ਤੱਕਦਾ ਹੈ (ਕਿ ਕੋਈ ਆਦਮੀ ਵੇਖ ਨ ਲਏ, ਪਰ ਮੂਰਖ ਇਹ ਨਹੀਂ ਸਮਝਦਾ ਕਿ ਹੇ ਪ੍ਰਭੂ !) ਤੇਰੇ ਪਾਸੋਂ ਕਿਤੇ ਲੁਕਾ ਨਹੀਂ ਕਰ ਸਕਦਾ ।੩।","hi":"(चोरी का माल लाता) आगे पीछे ताकता है (कि कोई देख ना ले~ पर मूर्ख ये नहीं समझता कि हे प्रभू !) तेरे से कहीं छुपा नहीं रह सकता। 3।","en":"I looked in front of me, and I looked behind me, but where could I hide from You? ||3||"},{"g":"ਤਟ ਤੀਰਥ ਹਮ ਨਵ ਖੰਡ ਦੇਖੇ ਹਟ ਪਟਣ ਬਾਜਾਰਾ ॥","t":"taT teerath ham nav kha(n)dd dhekhe haT paTan baajaaraa ||","pa":"(ਇਹਨਾਂ ਕੀਤੇ ਕੁਕਰਮਾਂ ਨੂੰ ਧੋਣ ਲਈ ਅਸੀ ਜੀਵ) ਸਾਰੀ ਧਰਤੀ ਦੇ ਸਾਰੇ ਤੀਰਥਾਂ ਦੇ ਦਰਸਨ ਕਰਦੇ ਫਿਰਦੇ ਹਾਂ, ਸਾਰੇ ਸ਼ਹਰਾਂ ਬਜ਼ਾਰਾਂ ਦੀ ਹੱਟੀ ਹੱਟੀ ਵੇਖਦੇ ਹਾਂ (ਭਾਵ, ਭੀਖ ਮੰਗਦੇ ਫਿਰਦੇ ਹਾਂ, ਪਰ ਇਹ ਕੁਕਰਮ ਫਿਰ ਭੀ ਖ਼ਲਾਸੀ ਨਹੀਂ ਕਰਦੇ) ।","hi":"(इन किए कुकर्मों को धोने के लिए हम जीव) सारी धरती के सारे तीर्थों के दर्शन करते फिरते हैं। सारे शहरों~ बाजारों की दुकान-दुकान देखते हैं (भाव~ भीख मांगते फिरते हैं~ पर ये कुकर्म फिर भी नहीं मिटते)।","en":"I saw the banks of sacred rivers, the nine continents, the shops and bazaars of the cities."},{"g":"ਲੈ ਕੈ ਤਕੜੀ ਤੋਲਣਿ ਲਾਗਾ ਘਟ ਹੀ ਮਹਿ ਵਣਜਾਰਾ ॥੪॥","t":"lai kai takaRee tolan laagaa ghaT hee meh vanajaaraa ||4||","pa":"(ਜਦੋਂ ਕੋਈ ਭਾਗਾਂ ਵਾਲਾ ਜੀਵ-) ਵਣਜਾਰਾ (ਤੇਰੀ ਮਿਹਰ ਦਾ ਸਦਕਾ) ਚੰਗੀ ਤਰ੍ਹਾਂ ਪਰਖ-ਵਿਚਾਰ ਕਰਦਾ ਹੈ (ਤਾਂ ਉਸ ਨੂੰ ਸਮਝ ਪੈਂਦੀ ਹੈ ਕਿ ਤੂੰ ਤਾਂ) ਸਾਡੇ ਹਿਰਦੇ ਵਿਚ ਹੀ ਵੱਸਦਾ ਹੈਂ ।੪।","hi":"(जब कोई भाग्यशाली जीव-) वणजारा (तेरी मेहर के सदका) अच्छी तरह परख विचार करता है (तो उसे समझ आती है कि तू तो) हमारे हृदय में ही बसता है। 4।","en":"Taking the scale, the merchant begins to weigh his actions within his own heart. ||4||"},{"g":"ਜੇਤਾ ਸਮੁੰਦੁ ਸਾਗਰੁ ਨੀਰਿ ਭਰਿਆ ਤੇਤੇ ਅਉਗਣ ਹਮਾਰੇ ॥","t":"jetaa samu(n)dh saagar neer bhariaa tete aaugan hamaare ||","pa":"(ਹੇ ਮੇਰੇ ਸਾਹਿਬ !) ਜਿਵੇਂ (ਅਮਿਣਵੇਂ) ਪਾਣੀ ਨਾਲ ਸਮੁੰਦਰ ਭਰਿਆ ਹੋਇਆ ਹੈ, ਤਿਵੇਂ ਹੀ ਸਾਡੇ ਜੀਵਾਂ ਦੇ ਅਣਗਿਣਤ ਹੀ ਔਗੁਣ ਹਨ ।","hi":"(हे मेरे साहिब !) जैसे (अनमापे~ अथाह) पानी के साथ समुंद्र भरा हुआ है~ वैसे ही हम जीवों के अनगिनत ही अवगुण हैं।","en":"As the seas and the oceans are overflowing with water, so vast are my own sins."},{"g":"ਦਇਆ ਕਰਹੁ ਕਿਛੁ ਮਿਹਰ ਉਪਾਵਹੁ ਡੁਬਦੇ ਪਥਰ ਤਾਰੇ ॥੫॥","t":"dhiaa karahu kichh mihar upaavahu ddubadhe pathar taare ||5||","pa":"(ਅਸੀ ਇਹਨਾਂ ਨੂੰ ਧੋ ਸਕਣ ਤੋਂ ਅਸਮਰਥ ਹਾਂ), ਤੂੰ ਆਪ ਹੀ ਦਇਆ ਕਰ ਮਿਹਰ ਕਰ । ਤੂੰ ਤਾਂ ਡੁੱਬਦੇ ਪੱਥਰਾਂ ਨੂੰ ਭੀ ਤਾਰ ਸਕਦਾ ਹੈਂ ।੫।","hi":"(हम इन्हें धो सकने में अस्मर्थ हैं)~ तू खुद ही दया करके मेहर कर। तू तो डूबते पत्थरों को भी उबार सकता है। 5।","en":"Please, shower me with Your Mercy, and take pity upon me. I am a sinking stone - please carry me across! ||5||"},{"g":"ਜੀਅੜਾ ਅਗਨਿ ਬਰਾਬਰਿ ਤਪੈ ਭੀਤਰਿ ਵਗੈ ਕਾਤੀ ॥","t":"jeeaRaa agan baraabar tapai bheetar vagai kaatee ||","pa":"(ਹੇ ਮੇਰੇ ਸਾਹਿਬ !) ਮੇਰੀ ਜਿੰਦ ਅੱਗ ਵਾਂਗ ਤਪ ਰਹੀ ਹੈ, ਮੇਰੇ ਅੰਦਰ ਤ੍ਰਿਸ਼ਨਾ ਦੀ ਛੁਰੀ ਚੱਲ ਰਹੀ ਹੈ ।","hi":"(हे मेरे साहिब !) मेरी जीवात्मा आग की तरह तप रही है। मेरे अंदर तृष्णा की छुरी चल रही है।","en":"My soul is burning like fire, and the knife is cutting deep."},{"g":"ਪ੍ਰਣਵਤਿ ਨਾਨਕੁ ਹੁਕਮੁ ਪਛਾਣੈ ਸੁਖੁ ਹੋਵੈ ਦਿਨੁ ਰਾਤੀ ॥੬॥੫॥੧੭॥","t":"pranavat naanak hukam pachhaanai sukh hovai dhin raatee ||6||5||17||","pa":"ਨਾਨਕ ਬੇਨਤੀ ਕਰਦਾ ਹੈ—ਜੋ ਮਨੁੱਖ ਪਰਮਾਤਮਾ ਦੀ ਰਜ਼ਾ ਨੂੰ ਸਮਝ ਲੈਂਦਾ ਹੈ, ਉਸ ਦੇ ਅੰਦਰ ਦਿਨ ਰਾਤ (ਹਰ ਵੇਲੇ ਹੀ) ਆਤਮਕ ਆਨੰਦ ਬਣਿਆ ਰਹਿੰਦਾ ਹੈ ।੬।੫।੧੭।","hi":"नानक विनती करता है– जो मनुष्य परमात्मा की रज़ा को समझ लेता है~ उसके अंदर दिन रात (हर वक्त ही) आत्मिक आनंद बना रहता है। 6। 5। 17।","en":"Prays Nanak, recognizing the Lord's Command, I am at peace, day and night. ||6||5||17||"}],"audioUrl":null,"youtube":{"id":"IaTt-G2s5LM","artist":"Bhai Balwinder Singh Rangila"}},{"id":"shabad-2886","type":"Shabad","title":"Aavahu sajanaa hau dhekhaa dharasan teraa raam ","gurmukhiTitle":"ਆਵਹੁ ਸਜਣਾ ਹਉ ਦੇਖਾ ਦਰਸਨੁ ਤੇਰਾ ਰਾਮ","author":"Guru Nanak Dev Ji","raag":"Raag Soohee","ang":764,"source":"Sri Guru Granth Sahib Ji","nitnem":false,"lines":[{"g":"ਰਾਗੁ ਸੂਹੀ ਮਹਲਾ ੧ ਘਰੁ ੩","t":"raag soohee mahalaa pehilaa ghar teejaa","pa":"","hi":"","en":"Raag Soohee, First Mehla, Third House:"},{"g":"ੴ ਸਤਿਗੁਰ ਪ੍ਰਸਾਦਿ ॥","t":"ikOankaar satigur prasaadh ||","pa":"","hi":"","en":"One Universal Creator God. By The Grace Of The True Guru:"},{"g":"ਆਵਹੁ ਸਜਣਾ ਹਉ ਦੇਖਾ ਦਰਸਨੁ ਤੇਰਾ ਰਾਮ ॥","t":"aavahu sajanaa hau dhekhaa dharasan teraa raam ||","pa":"ਹੇ ਸੱਜਣ-ਪ੍ਰਭੂ! ਆ, ਮੈਂ ਤੇਰਾ ਦਰਸਨ ਕਰ ਸਕਾਂ ।","hi":"हे सज्जन प्रभू ! आ।मैं तेरे दर्शन कर सकूँ।","en":"Come, my friend, so that I may behold the blessed Vision of Your Darshan."},{"g":"ਘਰਿ ਆਪਨੜੈ ਖੜੀ ਤਕਾ ਮੈ ਮਨਿ ਚਾਉ ਘਨੇਰਾ ਰਾਮ ॥","t":"ghar aapanaRai khaRee takaa mai man chaau ghaneraa raam ||","pa":"(ਹੇ ਸੱਜਣ!) ਮੈਂ ਆਪਣੇ ਹਿਰਦੇ ਵਿਚ ਪੂਰੀ ਸਾਵਧਾਨਤਾ ਨਾਲ ਤੇਰੀ ਉਡੀਕ ਕਰ ਰਹੀ ਹਾਂ, ਮੇਰੇ ਮਨ ਵਿਚ ਬੜਾ ਹੀ ਚਾਉ ਹੈ (ਕਿ ਮੈਨੂੰ ਤੇਰਾ ਦਰਸਨ ਹੋਵੇ) ।","hi":"(हे सज्जन !) मैं अपने हृदय में पूरी सावधानी से तेरा इन्तजार कर रही हूँ।मेरे मन में बड़ा चाव है (कि मुझे तेरे दर्शन हों)।","en":"I stand in my doorway, watching for You; my mind is filled with such a great yearning."},{"g":"ਮਨਿ ਚਾਉ ਘਨੇਰਾ ਸੁਣਿ ਪ੍ਰਭ ਮੇਰਾ ਮੈ ਤੇਰਾ ਭਰਵਾਸਾ ॥","t":"man chaau ghaneraa sun prabh meraa mai teraa bharavaasaa ||","pa":"ਹੇ ਮੇਰੇ ਪ੍ਰਭੂ! (ਮੇਰੀ ਬੇਨਤੀ) ਸੁਣ, ਮੇਰੇ ਮਨ ਵਿਚ (ਤੇਰੇ ਦਰਸਨ ਲਈ) ਬੜਾ ਹੀ ਚਾਉ ਹੈ, ਮੈਨੂੰ ਆਸਰਾ ਭੀ ਤੇਰਾ ਹੀ ਹੈ ।","hi":"हे मेरे प्रभू ! (मेरी विनती) सुन।मेरे मन में (तेरे दर्शनों के लिए) बड़ा ही उत्साह है।मुझे आसरा भी तेरा ही है।","en":"My mind is filled with such a great yearning; hear me, O God - I place my faith in You."},{"g":"ਦਰਸਨੁ ਦੇਖਿ ਭਈ ਨਿਹਕੇਵਲ ਜਨਮ ਮਰਣ ਦੁਖੁ ਨਾਸਾ ॥","t":"dharasan dhekh bhiee nihakeval janam maran dhukh naasaa ||","pa":"(ਹੇ ਪ੍ਰਭੂ!) ਜਿਸ ਜੀਵ-ਇਸਤ੍ਰੀ ਨੇ ਤੇਰਾ ਦਰਸਨ ਕਰ ਲਿਆ, ਉਹ ਪਵਿੱਤ੍ਰ-ਆਤਮਾ ਹੋ ਗਈ, ਉਸ ਦਾ ਜਨਮ ਮਰਨ ਦਾ ਦੁੱਖ ਦੂਰ ਹੋ ਗਿਆ ।","hi":"(हे प्रभू !) जिस जीव-स्त्री ने तेरे दर्शन कर लिए।वह पवित्र आत्मा हो गई।उसके जनम-मरण के दुख दूर हो गए।","en":"Gazing upon the Blessed Vision of Your Darshan, I have become free of desire; the pains of birth and death are taken away."},{"g":"ਸਗਲੀ ਜੋਤਿ ਜਾਤਾ ਤੂ ਸੋਈ ਮਿਲਿਆ ਭਾਇ ਸੁਭਾਏ ॥","t":"sagalee jot jaataa too soiee miliaa bhai subhaae ||","pa":"ਉਸ ਨੇ ਸਾਰੇ ਜੀਵਾਂ ਵਿਚ ਤੈਨੂੰ ਹੀ ਵੱਸਦਾ ਪਛਾਣ ਲਿਆ, ਉਸ ਦੇ ਪ੍ਰੇਮ (ਦੀ ਖਿੱਚ) ਦੀ ਰਾਹੀਂ ਤੂੰ ਉਸ ਨੂੰ ਮਿਲ ਪਿਆ ।","hi":"उसने सारे जीवों में तुझे ही बसता पहचान लिया।उसके प्रेम (के आर्कषण) के द्वारा तू उसे मिल गया।","en":"Your Light is in everyone; through it, You are known. Through love, You are easily met."},{"g":"ਨਾਨਕ ਸਾਜਨ ਕਉ ਬਲਿ ਜਾਈਐ ਸਾਚਿ ਮਿਲੇ ਘਰਿ ਆਏ ॥੧॥","t":"naanak saajan kau bal jaieeaai saach mile ghar aae ||1||","pa":"ਹੇ ਨਾਨਕ! ਸੱਜਣ ਪ੍ਰਭੂ ਤੋਂ ਸਦਕੇ ਹੋਣਾ ਚਾਹੀਦਾ ਹੈ । ਜੇਹੜੀ ਜੀਵ-ਇਸਤ੍ਰੀ ਉਸ ਦੇ ਸਦਾ-ਥਿਰ ਨਾਮ ਵਿਚ ਜੁੜਦੀ ਹੈ, ਉਸ ਦੇ ਹਿਰਦੇ ਵਿਚ ਉਹ ਆ ਪ੍ਰਗਟਦਾ ਹੈ ।੧।","hi":"हे नानक ! सज्जन प्रभू से सदके होना चाहिए।जो जीव-स्त्री उसके सदा-स्थिर नाम में जुड़ती है।उसके हृदय में वह आ प्रगट होता है। 1।","en":"O Nanak, I am a sacrifice to my Friend; He has come home to meet with those who are true. ||1||"},{"g":"ਘਰਿ ਆਇਅੜੇ ਸਾਜਨਾ ਤਾ ਧਨ ਖਰੀ ਸਰਸੀ ਰਾਮ ॥","t":"ghar aaiaRe saajanaa taa dhan kharee sarasee raam ||","pa":"ਜਦੋਂ ਸੱਜਣ-ਪ੍ਰਭੂ ਜੀ ਜੀਵ-ਇਸਤ੍ਰੀ ਦੇ ਹਿਰਦੇ-ਘਰ ਵਿਚ ਪਰਗਟਦੇ ਹਨ, ਤਾਂ ਜੀਵ-ਇਸਤ੍ਰੀ ਬਹੁਤ ਪ੍ਰਸੰਨ-ਚਿੱਤ ਹੋ ਜਾਂਦੀ ਹੈ ।","hi":"जब सज्जन प्रभू जी जीव-स्त्री के हृदय-गृह में प्रकट होते हैं।तो जीव-स्त्री बहुत प्रसन्न-चिक्त हो जाती है।","en":"When her Friend comes to her home, the bride is very pleased."},{"g":"ਹਰਿ ਮੋਹਿਅੜੀ ਸਾਚ ਸਬਦਿ ਠਾਕੁਰ ਦੇਖਿ ਰਹੰਸੀ ਰਾਮ ॥","t":"har mohiaRee saach sabadh Thaakur dhekh raha(n)see raam ||","pa":"ਜਦੋਂ ਸਦਾ-ਥਿਰ ਪ੍ਰਭੂ ਦੀ ਸਿਫ਼ਤਿ ਸਾਲਾਹ ਦੇ ਸ਼ਬਦ ਨੇ ਉਸ ਨੂੰ ਖਿੱਚ ਪਾਈ, ਤਾਂ ਠਾਕੁਰ ਜੀ ਦਾ ਦਰਸਨ ਕਰ ਕੇ ਉਹ ਅਡੋਲ-ਚਿੱਤ ਹੋ ਗਈ ।","hi":"जब सदा-स्थिर प्रभू की सिफत सालाह के शबद ने उसको आकर्षित किया।तब ठाकुर जी के दर्शन करके वह अडोल-चिक्त हो गई।","en":"She is fascinated with the True Word of the Lord's Shabad; gazing upon her Lord and Master, she is filled with joy."},{"g":"ਗੁਣ ਸੰਗਿ ਰਹੰਸੀ ਖਰੀ ਸਰਸੀ ਜਾ ਰਾਵੀ ਰੰਗਿ ਰਾਤੈ ॥","t":"gun sa(n)g raha(n)see kharee sarasee jaa raavee ra(n)g raatai ||","pa":"ਜਦੋਂ ਪ੍ਰੇਮ-ਰੰਗ ਵਿਚ ਰੱਤੇ ਪਰਮਾਤਮਾ ਨੇ ਜੀਵ-ਇਸਤ੍ਰੀ ਨੂੰ ਆਪਣੇ ਚਰਨਾਂ ਵਿਚ ਜੋੜਿਆ ਤਾਂ ਉਹ ਪ੍ਰਭੂ ਦੇ ਗੁਣਾਂ (ਦੀ ਯਾਦ) ਵਿਚ ਅਡੋਲ-ਆਤਮਾ ਹੋ ਗਈ ਤੇ ਬਹੁਤ ਪ੍ਰਸੰਨ-ਚਿੱਤ ਹੋ ਗਈ ।","hi":"जब प्रेम-रंग में रंगे हुए परमात्मा ने जीव-स्त्री को अपने चरणों में जोड़ा तो वह प्रभू के गुणों (की याद) में अडोल-आत्मा हो गई और बहुत प्रसन्न-चिक्त हो गई।","en":"She is filled with virtuous joy, and is totally pleased, when she is ravished and enjoyed by her Lord, and imbued with His Love."},{"g":"ਅਵਗਣ ਮਾਰਿ ਗੁਣੀ ਘਰੁ ਛਾਇਆ ਪੂਰੈ ਪੁਰਖਿ ਬਿਧਾਤੈ ॥","t":"avagan maar gunee ghar chhaiaa poorai purakh bidhaatai ||","pa":"ਪੂਰਨ ਪੁਰਖ ਨੇ ਸਿਰਜਣਹਾਰ ਨੇ (ਉਸ ਦੇ ਅੰਦਰੋਂ) ਔਗੁਣ ਦੂਰ ਕਰ ਕੇ ਉਸ ਦੇ ਹਿਰਦੇ ਨੂੰ ਗੁਣਾਂ ਨਾਲ ਭਰਪੂਰ ਕਰ ਦਿੱਤਾ","hi":"पूरन-पुरख ने। सृजनहार ने (उसके अंदर से) अवगुण दूर करके उसके हृदय को गुणों से भरपूर कर दिया","en":"Her faults and demerits are eradicated, and she roofs her home with virtue, through the Perfect Lord, the Architect of Destiny."},{"g":"ਤਸਕਰ ਮਾਰਿ ਵਸੀ ਪੰਚਾਇਣਿ ਅਦਲੁ ਕਰੇ ਵੀਚਾਰੇ ॥","t":"tasakar maar vasee pa(n)chain adhal kare veechaare ||","pa":"ਕਾਮਾਦਿਕ ਚੋਰਾਂ ਨੂੰ ਮਾਰ ਕੇ ਉਹ ਜੀਵ-ਇਸਤ੍ਰੀ ਉਸ ਪਰਮਾਤਮਾ (ਦੇ ਚਰਨਾਂ) ਵਿਚ ਟਿਕ ਗਈ ਜੋ ਸਦਾ ਪੂਰੀ ਵਿਚਾਰ ਨਾਲ ਨਿਆਂ ਕਰਦਾ ਹੈ ।","hi":"कामादिक चोरों को मार के वह जीव-स्त्री उस परमात्मा (के चरणों) में टिक गई जो सदा पूरी विचार से न्याय करता है।","en":"Conquering the thieves, she dwells as the mistress of her home, and administers justice wisely."},{"g":"ਨਾਨਕ ਰਾਮ ਨਾਮਿ ਨਿਸਤਾਰਾ ਗੁਰਮਤਿ ਮਿਲਹਿ ਪਿਆਰੇ ॥੨॥","t":"naanak raam naam nisataaraa gurmat mileh piaare ||2||","pa":"ਹੇ ਨਾਨਕ! ਪਰਮਾਤਮਾ ਦੇ ਨਾਮ ਵਿਚ ਜੁੜਿਆਂ ਸੰਸਾਰ-ਸਮੁੰਦਰ ਤੋਂ ਪਾਰ ਲੰਘ ਜਾਈਦਾ ਹੈ, ਗੁਰੂ ਦੀ ਸਿੱਖਿਆ ਤੇ ਤੁਰਿਆਂ ਪਿਆਰੇ ਪ੍ਰਭੂ ਜੀ ਮਿਲ ਪੈਂਦੇ ਹਨ ।੨।","hi":"हे नानक ! परमात्मा के नाम में जुड़ने से संसार-समुंद्र से पार लांघा जाता है।गुरू की शिक्षा पर चलने से प्यारे प्रभू जी मिल पड़ते हैं। 2।","en":"O Nanak, through the Lord's Name, she is emancipated; through the Guru's Teachings, she meets her Beloved. ||2||"},{"g":"ਵਰੁ ਪਾਇਅੜਾ ਬਾਲੜੀਏ ਆਸਾ ਮਨਸਾ ਪੂਰੀ ਰਾਮ ॥","t":"var paiaRaa baalaRe'e aasaa manasaa pooree raam ||","pa":"ਜਿਸ ਜੀਵ-ਇਸਤ੍ਰੀ ਨੇ ਖਸਮ-ਪ੍ਰਭੂ ਲੱਭ ਲਿਆ, ਉਸ ਦੀ ਹਰੇਕ ਆਸ ਉਸ ਦੀ ਹਰੇਕ ਇੱਛਾ ਪੂਰੀ ਹੋ ਜਾਂਦੀ ਹੈ (ਭਾਵ, ਉਸ ਦਾ ਮਨ ਦੁਨੀਆ ਦੀਆਂ ਆਸਾਂ ਆਦਿਕ ਵਲ ਨਹੀਂ ਦੌੜਦਾ ਭੱਜਦਾ) ।","hi":"जिस जीव-स्त्री ने पति-प्रभू को पा लिया।उसकी हरेक आस उसकी हरेक इच्छा पूरी हो जाती है (भाव।उसका मन दुनिया की आशाओं आदि की ओर नहीं दौड़ता भागता)।","en":"The young bride has found her Husband Lord; her hopes and desires are fulfilled."},{"g":"ਪਿਰਿ ਰਾਵਿਅੜੀ ਸਬਦਿ ਰਲੀ ਰਵਿ ਰਹਿਆ ਨਹ ਦੂਰੀ ਰਾਮ ॥","t":"pir raaviaRee sabadh ralee rav rahiaa neh dhooree raam ||","pa":"ਜਿਸ ਜੀਵ-ਇਸਤ੍ਰੀ ਨੂੰ ਪ੍ਰਭੂ-ਪਤੀ ਨੇ ਆਪਣੇ ਚਰਨਾਂ ਵਿਚ ਜੋੜ ਲਿਆ, ਜੋ ਜੀਵ-ਇਸਤ੍ਰੀ ਗੁਰੂ ਦੇ ਸ਼ਬਦ ਦੀ ਬਰਕਤਿ ਨਾਲ ਪ੍ਰਭੂ ਵਿਚ ਲੀਨ ਹੋ ਗਈ, ਉਸ ਨੂੰ ਪ੍ਰਭੂ ਹਰ ਥਾਂ ਵਿਆਪਕ ਦਿੱਸਦਾ ਹੈ, ਉਸ ਨੂੰ ਆਪਣੇ ਤੋਂ ਦੂਰ ਨਹੀਂ ਜਾਪਦਾ ।","hi":"जिस जीव-स्त्री को प्रभू-पति ने अपने चरणों में जोड़ लिया।जो जीव-स्त्री गुरू के शबद की बरकति से प्रभू में लीन हो गई।उसे प्रभू हर जगह व्यापक दिखाई देता है।उसको अपने से दूर नहीं प्रतीत होता।","en":"She enjoys and ravishes her Husband Lord, and blends into the Word of the Shabad, pervading and permeating everywhere; the Lord is not far away."},{"g":"ਪ੍ਰਭੁ ਦੂਰਿ ਨ ਹੋਈ ਘਟਿ ਘਟਿ ਸੋਈ ਤਿਸ ਕੀ ਨਾਰਿ ਸਬਾਈ ॥","t":"prabh dhoor na hoiee ghaT ghaT soiee tis kee naar sabaiee ||","pa":"ਉਸ ਨੂੰ ਇਹ ਨਿਸ਼ਚਾ ਹੋ ਜਾਂਦਾ ਹੈ ਕਿ ਪ੍ਰਭੂ ਕਿਤੇ ਦੂਰ ਨਹੀਂ ਹਰੇਕ ਸਰੀਰ ਵਿਚ ਉਹੀ ਮੌਜੂਦ ਹੈ, ਸਾਰੀਆਂ ਜੀਵ-ਇਸਤ੍ਰੀਆਂ ਉਸੇ ਦੀਆਂ ਹੀ ਹਨ ।","hi":"उसे ये निश्चय हो जाता है कि प्रभू कहीं दूर नहीं हरेक शरीर में वही मौजूद है।सारी जीव-सि्त्रयां उसी की ही हैं।","en":"God is not far away; He is in each and every heart. All are His brides."},{"g":"ਆਪੇ ਰਸੀਆ ਆਪੇ ਰਾਵੇ ਜਿਉ ਤਿਸ ਦੀ ਵਡਿਆਈ ॥","t":"aape raseeaa aape raave jiau tis dhee vaddiaaiee ||","pa":"ਉਹ ਆਪ ਹੀ ਆਨੰਦ ਦਾ ਸੋਮਾ ਹੈ, ਜਿਵੇਂ ਉਸ ਦੀ ਰਜ਼ਾ ਹੁੰਦੀ ਹੈ ਉਹ ਆਪ ਹੀ ਆਪਣੇ ਮਿਲਾਪ ਦਾ ਆਨੰਦ ਦੇਂਦਾ ਹੈ ।","hi":"वह स्वयं ही आनंद का श्रोत है।जैसे उसकी रजा होती है वह स्वयं ही अपने मिलाप का आनंद देता है।","en":"He Himself is the Enjoyer, He Himself ravishes and enjoys; this is His glorious greatness."},{"g":"ਅਮਰ ਅਡੋਲੁ ਅਮੋਲੁ ਅਪਾਰਾ ਗੁਰਿ ਪੂਰੈ ਸਚੁ ਪਾਈਐ ॥","t":"amar addol amol apaaraa gur poorai sach paieeaai ||","pa":"ਉਹ ਪਰਮਾਤਮਾ ਮੌਤ-ਰਹਿਤ ਹੈ, ਮਾਇਆ ਵਿਚ ਡੋਲਦਾ ਨਹੀਂ ਉਸ ਦਾ ਮੁੱਲ ਨਹੀਂ ਪੈ ਸਕਦਾ (ਭਾਵ, ਕੋਈ ਪਦਾਰਥ ਉਸ ਦੇ ਬਰਾਬਰ ਦਾ ਨਹੀਂ) ਉਹ ਸਦਾ-ਥਿਰ ਰਹਿਣ ਵਾਲਾ ਹੈ, ਉਹ ਬੇਅੰਤ ਹੈ, ਪੂਰੇ ਗੁਰੂ ਦੀ ਰਾਹੀਂ ਉਸ ਦੀ ਪ੍ਰਾਪਤੀ ਹੁੰਦੀ ਹੈ ।","hi":"वह परमात्मा मौत-रहित है।माया में डोलता नहीं उसका मूल्य नहीं पड़ सकता (भाव।कोई पदार्थ भी उसके बराबर का नहीं) वह सदा-स्थिर रहने वाला है।वह बेअंत है।पूरे गुरू के द्वारा ही उसकी प्राप्ति होती है।","en":"He is imperishable, immovable, invaluable and infinite. The True Lord is obtained through the Perfect Guru."},{"g":"ਨਾਨਕ ਆਪੇ ਜੋਗ ਸਜੋਗੀ ਨਦਰਿ ਕਰੇ ਲਿਵ ਲਾਈਐ ॥੩॥","t":"naanak aape jog sajogee nadhar kare liv laieeaai ||3||","pa":"ਹੇ ਨਾਨਕ! ਪ੍ਰਭੂ ਆਪ ਹੀ ਜੀਵਾਂ ਦੇ ਆਪਣੇ ਨਾਲ ਮੇਲ ਦੇ ਢੋ ਢੁਕਾਂਦਾ ਹੈ, ਜਦੋਂ ਉਹ ਮੇਹਰ ਦੀ ਨਜ਼ਰ ਕਰਦਾ ਹੈ, ਤਦੋਂ ਜੀਵ ਉਸ ਵਿਚ ਸੁਰਤਿ ਜੋੜਦਾ ਹੈ ।੩।","hi":"हे नानक ! प्रभू खुद ही जीवों के अपने साथ मेल के संयोग बनाता है।जब वह मेहर की नजर करता है।तब जीव उसमें सुरति जोड़ता है। 3।","en":"O Nanak, He Himself unites in Union; by His Glance of Grace, He lovingly attunes them to Himself. ||3||"},{"g":"ਪਿਰੁ ਉਚੜੀਐ ਮਾੜੜੀਐ ਤਿਹੁ ਲੋਆ ਸਿਰਤਾਜਾ ਰਾਮ ॥","t":"pir uchaReeaai maaRaReeaai tih loaa sirataajaa raam ||","pa":"ਪ੍ਰਭੂ-ਪਤੀ ਇਕ ਸੋਹਣੇ ਉੱਚੇ ਮਹਲ ਵਿਚ ਵੱਸਦਾ ਹੈ (ਜਿੱਥੇ ਮਾਇਆ ਦਾ ਪ੍ਰਭਾਵ ਨਹੀਂ ਪੈ ਸਕਦਾ) ਉਹ ਤਿੰਨਾਂ ਲੋਕਾਂ ਦਾ ਨਾਥ ਹੈ ।","hi":"प्रभू-पति एक सोहाने-ऊँचे महल में बसता है (जहाँ माया का प्रभाव नहीं पड़ सकता) वह तीनों लोकों का नाथ है।","en":"My Husband Lord dwells in the loftiest balcony; He is the Supreme Lord of the three worlds."},{"g":"ਹਉ ਬਿਸਮ ਭਈ ਦੇਖਿ ਗੁਣਾ ਅਨਹਦ ਸਬਦ ਅਗਾਜਾ ਰਾਮ ॥","t":"hau bisam bhiee dhekh gunaa anahadh sabadh agaajaa raam ||","pa":"ਉਸ ਦੇ ਗੁਣ ਵੇਖ ਕੇ ਮੈਂ ਹੈਰਾਨ ਹੋ ਰਹੀ ਹਾਂ । ਚੌਹੀਂ ਪਾਸੀਂ (ਸਾਰੇ ਸੰਸਾਰ ਵਿਚ) ਉਸ ਦੀ ਜੀਵਨ-ਰੌ ਇਕ-ਰਸ ਰੁਮਕ ਰਹੀ ਹੈ ।","hi":"उसके गुण देख के मैं हैरान हो रही हूँ।चारों तरफ (सारे संसार में) उसकी जीवन-रौंअ एक-रस रुमक रही है।","en":"I am amazed, gazing upon His glorious excellence; the unstruck sound current of the Shabad vibrates and resonates."},{"g":"ਸਬਦੁ ਵੀਚਾਰੀ ਕਰਣੀ ਸਾਰੀ ਰਾਮ ਨਾਮੁ ਨੀਸਾਣੋ ॥","t":"sabadh veechaaree karanee saaree raam naam neesaano ||","pa":"ਜੇਹੜਾ ਮਨੁੱਖ ਪ੍ਰਭੂ ਦੀ ਸਿਫ਼ਤਿ-ਸਾਲਾਹ ਦੇ ਸ਼ਬਦ ਨੂੰ ਵਿਚਾਰਦਾ ਹੈ (ਭਾਵ, ਆਪਣੇ ਮਨ ਵਿਚ ਵਸਾਂਦਾ ਹੈ) ਜਿਸ ਨੇ ਇਹ ਸ੍ਰੇਸ਼ਟ ਕਰਤੱਬ ਬਣਾ ਲਿਆ ਹੈ, ਜਿਸ ਦੇ ਪਾਸ ਪਰਮਾਤਮਾ ਦਾ ਨਾਮ (ਰੂਪ) ਰਾਹਦਾਰੀ ਹੈ (ਉਸ ਨੂੰ ਪ੍ਰਭੂ ਦੀ ਹਜ਼ੂਰੀ ਵਿਚ ਥਾਂ ਮਿਲ ਜਾਂਦੀ ਹੈ)","hi":"जो मनुष्य प्रभू के सिफत सालाह के शबद को विचारता है (भाव।अपने मन में बसाता है) जिसने ये श्रेष्ठ कर्तव्य बना लिया है।","en":"I contemplate the Shabad, and perform sublime deeds; I am blessed with the insignia, the banner of the Lord's Name."},{"g":"ਨਾਮ ਬਿਨਾ ਖੋਟੇ ਨਹੀ ਠਾਹਰ ਨਾਮੁ ਰਤਨੁ ਪਰਵਾਣੋ ॥","t":"naam binaa khoTe nahee Thaahar naam ratan paravaano ||","pa":"(ਪਰ) ਨਾਮ-ਹੀਣੇ ਖੋਟੇ ਮਨੁੱਖ ਨੂੰ (ਉਸ ਦੀ ਦਰਗਾਹ ਵਿਚ) ਥਾਂ ਨਹੀਂ ਮਿਲਦੀ । (ਪ੍ਰਭੂ ਦੇ ਦਰ ਤੇ) ਪ੍ਰਭੂ ਦਾ ਨਾਮ-ਰਤਨ ਹੀ ਕਬੂਲ ਹੁੰਦਾ ਹੈ ।","hi":"जिसके पास परमात्मा के नाम (रूपी) राहदारी है (उसको प्रभू की हजूरी में जगह मिल जाती है।पर) नाम-हीन खोटे मनुष्य को (उसकी दरगाह में) जगह नहीं मिलती।","en":"Without the Naam, the Name of the Lord, the false find no place of rest; only the jewel of the Naam brings acceptance and renown."},{"g":"ਪਤਿ ਮਤਿ ਪੂਰੀ ਪੂਰਾ ਪਰਵਾਨਾ ਨਾ ਆਵੈ ਨਾ ਜਾਸੀ ॥","t":"pat mat pooree pooraa paravaanaa naa aavai naa jaasee ||","pa":"ਜਿਸ ਮਨੁੱਖ ਦੇ ਪਾਸ (ਪ੍ਰਭੂ-ਨਾਮ ਦਾ) ਅ-ਰੁਕ ਪਰਵਾਨਾ ਹੈ, ਉਸ ਨੂੰ (ਪ੍ਰਭੂ-ਦਰ ਤੇ) ਪੂਰੀ ਇੱਜ਼ਤ ਮਿਲਦੀ ਹੈ ਉਸ ਦੀ ਅਕਲ ਉਕਾਈ-ਹੀਣ ਹੋ ਜਾਂਦੀ ਹੈ, ਉਹ ਜਨਮ ਮਰਨ ਦੇ ਗੇੜ ਤੋਂ ਬਚ ਜਾਂਦਾ ਹੈ ।","hi":"(प्रभू के दर पर) प्रभू का नाम-रत्न ही कबूल होता है। जिस मनुष्य के पास (प्रभू-नाम का) अ-रुक परवाना है।उसको (प्रभू-दर पर) पूरी इज्जत मिलती है उसकी अक्ल त्रुटि-हीन हो जाती है।वह जनम-मरन के चक्कर से बच जाता है।","en":"Perfect is my honor, perfect is my intellect and password. I shall not have to come or go."},{"g":"ਨਾਨਕ ਗੁਰਮੁਖਿ ਆਪੁ ਪਛਾਣੈ ਪ੍ਰਭ ਜੈਸੇ ਅਵਿਨਾਸੀ ॥੪॥੧॥੩॥","t":"naanak gurmukh aap pachhaanai prabh jaise avinaasee ||4||1||3||","pa":"ਹੇ ਨਾਨਕ! ਗੁਰੂ ਦੀ ਸਰਨ ਪੈ ਕੇ ਜੋ ਮਨੁੱਖ ਆਪਣੇ ਜੀਵਨ ਨੂੰ ਪੜਤਾਲਦਾ ਹੈ, ਉਹ ਅਬਿਨਾਸੀ ਪ੍ਰਭੂ ਦਾ ਰੂਪ ਹੋ ਜਾਂਦਾ ਹੈ ।੪।੧।੩।","hi":"हे नानक ! गुरू की शरण पड़ कर जो मनुष्य अपने जीवन को पड़तालता है।वह अविनाशी प्रभू का रूप हो जाता है। 4। 1। 3।","en":"O Nanak, the Gurmukh understands her own self; she becomes like her Imperishable Lord God. ||4||1||3||"}],"audioUrl":null,"youtube":{"id":"dFopOHYcrTk","artist":"Bhai Nirmal Singh Khalsa"}},{"id":"shabad-5478","type":"Shabad","title":"Vin boliaa sabh kichh jaanadhaa kis aagai keechai aradhaas ","gurmukhiTitle":"ਵਿਣੁ ਬੋਲਿਆ ਸਭੁ ਕਿਛੁ ਜਾਣਦਾ ਕਿਸੁ ਆਗੈ ਕੀਚੈ ਅਰਦਾਸਿ","author":"Guru Amar Das Ji","raag":"Salok Vaaraan Thay Vadheek","ang":1413,"source":"Sri Guru Granth Sahib Ji","nitnem":false,"lines":[{"g":"ਬਾਬੀਹਾ ਸਗਲੀ ਧਰਤੀ ਜੇ ਫਿਰਹਿ ਊਡਿ ਚੜਹਿ ਆਕਾਸਿ ॥","t":"baabeehaa sagalee dharatee je fireh uoodd chaReh aakaas ||","pa":"ਹੇ ਆਤਮਕ ਜੀਵਨ ਦੇਣ ਵਾਲੀ ਨਾਮ-ਬੂੰਦ ਦੇ ਰਸੀਏ! (ਗੁਰੂ ਨੂੰ ਛੱਡ ਕੇ) ਤੂੰ (ਤੀਰਥ-ਜਾਤ੍ਰਾ ਆਦਿਕ ਦੀ ਖ਼ਾਤਰ) ਸਾਰੀ ਧਰਤੀ ਉਤੇ ਰਟਨ ਕਰਦਾ ਫਿਰੇਂ, ਜੇ ਤੂੰ (ਮਾਨਸਕ ਸ਼ਕਤੀਆਂ ਦੀ ਮਦਦ ਨਾਲ) ਉੱਡ ਕੇ ਆਕਾਸ਼ ਵਿਚ ਭੀ ਜਾ ਪਹੁੰਚੇਂ,","hi":"हे आत्मिक जीवन देने वाली नाम बूँद के रसिए ! (गुरू को छोड़ के) तू (तीर्थ-यात्रा आदि की खातिर) सारी धरती पर रटन करता फिरे। अगर तू (मानसिक शक्तियों की मदद से) उड़ के आकाश में भी जा पहुँचे (तो भी इस तरह माया की तृष्णा की भूख नहीं मिटती। सिर्फ नाम-जल से ही माया की)","en":"The rainbird wanders all over the earth, soaring high through the skies."},{"g":"ਸਤਿਗੁਰਿ ਮਿਲਿਐ ਜਲੁ ਪਾਈਐ ਚੂਕੈ ਭੂਖ ਪਿਆਸ ॥","t":"satigur miliaai jal paieeaai chookai bhookh piaas ||","pa":"ਇਸ ਤਰ੍ਹਾਂ ਮਾਇਆ ਦੀ ਤ੍ਰਿਸ਼ਨਾ ਮਾਇਆ ਦੀ ਭੁੱਖ ਨਹੀਂ ਮਿਟਦੀ । ਨਾਮ-ਜਲ ਨਾਲ ਹੀ ਮਾਇਆ ਦੀ) ਭੁੱਖ ਤ੍ਰਿਹ ਮਿਟਦੀ ਹੈ (ਅਤੇ ਉਹ ਨਾਮ-) ਜਲ ਗੁਰੂ ਮਿਲਿਆਂ (ਹੀ) ਪ੍ਰਾਪਤ ਹੁੰਦਾ ਹੈ ।","hi":"भूख-प्यास मिटती है (और वह नाम-) जल गुरू के मिलने पर (ही) प्राप्त होता है।","en":"But it obtains the drop of water, only when it meets the True Guru, and then, its hunger and thirst are relieved."},{"g":"ਜੀਉ ਪਿੰਡੁ ਸਭੁ ਤਿਸ ਕਾ ਸਭੁ ਕਿਛੁ ਤਿਸ ਕੈ ਪਾਸਿ ॥","t":"jeeau pi(n)dd sabh tis kaa sabh kichh tis kai paas ||","pa":"ਹੇ ਭਾਈ! ਇਹ ਜਿੰਦ ਇਹ ਸਰੀਰ ਸਭ ਕੁਝ ਉਸ (ਪਰਮਾਤਮਾ) ਦਾ ਹੀ ਦਿੱਤਾ ਹੋਇਆ ਹੈ, ਹਰੇਕ ਦਾਤਿ ਉਸ ਦੇ ਹੀ ਵੱਸ ਵਿਚ ਹੈ ।","hi":"हे भाई ! ये जिंद ये शरीर सब कुछ उस (परमात्मा) का ही दिया हुआ है। हरेक दाति उस के ही वश में है।","en":"Soul and body and all belong to Him; everything is His."},{"g":"ਵਿਣੁ ਬੋਲਿਆ ਸਭੁ ਕਿਛੁ ਜਾਣਦਾ ਕਿਸੁ ਆਗੈ ਕੀਚੈ ਅਰਦਾਸਿ ॥","t":"vin boliaa sabh kichh jaanadhaa kis aagai keechai aradhaas ||","pa":"(ਜੀਵਾਂ ਦੇ) ਬੋਲਣ ਤੋਂ ਬਿਨਾ ਹੀ (ਹਰੇਕ ਜੀਵ ਦੀ) ਹਰੇਕ ਲੋੜ ਉਹ ਜਾਣਦਾ ਹੈ, (ਉਸ ਨੂੰ ਛੱਡ ਕੇ) ਹੋਰ ਕਿਸ ਅੱਗੇ ਅਰਦਾਸ ਕੀਤੀ ਜਾ ਸਕਦੀ ਹੈ?","hi":"(जीवों के) बोले बिना ही (हरेक जीव की) हरेक जरूरत वह जानता है। (उसको छोड़ के) और किस के आगे अरदास की जा सकती है।","en":"He knows everything, without being told; unto whom should we offer our prayers?"},{"g":"ਨਾਨਕ ਘਟਿ ਘਟਿ ਏਕੋ ਵਰਤਦਾ ਸਬਦਿ ਕਰੇ ਪਰਗਾਸ ॥੫੮॥","t":"naanak ghaT ghaT eko varatadhaa sabadh kare paragaas ||58||","pa":"ਹੇ ਨਨਾਕ? ਹਰੇਕ ਸਰੀਰ ਵਿਚ ਉਹ ਪਰਮਾਤਮਾ ਆਪ ਹੀ ਮੌਜੂਦ ਹੈ, (ਗੁਰੂ ਦੇ) ਸ਼ਬਦ ਦੀ ਰਾਹੀਂ (ਹਰੇਕ ਜੀਵ ਦੇ ਅੰਦਰ ਆਤਮਕ ਜੀਵਨ ਦਾ) ਚਾਨਣ (ਉਹ ਆਪ ਹੀ) ਕਰਦਾ ਹੈ ।੫੮।","hi":"हे नानक ! हरेक शरीर में वह परमात्मा स्वयं ही मौजूद है। (गुरू के) शबद द्वारा (हरेक जीव के अंदर आत्मिक जीवन की) रौशनी (वह खुद ही) करता है। 58।","en":"O Nanak, the One Lord is prevading and permeating each and every heart; the Word of the Shabad brings illumination. ||58||"}],"audioUrl":null,"youtube":{"id":"DXyzczk-tVE","artist":"Bhai Joginder Singh Riar"}},{"id":"shabad-2555","type":"Shabad","title":"Sabhanaa vich too varatadhaa saahaa sabh tujheh dhiaaveh dhin raat ","gurmukhiTitle":"ਸਭਨਾ ਵਿਚਿ ਤੂ ਵਰਤਦਾ ਸਾਹਾ ਸਭਿ ਤੁਝਹਿ ਧਿਆਵਹਿ ਦਿਨੁ ਰਾਤਿ","author":"Guru Ram Das Ji","raag":"Raag Dhanaasree","ang":670,"source":"Sri Guru Granth Sahib Ji","nitnem":false,"lines":[{"g":"ਧਨਾਸਰੀ ਮਹਲਾ ੪ ॥","t":"dhanaasaree mahalaa chauthhaa ||","pa":"","hi":"","en":"Dhanaasaree, Fourth Mehla:"},{"g":"ਮੇਰੇ ਸਾਹਾ ਮੈ ਹਰਿ ਦਰਸਨ ਸੁਖੁ ਹੋਇ ॥","t":"mere saahaa mai har dharasan sukh hoi ||","pa":"ਹੇ ਮੇਰੇ ਪਾਤਿਸ਼ਾਹ! (ਮੇਹਰ ਕਰ) ਮੈਨੂੰ ਤੇਰੇ ਦਰਸਨ ਦਾ ਆਨੰਦ ਪ੍ਰਾਪਤ ਹੋ ਜਾਏ ।","hi":"हे मेरे पातशाह ! (मेहर कर) मुझे तेरे दर्शनों का आनंद प्राप्त हो जाए।","en":"O my King, beholding the Blessed Vision of the Lord's Darshan, I am at peace."},{"g":"ਹਮਰੀ ਬੇਦਨਿ ਤੂ ਜਾਨਤਾ ਸਾਹਾ ਅਵਰੁ ਕਿਆ ਜਾਨੈ ਕੋਇ ॥ ਰਹਾਉ ॥","t":"hamaree bedhan too jaanataa saahaa avar kiaa jaanai koi || rahaau ||","pa":"ਹੇ ਮੇਰੇ ਪਾਤਿਸ਼ਾਹ! ਮੇਰੇ ਦਿਲ ਦੀ ਪੀੜ ਤੂੰ ਹੀ ਜਾਣਦਾ ਹੈਂ । ਕੋਈ ਹੋਰ ਕੀ ਜਾਣ ਸਕਦਾ ਹੈ? ।ਰਹਾਉ।","hi":"हे मेरे पातशाह ! मेरे दिल की पीड़ा को तू ही जानता है।कोई और क्या जान सकता है।रहाउ।","en":"You alone know my inner pain, O King; what can anyone else know? ||Pause||"},{"g":"ਸਾਚਾ ਸਾਹਿਬੁ ਸਚੁ ਤੂ ਮੇਰੇ ਸਾਹਾ ਤੇਰਾ ਕੀਆ ਸਚੁ ਸਭੁ ਹੋਇ ॥","t":"saachaa saahib sach too mere saahaa teraa keeaa sach sabh hoi ||","pa":"ਹੇ ਮੇਰੇ ਪਾਤਿਸ਼ਾਹ! ਤੂੰ ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲਾ ਮਾਲਕ ਹੈਂ, ਤੂੰ ਅਟੱਲ ਹੈਂ । ਜੋ ਕੁਝ ਤੂੰ ਕਰਦਾ ਹੈਂ, ਉਹ ਭੀ ਉਕਾਈ-ਹੀਣ ਹੈ (ਉਸ ਵਿਚ ਭੀ ਕੋਈ ਊਣਤਾ ਨਹੀਂ) ।","hi":"हे मेरे पातशाह ! तू सदा कायम रहने वाला मालिक है।तू अटल है।जो कुछ तू करता है।उसमें कोई भी कमी खामी नहीं है।","en":"O True Lord and Master, You are truly my King; whatever You do, all that is True."},{"g":"ਝੂਠਾ ਕਿਸ ਕਉ ਆਖੀਐ ਸਾਹਾ ਦੂਜਾ ਨਾਹੀ ਕੋਇ ॥੧॥","t":"jhooThaa kis kau aakheeaai saahaa dhoojaa naahee koi ||1||","pa":"ਹੇ ਪਾਤਿਸ਼ਾਹ! (ਸਾਰੇ ਸੰਸਾਰ ਵਿਚ ਤੈਥੋਂ ਬਿਨਾ) ਹੋਰ ਕੋਈ ਨਹੀਂ ਹੈ (ਇਸ ਵਾਸਤੇ) ਕਿਸੇ ਨੂੰ ਝੂਠਾ ਆਖਿਆ ਨਹੀਂ ਜਾ ਸਕਦਾ ।੧","hi":"हे पातशाह ! (सारे संसार में तेरे बिना) और कोई नहीं है (इस वास्ते) किसी को झूठा नहीं कहा जा सकता। 1।","en":"Who should I call a liar? There is no other than You, O King. ||1||"},{"g":"ਸਭਨਾ ਵਿਚਿ ਤੂ ਵਰਤਦਾ ਸਾਹਾ ਸਭਿ ਤੁਝਹਿ ਧਿਆਵਹਿ ਦਿਨੁ ਰਾਤਿ ॥","t":"sabhanaa vich too varatadhaa saahaa sabh tujheh dhiaaveh dhin raat ||","pa":"ਹੇ ਮੇਰੇ ਪਾਤਿਸ਼ਾਹ! ਤੂੰ ਸਭ ਜੀਵਾਂ ਵਿਚ ਮੌਜੂਦ ਹੈਂ, ਸਾਰੇ ਜੀਵ ਦਿਨ ਰਾਤ ਤੇਰਾ ਹੀ ਧਿਆਨ ਧਰਦੇ ਹਨ","hi":"हे मेरे पातशाह ! तू सब जीवों में मौजूद है।सारे जीव दिन-रात तेरा ही ध्यान धरते हैं।","en":"You are pervading and permeating in all; O King, everyone meditates on You, day and night."},{"g":"ਸਭਿ ਤੁਝ ਹੀ ਥਾਵਹੁ ਮੰਗਦੇ ਮੇਰੇ ਸਾਹਾ ਤੂ ਸਭਨਾ ਕਰਹਿ ਇਕ ਦਾਤਿ ॥੨॥","t":"sabh tujh hee thaavahu ma(n)gadhe mere saahaa too sabhanaa kareh ik dhaat ||2||","pa":"ਹੇ ਮੇਰੇ ਪਾਤਿਸ਼ਾਹ! ਸਾਰੇ ਜੀਵ ਤੇਰੇ ਪਾਸੋਂ ਹੀ (ਮੰਗਾਂ) ਮੰਗਦੇ ਹਨ । ਇਕ ਤੂੰ ਹੀ ਸਭ ਜੀਵਾਂ ਨੂੰ ਦਾਤਾਂ ਦੇ ਰਿਹਾ ਹੈਂ ।੨।","hi":"हे मेरे पातशाह ! सारे जीव तुझसे ही (मांगें) मांगते हैं।एक तू ही सब जीवों को दातें दे रहा है। 2।","en":"Everyone begs of You, O my King; You alone give gifts to all. ||2||"},{"g":"ਸਭੁ ਕੋ ਤੁਝ ਹੀ ਵਿਚਿ ਹੈ ਮੇਰੇ ਸਾਹਾ ਤੁਝ ਤੇ ਬਾਹਰਿ ਕੋਈ ਨਾਹਿ ॥","t":"sabh ko tujh hee vich hai mere saahaa tujh te baahar koiee naeh ||","pa":"ਹੇ ਮੇਰੇ ਪਾਤਿਸ਼ਾਹ! ਹਰੇਕ ਜੀਵ ਤੇਰੇ ਹੁਕਮ ਵਿਚ ਹੈ, ਤੈਥੋਂ ਆਕੀ ਕੋਈ ਜੀਵ ਨਹੀਂ ਹੋ ਸਕਦਾ","hi":"हे मेरे पातशाह ! हरेक जीव तेरे हुकम में है।तुझसे आकी कोई जीव हो ही नहीं सकता।","en":"All are under Your Power, O my King; none at all are beyond You."},{"g":"ਸਭਿ ਜੀਅ ਤੇਰੇ ਤੂ ਸਭਸ ਦਾ ਮੇਰੇ ਸਾਹਾ ਸਭਿ ਤੁਝ ਹੀ ਮਾਹਿ ਸਮਾਹਿ ॥੩॥","t":"sabh jeea tere too sabhas dhaa mere saahaa sabh tujh hee maeh samaeh ||3||","pa":"ਹੇ ਮੇਰੇ ਪਾਤਿਸ਼ਾਹ! ਸਾਰੇ ਜੀਵ ਤੇਰੇ ਪੈਦਾ ਕੀਤੇ ਹੋਏ ਹਨ, ਤੇ, ਇਹ ਸਾਰੇ ਤੇਰੇ ਵਿਚ ਹੀ ਲੀਨ ਹੋ ਜਾਂਦੇ ਹਨ ।੩।","hi":"हे मेरे पातशाह ! सारे जीव तेरे पैदा किए हुए हैं।ये सारे तेरे में ही लीन हो जाते हैं। 3।","en":"All beings are Yours-You belong to all, O my King. All shall merge and be absorbed in You. ||3||"},{"g":"ਸਭਨਾ ਕੀ ਤੂ ਆਸ ਹੈ ਮੇਰੇ ਪਿਆਰੇ ਸਭਿ ਤੁਝਹਿ ਧਿਆਵਹਿ ਮੇਰੇ ਸਾਹ ॥","t":"sabhanaa kee too aas hai mere piaare sabh tujheh dhiaaveh mere saeh ||","pa":"ਹੇ ਮੇਰੇ ਪਿਆਰੇ ਪਾਤਿਸ਼ਾਹ! ਤੂੰ ਸਭ ਜੀਵਾਂ ਦੀ ਆਸਾਂ ਪੂਰੀਆਂ ਕਰਦਾ ਹੈਂ ਸਾਰੇ ਜੀਵ ਤੇਰਾ ਹੀ ਧਿਆਨ ਧਰਦੇ ਹਨ ।","hi":"हे मेरे प्यारे पातशाह ! तू सब जीवों की आशाएं-उम्मीदें पूरी करता है सारे जीव तेरा ही ध्यान धरते हैं।","en":"You are the hope of all, O my Beloved; all meditate on You, O my King."},{"g":"ਜਿਉ ਭਾਵੈ ਤਿਉ ਰਖੁ ਤੂ ਮੇਰੇ ਪਿਆਰੇ ਸਚੁ ਨਾਨਕ ਕੇ ਪਾਤਿਸਾਹ ॥੪॥੭॥੧੩॥","t":"jiau bhaavai tiau rakh too mere piaare sach naanak ke paatisaeh ||4||7||13||","pa":"ਹੇ ਨਾਨਕ ਦੇ ਪਾਤਿਸ਼ਾਹ! ਹੇ ਮੇਰੇ ਪਿਆਰੇ! ਜਿਵੇਂ ਤੈਨੂੰ ਚੰਗਾ ਲੱਗਦਾ ਹੈ, ਤਿਵੇਂ ਮੈਨੂੰ (ਆਪਣੇ ਚਰਨਾਂ ਵਿਚ) ਰੱਖ । ਤੂੰ ਹੀ ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲਾ ਹੈਂ ।੪।੭।੧੩।","hi":"हे नानक के पातशाह ! हे मेरे प्यारे ! जैसे तुझे अच्छा लगता है।वैसे मुझे (अपने चरणों में) रख।तू ही सदा कायम रहने वाला है। 4। 7। 13।","en":"As it pleases You, protect and preserve me, O my Beloved; You are the True King of Nanak. ||4||7||13||"}],"audioUrl":null,"youtube":{"id":"Gxmxts_wqsM","artist":"Bhai Satvinder Singh & Bhai Harvinder Singh"}},{"id":"shabad-4288","type":"Shabad","title":"Mohan ghar aavahu karau jodhareeaa ","gurmukhiTitle":"ਮੋਹਨ ਘਰਿ ਆਵਹੁ ਕਰਉ ਜੋਦਰੀਆ","author":"Guru Arjan Dev Ji","raag":"Raag Saarang","ang":1209,"source":"Sri Guru Granth Sahib Ji","nitnem":false,"lines":[{"g":"ਸਾਰਗ ਮਹਲਾ ੫ ਦੁਪਦੇ ਘਰੁ ੪","t":"saarag mahalaa panjavaa dhupadhe ghar chauthhaa","pa":"","hi":"","en":"Saarang, Fifth Mehla, Dho-Padhay, Fourth House:"},{"g":"ੴ ਸਤਿਗੁਰ ਪ੍ਰਸਾਦਿ ॥","t":"ikOankaar satigur prasaadh ||","pa":"","hi":"","en":"One Universal Creator God. By The Grace Of The True Guru:"},{"g":"ਮੋਹਨ ਘਰਿ ਆਵਹੁ ਕਰਉ ਜੋਦਰੀਆ ॥","t":"mohan ghar aavahu karau jodhareeaa ||","pa":"ਹੇ ਮੋਹਨ-ਪ੍ਰਭੂ! ਮੈਂ ਮਿੰਨਤ ਕਰਦੀ ਹਾਂ ਮੇਰੇ ਹਿਰਦੇ-ਘਰ ਵਿਚ ਆ ਵੱਸ ।","hi":"हे मोहन प्रभू ! मैं मिन्नत करती हॅूँ मेरे हृदय-घर में आ बस।","en":"O my Fascinating Lord, I pray to You: come into my house."},{"g":"ਮਾਨੁ ਕਰਉ ਅਭਿਮਾਨੈ ਬੋਲਉ ਭੂਲ ਚੂਕ ਤੇਰੀ ਪ੍ਰਿਅ ਚਿਰੀਆ ॥੧॥ ਰਹਾਉ ॥","t":"maan karau abhimaanai bolau bhool chook teree pria chireeaa ||1|| rahaau ||","pa":"ਹੇ ਮੋਹਨ! ਮੈਂ (ਸਦਾ) ਮਾਣ ਕਰਦੀ ਰਹਿੰਦੀ ਹਾਂ, ਮੈਂ (ਸਦਾ) ਅਹੰਕਾਰ ਨਾਲ ਗੱਲਾਂ ਕਰਦੀ ਹਾਂ, ਮੈਂ ਬਥੇਰੀਆਂ ਭੁੱਲਾਂ-ਚੁੱਕਾਂ ਕਰਦੀ ਹਾਂ, (ਫਿਰ ਭੀ) ਹੇ ਪਿਆਰੇ! ਮੈਂ ਤੇਰੀ (ਹੀ) ਦਾਸੀ ਹਾਂ ।੧।ਰਹਾਉ।","hi":"हे मोहन ! मैं (सदा) मान करती रहती हूँ। मैं (सदा) अहंकार की बात करती हूँ। मैं बहुत सारी भूलें-चूकें करती हूँ। (फिर भी) हे प्यारे ! मैं तेरी (ही) दासी हूँ। 1। रहाउ।","en":"I act in pride, and speak in pride. I am mistaken and wrong, but I am still Your hand-maiden, O my Beloved. ||1||Pause||"},{"g":"ਨਿਕਟਿ ਸੁਨਉ ਅਰੁ ਪੇਖਉ ਨਾਹੀ ਭਰਮਿ ਭਰਮਿ ਦੁਖ ਭਰੀਆ ॥","t":"nikaT sunau ar pekhau naahee bharam bharam dhukh bhareeaa ||","pa":"ਹੇ ਮੋਹਨ! ਮੈਂ ਸੁਣਦੀ ਹਾਂ (ਤੂੰ) ਨੇੜੇ (ਵੱਸਦਾ ਹੈਂ), ਪਰ ਮੈਂ (ਤੈਨੂੰ) ਵੇਖ ਨਹੀਂ ਸਕਦੀ । ਸਦਾ ਭਟਕ ਭਟਕ ਕੇ ਮੈਂ ਦੁੱਖਾਂ ਵਿਚ ਫਸੀ ਰਹਿੰਦੀ ਹਾਂ ।","hi":"हे मोहन ! मैं सुनती हूँ (तू) नजदीक (बसता है)। पर मैं (तुझे) देख नहीं सकती। सदा भटक-भटक के मैं दुखों में फसी रहती हूँ।","en":"I hear that You are near, but I cannot see You. I wander in suffering, deluded by doubt."},{"g":"ਹੋਇ ਕ੍ਰਿਪਾਲ ਗੁਰ ਲਾਹਿ ਪਾਰਦੋ ਮਿਲਉ ਲਾਲ ਮਨੁ ਹਰੀਆ ॥੧॥","t":"hoi kirapaal gur laeh paaradho milau laal man hareeaa ||1||","pa":"ਹੇ ਗੁਰੂ! ਜੇ ਤੂੰ ਦਇਆਵਾਨ ਹੋ ਕੇ (ਮੇਰੇ ਅੰਦਰੋਂ ਮਾਇਆ ਦੇ ਮੋਹ ਦਾ) ਪਰਦਾ ਦੂਰ ਕਰ ਦੇਵੇਂ, ਮੈਂ (ਸੋਹਣੇ) ਲਾਲ (ਪ੍ਰਭੂ) ਨੂੰ ਮਿਲ ਪਵਾਂ, ਤੇ, ਮੇਰਾ ਮਨ (ਆਤਮਕ ਜੀਵਨ ਨਾਲ) ਹਰ-ਭਰਾ ਹੋ ਜਾਏ ।੧।","hi":"हे गुरू ! अगर तू दयावान हो के (मेरे अंदर से माया के मोह का) पर्दा दूर कर दे। मैं (सुंदर) लाल (प्रभू) को मिल जाऊँ। और। मेरा मन (आत्मिक जीवन से) हरा-भरा हो जाए। 1।","en":"The Guru has become merciful to me; He has removed the veils. Meeting with my Beloved, my mind blossoms forth in abundance. ||1||"},{"g":"ਏਕ ਨਿਮਖ ਜੇ ਬਿਸਰੈ ਸੁਆਮੀ ਜਾਨਉ ਕੋਟਿ ਦਿਨਸ ਲਖ ਬਰੀਆ ॥","t":"ek nimakh je bisarai suaamee jaanau koT dhinas lakh bareeaa ||","pa":"ਹੇ ਭਾਈ! ਜੇ ਅੱਖ ਝਮਕਣ ਜਿਤਨੇ ਸਮੇ ਲਈ ਭੀ ਮਾਲਕ-ਪ੍ਰਭੂ (ਮਨ ਤੋਂ) ਭੱੁਲ ਜਾਏ, ਤਾਂ ਮੈਂ ਇਉਂ ਸਮਝਦੀ ਹਾਂ ਕਿ ਕ੍ਰੋੜਾਂ ਦਿਨ ਲੱਖਾਂ ਵਰ੍ਹੇ ਲੰਘ ਗਏ ਹਨ ।","hi":"हे भाई ! अगर आँख झपकने जितने समय के लिए भी मालिक-प्रभू (मन से) भूल जाए। तो मैं ऐसे समझती हूँ कि करोड़ों दिन लाखों वर्ष गुजर गए हैं।","en":"If I were to forget my Lord and Master, even for an instant, it would be like millions of days, tens of thousands of years."},{"g":"ਸਾਧਸੰਗਤਿ ਕੀ ਭੀਰ ਜਉ ਪਾਈ ਤਉ ਨਾਨਕ ਹਰਿ ਸੰਗਿ ਮਿਰੀਆ ॥੨॥੧॥੨੪॥","t":"saadhasa(n)gat kee bheer jau paiee tau naanak har sa(n)g mireeaa ||2||1||24||","pa":"ਹੇ ਨਾਨਕ! (ਆਖ—) ਜਦੋਂ ਮੈਨੂੰ ਸਾਧ ਸੰਗਤਿ ਦਾ ਸਮਾਗਮ ਪ੍ਰਾਪਤ ਹੋਇਆ, ਤਦੋਂ ਪਰਮਾਤਮਾ ਨਾਲ ਮੇਲ ਹੋ ਗਿਆ ।੨।੧।੨੪।","hi":"हे नानक ! (कह-) जब मुझे साध-संगति का समागम प्राप्त हुआ। तब परमात्मा से मेल हो गया। 2। 1। 24।","en":"When I joined the Saadh Sangat, the Company of the Holy, O Nanak, I met my Lord. ||2||1||24||"}],"audioUrl":null,"youtube":{"id":"IfsWfEe8FRU","artist":"Bhai Nirmal Singh Khalsa"}},{"id":"shabad-3125","type":"Shabad","title":"Aaisee kirapaa moh karahu ","gurmukhiTitle":"ਐਸੀ ਕਿਰਪਾ ਮੋਹਿ ਕਰਹੁ","author":"Guru Arjan Dev Ji","raag":"Raag Bilaaval","ang":828,"source":"Sri Guru Granth Sahib Ji","nitnem":false,"lines":[{"g":"ਬਿਲਾਵਲੁ ਮਹਲਾ ੫ ॥","t":"bilaaval mahalaa panjavaa ||","pa":"","hi":"","en":"Bilaaval, Fifth Mehla:"},{"g":"ਐਸੀ ਕਿਰਪਾ ਮੋਹਿ ਕਰਹੁ ॥","t":"aaisee kirapaa moh karahu ||","pa":"ਹੇ ਪ੍ਰਭੂ! ਮੇਰੇ ਉਤੇ ਇਹ ਮੇਹਰ ਕਰ ਕਿ","hi":"हे प्रभू ! मेरे पर मेहर कर कि","en":"Bless me with such mercy, Lord,"},{"g":"ਸੰਤਹ ਚਰਣ ਹਮਾਰੋ ਮਾਥਾ ਨੈਨ ਦਰਸੁ ਤਨਿ ਧੂਰਿ ਪਰਹੁ ॥੧॥ ਰਹਾਉ ॥","t":"sa(n)teh charan hamaaro maathaa nain dharas tan dhoor parahu ||1|| rahaau ||","pa":"ਸੰਤਾਂ ਦੇ ਚਰਨਾਂ ਉਤੇ ਮੇਰਾ ਮੱਥਾ (ਸਿਰ) ਪਿਆ ਰਹੇ, ਮੇਰੀਆਂ ਅੱਖਾਂ ਵਿਚ ਸੰਤ ਜਨਾਂ ਦਾ ਦਰਸਨ ਟਿਕਿਆ ਰਹੇ, ਮੇਰੇ ਸਰੀਰ ਉਤੇ ਸੰਤਾਂ ਦੇ ਚਰਨਾਂ ਦੀ ਧੂੜ ਪਾਈ ਰੱਖੋ ।੧।ਰਹਾਉ।","hi":"संतों के चरणों पर मेरा माथा (सिर) पड़ा रहे। मेरी आँखों में संत जनों के दर्शन टिके रहें। मेरे शरीर पर संतों के चरणों की धूड़ पड़ी रहे। 1। रहाउ।","en":"that my forehead may touch the feet of the Saints, and my eyes may behold the Blessed Vision of their Darshan, and my body may fall at the dust of their feet. ||1||Pause||"},{"g":"ਗੁਰ ਕੋ ਸਬਦੁ ਮੇਰੈ ਹੀਅਰੈ ਬਾਸੈ ਹਰਿ ਨਾਮਾ ਮਨ ਸੰਗਿ ਧਰਹੁ ॥","t":"gur ko sabadh merai heearai baasai har naamaa man sa(n)g dharahu ||","pa":"(ਹੇ ਪ੍ਰਭੂ! ਮੇਰੇ ਉਤੇ ਇਹ ਮੇਹਰ ਕਰੋ—) ਗੁਰੂ ਦਾ ਸ਼ਬਦ ਮੇਰੇ ਹਿਰਦੇ ਵਿਚ (ਸਦਾ) ਵੱਸਦਾ ਰਹੇ, ਹੇ ਹਰੀ! ਆਪਣਾ ਨਾਮ ਮੇਰੇ ਮਨ ਵਿਚ ਟਿਕਾਈ ਰੱਖ ।","hi":"(हे प्रभू ! मेरे पर यह मेहर करो-) गुरू का शबद मेरे हृदय में (सदा) बसता रहे। हे हरी ! अपना नाम मेरे मन में टिकाए रख।","en":"May the Word of the Guru's Shabad abide within my heart, and the Lord's Name be enshrined within my mind."},{"g":"ਤਸਕਰ ਪੰਚ ਨਿਵਾਰਹੁ ਠਾਕੁਰ ਸਗਲੋ ਭਰਮਾ ਹੋਮਿ ਜਰਹੁ ॥੧॥","t":"tasakar pa(n)ch nivaarahu Thaakur sagalo bharamaa hom jarahu ||1||","pa":"ਹੇ ਠਾਕੁਰ! (ਮੇਰੇ ਅੰਦਰੋਂ ਕਾਮਾਦਿਕ) ਪੰਜੇ ਚੋਰ ਕੱਢ ਦੇ, ਮੇਰੀ ਸਾਰੀ ਭਟਕਣਾ ਅੱਗ ਵਿਚ ਸਾੜ ਦੇ ।੧।","hi":"हे ठाकुर ! (मेरे अंदर से कामादिक) पाँचों चोर निकाल दे। मेरी सारी भटकना आग में जला दे। 1।","en":"Drive out the five thieves, O my Lord and Master, and let my doubts all burn like incense. ||1||"},{"g":"ਜੋ ਤੁਮੑ ਕਰਹੁ ਸੋਈ ਭਲ ਮਾਨੈ ਭਾਵਨੁ ਦੁਬਿਧਾ ਦੂਰਿ ਟਰਹੁ ॥","t":"jo tum(h) karahu soiee bhal maanai bhaavan dhubidhaa dhoor Tarahu ||","pa":"(ਹੇ ਪ੍ਰਭੂ! ਮੇਰੇ ਉਤੇ ਇਹ ਮੇਹਰ ਕਰ—) ਜੋ ਕੁਝ ਤੂੰ ਕਰਦਾ ਹੈਂ, ਉਸੇ ਨੂੰ (ਮੇਰਾ ਮਨ) ਚੰਗਾ ਮੰਨੇ । (ਹੇ ਪ੍ਰਭੂ! ਮੇਰੇ ਅੰਦਰੋਂ) ਵਿਤਕਰਿਆਂ ਦਾ ਚੰਗਾ ਲੱਗਣਾ ਕੱਢ ਦੇ ।","hi":"(हे प्रभू मेरे ऊपर यह मेहर कर-) जो कुछ तू करता है। उसी को (मेरा मन) ठीक मान ले। (हे प्रभू ! मेरे अंदर से) भेद-भाव भरी तेर-मेर निकाल दे।","en":"Whatever You do, I accept as good; I have driven out the sense of duality."},{"g":"ਨਾਨਕ ਕੇ ਪ੍ਰਭ ਤੁਮ ਹੀ ਦਾਤੇ ਸੰਤਸੰਗਿ ਲੇ ਮੋਹਿ ਉਧਰਹੁ ॥੨॥੩॥੧੧੯॥","t":"naanak ke prabh tum hee dhaate sa(n)tasa(n)g le moh udharahu ||2||3||119||","pa":"ਹੇ ਪ੍ਰਭੂ! ਤੂੰ ਹੀ ਨਾਨਕ ਨੂੰ ਸਭ ਦਾਤਾਂ ਦੇਣ ਵਾਲਾ ਹੈਂ । (ਨਾਨਕ ਦੀ ਇਹ ਅਰਜ਼ੋਈ ਹੈ—) ਸੰਤਾਂ ਦੀ ਸੰਗਤਿ ਵਿਚ ਰੱਖ ਕੇ ਮੈਨੂੰ (ਨਾਨਕ ਨੂੰ ਕਾਮਾਦਿਕ ਤਸਕਰਾਂ ਤੋਂ) ਬਚਾ ਲੈ ।੨।੩।੧੧੯।","hi":"हे प्रभू ! तू ही नानक को सब दातें देने वाला है। (नानक की यह आरजू है कि) संतों की संगति में रख के मुझे (नानक को कामादिक तस्करों से) बचा ले। 2। 3। 119।","en":"You are Nanak's God, the Great Giver; in the Congregation of the Saints, emancipate me. ||2||3||119||"}],"audioUrl":null,"youtube":{"id":"IdpbNB56nsQ","artist":"Bhai Jarnail Singh"}},{"id":"shabad-2812","type":"Shabad","title":"Laal ra(n)geele preetam manmohan tere dharasan kau ham baare ","gurmukhiTitle":"ਲਾਲ ਰੰਗੀਲੇ ਪ੍ਰੀਤਮ ਮਨਮੋਹਨ ਤੇਰੇ ਦਰਸਨ ਕਉ ਹਮ ਬਾਰੇ","author":"Guru Arjan Dev Ji","raag":"Raag Soohee","ang":738,"source":"Sri Guru Granth Sahib Ji","nitnem":false,"lines":[{"g":"ਸੂਹੀ ਮਹਲਾ ੫ ॥","t":"soohee mahalaa panjavaa ||","pa":"","hi":"","en":"Soohee, Fifth Mehla:"},{"g":"ਕਿਆ ਗੁਣ ਤੇਰੇ ਸਾਰਿ ਸਮੑਾਲੀ ਮੋਹਿ ਨਿਰਗੁਨ ਕੇ ਦਾਤਾਰੇ ॥","t":"kiaa gun tere saar sam(h)aalee moh niragun ke dhaataare ||","pa":"ਮੈਂ ਗੁਣ-ਹੀਨ ਦੇ ਹੇ ਦਾਤਾਰ! ਮੈਂ ਤੇਰੇ ਕੇਹੜੇ ਕੇਹੜੇ ਗੁਣ ਚੇਤੇ ਕਰ ਕੇ ਆਪਣੇ ਹਿਰਦੇ ਵਿਚ ਵਸਾਵਾਂ? (ਮੈਂ ਤਾਂ ਤੇਰਾ ਮੁੱਲ-ਖ਼ਰੀਦਿਆ ਸੇਵਕ ਹਾਂ) ਮੁੱਲ-ਖ਼ਰੀਦਿਆ ਨੌਕਰ ਕੋਈ ਚਲਾਕੀ ਦੀ ਗੱਲ ਨਹੀਂ ਕਰ ਸਕਦਾ","hi":"मुझ गुणहीन के हे दातार ! मैं तेरे कौन-कौन से गुण याद कर-कर के अपने दिल में बसाऊँ।","en":"What virtues and excellences of Yours should I cherish and contemplate? I am worthless, while You are the Great Giver."},{"g":"ਬੈ ਖਰੀਦੁ ਕਿਆ ਕਰੇ ਚਤੁਰਾਈ ਇਹੁ ਜੀਉ ਪਿੰਡੁ ਸਭੁ ਥਾਰੇ ॥੧॥","t":"bai khareedh kiaa kare chaturaiee ih jeeau pi(n)dd sabh thaare ||1||","pa":"(ਹੇ ਦਾਤਾਰ! ਮੇਰਾ) ਇਹ ਸਰੀਰ ਤੇ ਮੇਰੀ ਇਹ ਜਿੰਦ ਸਭ ਤੇਰੇ ਹੀ ਦਿੱਤੇ ਹੋਏ ਹਨ ।੧।","hi":"(मैं तो तेरा मूल्य खरीदा हुआ सेवक हूँ) मूल्य खरीदा हुआ नौकर कोई चालाकी भरी बात नहीं कर सकता।(हे दातार !् मेरा) ये शरीर और मेरी ये जिंद सब तेरे ही दिए हुए हैं। 1।","en":"I am Your slave - what clever tricks could I ever try? This soul and body are totally Yours||1||"},{"g":"ਲਾਲ ਰੰਗੀਲੇ ਪ੍ਰੀਤਮ ਮਨਮੋਹਨ ਤੇਰੇ ਦਰਸਨ ਕਉ ਹਮ ਬਾਰੇ ॥੧॥ ਰਹਾਉ ॥","t":"laal ra(n)geele preetam manmohan tere dharasan kau ham baare ||1|| rahaau ||","pa":"ਹੇ ਚੋਜੀ ਲਾਲ! ਹੇ ਪ੍ਰੀਤਮ! ਹੇ ਮਨ ਨੂੰ ਮੋਹ ਲੈਣ ਵਾਲੇ! ਅਸੀ ਜੀਵ ਤੇਰੇ ਦਰਸਨ ਤੋਂ ਕੁਰਬਾਨ ਹਾਂ ।੧।ਰਹਾਉ।","hi":"हे चोजी लाल ! हे प्रीतम ! हे मन को मोह लेने वाले ! हम जीव तेरे दर्शनों को कुर्बान हैं। 1।रहाउ।","en":"O my Darling, Blissful Beloved, who fascinates my mind - I am a sacrifice to the Blessed Vision of Your Darshan. ||1||Pause||"},{"g":"ਪ੍ਰਭੁ ਦਾਤਾ ਮੋਹਿ ਦੀਨੁ ਭੇਖਾਰੀ ਤੁਮੑ ਸਦਾ ਸਦਾ ਉਪਕਾਰੇ ॥","t":"prabh dhaataa moh dheen bhekhaaree tum(h) sadhaa sadhaa upakaare ||","pa":"(ਹੇ ਦਾਤਾਰ!) ਤੂੰ ਮਾਲਕ ਹੈਂ, ਦਾਤਾਂ ਦੇਣ ਵਾਲਾ ਹੈਂ, ਮੈਂ (ਤੇਰੇ ਦਰ ਤੇ) ਕੰਗਾਲ ਮੰਗਤਾ ਹਾਂ, ਤੂੰ ਸਦਾ ਹੀ ਤੂੰ ਸਦਾ ਹੀ ਮੇਰੇ ਉਤੇ ਮੇਹਰਬਾਨੀਆਂ ਕਰਦਾ ਹੈਂ","hi":"(हे दातार !) तू मालिक है।दातें देने वाला है।मैं (तेरे दर पर) कंगाल मंगता हूँ।तू सदा ही।तू हमेशा ही मेरे ऊपर मेहरवानियाँ करता है।","en":"O God, You are the Great Giver, and I am just a poor beggar; You are forever and ever benevolent."},{"g":"ਸੋ ਕਿਛੁ ਨਾਹੀ ਜਿ ਮੈ ਤੇ ਹੋਵੈ ਮੇਰੇ ਠਾਕੁਰ ਅਗਮ ਅਪਾਰੇ ॥੨॥","t":"so kichh naahee j mai te hovai mere Thaakur agam apaare ||2||","pa":"ਹੇ ਮੇਰੇ ਅਪਹੁੰਚ ਅਤੇ ਬੇਅੰਤ ਮਾਲਕ! ਕੋਈ ਐਸਾ ਕੰਮ ਨਹੀਂ ਜੋ (ਤੇਰੀ ਮਦਦ ਤੋਂ ਬਿਨਾ) ਮੈਥੋਂ ਹੋ ਸਕੇ ।੨।","hi":"हे मेरे अपहुँच और बेअंत मालिक ! कोई ऐसा काम नहीं जो (बग़ैर तेरी मदद के) मुझसे हो सके। 2।","en":"I cannot accomplish anything by myself, O my Unapproachable and Infinite Lord and Master. ||2||"},{"g":"ਕਿਆ ਸੇਵ ਕਮਾਵਉ ਕਿਆ ਕਹਿ ਰੀਝਾਵਉ ਬਿਧਿ ਕਿਤੁ ਪਾਵਉ ਦਰਸਾਰੇ ॥","t":"kiaa sev kamaavau kiaa keh reejhaavau bidh kit paavau dharasaare ||","pa":"ਹੇ ਪ੍ਰਭੂ! ਮੈਂ ਤੇਰੀ ਕੇਹੜੀ ਸੇਵਾ ਕਰਾਂ? ਮੈਂ ਕੀਹ ਆਖ ਕੇ ਤੈਨੂੰ ਖ਼ੁਸ਼ ਕਰਾਂ? ਮੈਂ ਕਿਸ ਤਰ੍ਹਾਂ ਤੇਰਾ ਦੀਦਾਰ ਹਾਸਲ ਕਰਾਂ? ਤੇਰੀ ਹਸਤੀ ਦਾ ਮਾਪ ਨਹੀਂ ਲੱਭ ਸਕਦਾ, ਤੇਰੇ ਗੁਣਾਂ ਦਾ ਅੰਤ ਨਹੀਂ ਪੈ ਸਕਦਾ","hi":"हे प्रभू ! मैं तेरी कौन सी सेवा करूं।मैं क्या कह के तुझे प्रसन्न करूँ।मैं किस तरह तेरे दीदार हासिल करूँ।","en":"What service can I perform? What should I say to please You? How can I gain the Blessed Vision of Your Darshan?"},{"g":"ਮਿਤਿ ਨਹੀ ਪਾਈਐ ਅੰਤੁ ਨ ਲਹੀਐ ਮਨੁ ਤਰਸੈ ਚਰਨਾਰੇ ॥੩॥","t":"mit nahee paieeaai a(n)t na laheeaai man tarasai charanaare ||3||","pa":"ਮੇਰਾ ਮਨ ਸਦਾ ਤੇਰੇ ਚਰਨਾਂ ਵਿਚ ਪਏ ਰਹਿਣ ਨੂੰ ਤਰਸਦਾ ਹੈ ।੩।","hi":"तेरी हस्ती का नाप नहीं पाया जा सकता।तेरे गुणों का अंत नहीं पाया जा सकता।मेरा मन सदा तेरे चरणों में पड़े रहने को तरसता है। 3।","en":"Your extent cannot be found - Your limits cannot be found. My mind longs for Your Feet. ||3||"},{"g":"ਪਾਵਉ ਦਾਨੁ ਢੀਠੁ ਹੋਇ ਮਾਗਉ ਮੁਖਿ ਲਾਗੈ ਸੰਤ ਰੇਨਾਰੇ ॥","t":"paavau dhaan ddeeTh hoi maagau mukh laagai sa(n)t renaare ||","pa":"ਹੇ ਪ੍ਰਭੂ! ਮੈਂ ਢੀਠ ਹੋ ਕੇ (ਮੁੜ ਮੁੜ, ਤੇਰੇ ਦਰ ਤੋਂ) ਮੰਗਦਾ ਹਾਂ, ਮੈਨੂੰ ਇਹ ਦਾਨ ਮਿਲ ਜਾਏ ਕਿ ਮੇਰੇ ਮੱਥੇ ਉਤੇ ਤੇਰੇ ਸੰਤ ਜਨਾਂ ਦੇ ਚਰਨਾਂ ਦੀ ਧੂੜ ਲੱਗਦੀ ਰਹ","hi":"हे प्रभू ! मैं ढीठ हो के (बार-बार तेरे दर से) माँगता हूँ।मुझे ये दान मिल जाए कि मेरे माथे पर तेरे संत जनों के चरणों की धूल लगती रहे।","en":"I beg with persistence to receive this gift, that the dust of the Saints might touch my face."},{"g":"ਜਨ ਨਾਨਕ ਕਉ ਗੁਰਿ ਕਿਰਪਾ ਧਾਰੀ ਪ੍ਰਭਿ ਹਾਥ ਦੇਇ ਨਿਸਤਾਰੇ ॥੪॥੬॥","t":"jan naanak kau gur kirapaa dhaaree prabh haath dhei nisataare ||4||6||","pa":"ਹੇ ਨਾਨਕ! (ਆਖ—) ਜਿਸ ਦਾਸ ਉਤੇ ਗੁਰੂ ਨੇ ਮੇਹਰ ਕਰ ਦਿੱਤੀ, ਪ੍ਰਭੂ ਨੇ (ਉਸ ਨੂੰ ਆਪਣੇ) ਹੱਥ ਦੇ ਕੇ (ਸੰਸਾਰ-ਸਮੁੰਦਰ ਤੋਂ) ਪਾਰ ਲੰਘਾ ਲਿਆ ।੪।੬।","hi":"हे नानक ! (कह–) जिस दास पर गुरू ने मेहर कर दी।प्रभू ने (उसको अपना) हाथ दे के (संसार-समुंद्र से) पार लंघा लिया। 4। 6।","en":"The Guru has showered His Mercy upon servant Nanak; reaching out with His Hand, God has delivered him. ||4||6||"}],"audioUrl":null,"youtube":{"id":"PnFlP8lL27Q","artist":"Bhai Jarnail Singh"}},{"id":"shabad-3521","type":"Shabad","title":"Sun sajan preetam meriaa mai satigur dheh dhikhaal ","gurmukhiTitle":"ਸੁਣਿ ਸਜਣ ਪ੍ਰੀਤਮ ਮੇਰਿਆ ਮੈ ਸਤਿਗੁਰੁ ਦੇਹੁ ਦਿਖਾਲਿ","author":"Guru Arjan Dev Ji","raag":"Raag Raamkalee","ang":957,"source":"Sri Guru Granth Sahib Ji","nitnem":false,"lines":[{"g":"ਸਲੋਕੁ ਮਃ ੫ ॥","t":"salok mahalaa panjavaa ||","pa":"","hi":"","en":"Shalok, Fifth Mehla:"},{"g":"ਸੁਣਿ ਸਜਣ ਪ੍ਰੀਤਮ ਮੇਰਿਆ ਮੈ ਸਤਿਗੁਰੁ ਦੇਹੁ ਦਿਖਾਲਿ ॥","t":"sun sajan preetam meriaa mai satigur dheh dhikhaal ||","pa":"ਹੇ ਮੇਰੇ ਪਿਆਰੇ ਸੱਜਣ ਪ੍ਰਭੂ! (ਮੇਰੀ ਬੇਨਤੀ) ਸੁਣ, ਮੈਨੂੰ ਗੁਰੂ ਦਾ ਦੀਦਾਰ ਕਰਾ ਦੇਹ;","hi":"हे मेरे प्यारे सज्जन प्रभू ! (मेरी विनती) सुन। मुझे गुरू के दीदार करा दे;","en":"Listen, O my beloved friend: please show me the True Guru."},{"g":"ਹਉ ਤਿਸੁ ਦੇਵਾ ਮਨੁ ਆਪਣਾ ਨਿਤ ਹਿਰਦੈ ਰਖਾ ਸਮਾਲਿ ॥","t":"hau tis dhevaa man aapanaa nit hiradhai rakhaa samaal ||","pa":"ਮੈਂ ਗੁਰੂ ਨੂੰ ਆਪਣਾ ਮਨ ਦੇ ਦੇਵਾਂਗਾ ਤੇ ਉਸ ਨੂੰ ਸਦਾ ਆਪਣੇ ਹਿਰਦੇ ਵਿਚ ਸਾਂਭ ਕੇ ਰੱਖਾਂਗਾ,","hi":"मैं गुरू को अपना मन दे दूँगा और उसको सदा अपने हृदय में संभाल के रखूँगा।","en":"I dedicate my mind to Him; I keep Him continually enshrined within my heart."},{"g":"ਇਕਸੁ ਸਤਿਗੁਰ ਬਾਹਰਾ ਧ੍ਰਿਗੁ ਜੀਵਣੁ ਸੰਸਾਰਿ ॥","t":"eikas satigur baaharaa dhirag jeevan sa(n)saar ||","pa":"(ਕਿਉਂਕਿ) ਇਕ ਗੁਰੂ ਤੋਂ ਬਿਨਾ ਜਗਤ ਵਿਚ ਜਿਊਣਾ ਫਿਟਕਾਰ-ਜੋਗ ਹੈ (ਗੁਰੂ ਦੇ ਦੱਸੇ ਰਾਹ ਉਤੇ ਤੁਰਨ ਤੋਂ ਬਿਨਾ ਜਗਤ ਵਿਚ ਫਿਟਕਾਰਾਂ ਹੀ ਪੈਂਦੀਆਂ ਹਨ) ।","hi":"(क्योंकि) एक गुरू के बिना जगत में जीना धिक्कारयोग्य है (गुरू के बताए हुए राह पर चले बिना जगत में धिक्कारना ही मिलती हैं)।","en":"Without the One and Only True Guru, life in this world is cursed."},{"g":"ਜਨ ਨਾਨਕ ਸਤਿਗੁਰੁ ਤਿਨਾ ਮਿਲਾਇਓਨੁ ਜਿਨ ਸਦ ਹੀ ਵਰਤੈ ਨਾਲਿ ॥੧॥","t":"jan naanak satigur tinaa milaion jin sadh hee varatai naal ||1||","pa":"ਹੇ ਦਾਸ ਨਾਨਕ! ਉਸ (ਪ੍ਰਭੂ) ਨੇ ਉਹਨਾਂ (ਭਾਗਾਂ ਵਾਲਿਆਂ) ਨੂੰ ਗੁਰੂ ਮਿਲਾਇਆ ਹੈ, ਜਿਨ੍ਹਾਂ ਦੇ ਨਾਲ ਪ੍ਰਭੂ ਆਪ ਸਦਾ ਵੱਸਦਾ ਹੈ ।੧।","hi":"हे दास नानक ! उस (प्रभू) ने उन (भाग्यशालियों) को गुरू मिलाया है। जिनके साथ प्रभू स्वयं बसता है। 1।","en":"O servant Nanak, they alone meet the True Guru, with whom He constantly abides. ||1||"}],"audioUrl":null,"youtube":{"id":"P-xESmdeFjU","artist":"Bhai Ravinder Singh"}},{"id":"shabad-1452","type":"Shabad","title":"Man kiau bairaag karahigaa satigur meraa pooraa ","gurmukhiTitle":"ਮਨ ਕਿਉ ਬੈਰਾਗੁ ਕਰਹਿਗਾ ਸਤਿਗੁਰੁ ਮੇਰਾ ਪੂਰਾ","author":"Guru Arjan Dev Ji","raag":"Raag Aasaa","ang":375,"source":"Sri Guru Granth Sahib Ji","nitnem":false,"lines":[{"g":"ਆਸਾ ਮਹਲਾ ੫ ॥","t":"aasaa mahalaa panjavaa ||","pa":"","hi":"","en":"Aasaa, Fifth Mehla:"},{"g":"ਪ੍ਰਭੁ ਹੋਇ ਕ੍ਰਿਪਾਲੁ ਤ ਇਹੁ ਮਨੁ ਲਾਈ ॥","t":"prabh hoi kirapaal ta ih man laiee ||","pa":"(ਹੇ ਭਾਈ!) ਜੇ ਪਰਮਾਤਮਾ ਦਇਆਵਾਨ ਹੋਵੇ ਤਾਂ ਹੀ ਮੈਂ ਇਹ ਮਨ (ਗੁਰੂ ਦੇ ਚਰਨਾਂ ਵਿਚ) ਜੋੜ ਸਕਦਾ ਹਾਂ,","hi":"(हे भाई !) यदि परमात्मा दयावान हो तो ही मैं ये मन (गुरू के चरणों में) जोड़ सकता हूँ।","en":"When God shows His Mercy, then this mind is focused on Him."},{"g":"ਸਤਿਗੁਰੁ ਸੇਵਿ ਸਭੈ ਫਲ ਪਾਈ ॥੧॥","t":"satigur sev sabhai fal paiee ||1||","pa":"ਤਦੋਂ ਹੀ ਗੁਰੂ ਦੀ (ਦੱਸੀ) ਸੇਵਾ ਕਰ ਕੇ ਮਨ-ਇੱਜ਼ਤ ਫਲ ਪ੍ਰਾਪਤ ਕਰ ਸਕਦਾ ਹਾਂ ।੧।","hi":"तब ही गुरू की (बताई) सेवा करके मन-इच्छित फल प्राप्त कर सकता हूँ। 1।","en":"Serving the True Guru, all rewards are obtained. ||1||"},{"g":"ਮਨ ਕਿਉ ਬੈਰਾਗੁ ਕਰਹਿਗਾ ਸਤਿਗੁਰੁ ਮੇਰਾ ਪੂਰਾ ॥","t":"man kiau bairaag karahigaa satigur meraa pooraa ||","pa":"ਹੇ ਮੇਰੇ ਮਨ! ਤੂੰ ਕਿਉਂ ਘਾਬਰਦਾ ਹੈਂ? (ਯਕੀਨ ਰੱਖ, ਤੇਰੇ ਸਿਰ ਉਤੇ ਉਹ) ਪਿਆਰਾ ਸਤਿਗੁਰੂ (ਰਾਖਾ) ਹੈ","hi":"हे मेरे मन ! तू क्यूँ घबराता है। (यकीन रख। तेरे सिर पर वह) प्यारा सतिगुरू (रखवाला) है","en":"O my mind, why are you so sad? My True Guru is Perfect."},{"g":"ਮਨਸਾ ਕਾ ਦਾਤਾ ਸਭ ਸੁਖ ਨਿਧਾਨੁ ਅੰਮ੍ਰਿਤ ਸਰਿ ਸਦ ਹੀ ਭਰਪੂਰਾ ॥੧॥ ਰਹਾਉ ॥","t":"manasaa kaa dhaataa sabh sukh nidhaan a(n)mirat sar sadh hee bharapooraa ||1|| rahaau ||","pa":"ਜੋ ਮਨ ਦੀਆਂ ਲੋੜਾਂ ਪੂਰੀਆਂ ਕਰਨ ਵਾਲਾ ਹੈ ਜੋ ਸਾਰੇ ਸੁਖਾਂ ਦਾ ਖ਼ਜ਼ਾਨਾ ਹੈ ਅਤੇ ਜਿਸ ਅੰਮ੍ਰਿਤ ਦੇ ਸਰੋਵਰ-ਗੁਰੂ ਵਿਚ ਆਤਮਕ ਜੀਵਨ ਦੇਣ ਵਾਲਾ ਨਾਮ-ਜਲ ਨਕਾ-ਨਕ ਭਰਿਆ ਹੋਇਆ ਹੈ ।੧।ਰਹਾਉ।","hi":"जो मन की जरूरतें पूरी करने वाला है जो सारे सुखों का खजाना है और जिस अमृत के सरोवर-गुरू में आत्मिक जीवन देने वाला नाम-जल नाको-नाक भरा हुआ है। 1। रहाउ।","en":"He is the Giver of blessings, the treasure of all comforts; His Ambrosial Pool of Nectar is always overflowing. ||1||Pause||"},{"g":"ਚਰਣ ਕਮਲ ਰਿਦ ਅੰਤਰਿ ਧਾਰੇ ॥","t":"charan kamal ridh a(n)tar dhaare ||","pa":"(ਹੇ ਭਾਈ!) ਜਿਸ ਮਨੁੱਖ ਨੇ ਆਪਣੇ ਹਿਰਦੇ ਵਿਚ (ਗੁਰੂ ਦੇ) ਸੋਹਣੇ ਚਰਨ ਟਿਕਾ ਲਏ","hi":"(हे भाई !) जिस मनुष्य ने अपने हृदय में (गुरू के) सुंदर चरण टिका लिए हैं","en":"One who enshrines His Lotus Feet within the heart,"},{"g":"ਪ੍ਰਗਟੀ ਜੋਤਿ ਮਿਲੇ ਰਾਮ ਪਿਆਰੇ ॥੨॥","t":"pragaTee jot mile raam piaare ||2||","pa":"(ਉਸ ਦੇ ਅੰਦਰ) ਪਰਮਾਤਮਾ ਦੀ ਜੋਤਿ ਜਗ ਪਈ, ਉਸ ਨੂੰ ਪਿਆਰਾ ਪ੍ਰਭੂ ਮਿਲ ਪਿਆ ।੨।","hi":"(उसके अंदर) परमात्माकी ज्योति जग पड़ी, उसे प्यारा प्रभू मिल गया। 2।","en":"meets the Beloved Lord; the Divine Light is revealed to him. ||2||"},{"g":"ਪੰਚ ਸਖੀ ਮਿਲਿ ਮੰਗਲੁ ਗਾਇਆ ॥","t":"pa(n)ch sakhee mil ma(n)gal gaiaa ||","pa":"ਉਸ ਦੇ ਪੰਜੇ ਗਿਆਨ-ਇੰਦ੍ਰਿਆਂ ਨੇ ਮਿਲ ਕੇ","hi":"उसकी पाँचों ज्ञानेन्द्रियों ने मिल के मंगल गीत गाए","en":"The five companions have met together to sing the songs of joy."},{"g":"ਅਨਹਦ ਬਾਣੀ ਨਾਦੁ ਵਜਾਇਆ ॥੩॥","t":"anahadh baanee naadh vajaiaa ||3||","pa":"ਪਰਮਾਤਮਾ ਦੀ ਸਿਫ਼ਤਿ-ਸਾਲਾਹ ਦੀ ਬਾਣੀ ਦਾ ਵਾਜਾ ਇਕ-ਰਸ ਵਜਾਣਾ ਸ਼ੁਰੂ ਕਰ ਦਿੱਤਾ ।੩।","hi":"परमात्मा की सिफत सालाह की बाणी का बाजा एक-रस बजाना शुरू कर दिया। 3।","en":"The unstruck melody, the sound current of the Naad, vibrates and resounds. ||3||"},{"g":"ਗੁਰੁ ਨਾਨਕੁ ਤੁਠਾ ਮਿਲਿਆ ਹਰਿ ਰਾਇ ॥","t":"gur naanak tuThaa miliaa har rai ||","pa":"ਹੇ ਨਾਨਕ! ਜਿਸ ਮਨੁੱਖ ਉਤੇ ਗੁਰੂ ਪ੍ਰਸੰਨ ਹੋ ਪਿਆ ਉਸ ਨੂੰ ਪ੍ਰਭੂ-ਪਾਤਿਸ਼ਾਹ ਮਿਲ ਪਿਆ,","hi":"हे नानक ! जिस मनुष्य पे गुरू प्रसन्न हो गया उसे प्रभू पातशाह मिल गया।","en":"O Nanak, when the Guru is totally pleased, one meets the Lord, the King."},{"g":"ਸੁਖਿ ਰੈਣਿ ਵਿਹਾਣੀ ਸਹਜਿ ਸੁਭਾਇ ॥੪॥੧੭॥","t":"sukh rain vihaanee sahaj subhai ||4||17||","pa":"ਉਸ ਦੀ (ਜ਼ਿੰਦਗੀ ਦੀ) ਰਾਤ ਸੁਖ ਵਿਚ ਆਤਮਕ ਅਡੋਲਤਾ ਵਿਚ ਬੀਤਣ ਲੱਗ ਪਈ ।੪।੧੭।","hi":"उसकी (जिंदगी की) रात सुख में आत्मिक अडोलता में बीतने लगी। 4। 17।","en":"Then, the night of one's life passes in peace and natural ease. ||4||17||"}],"audioUrl":null,"youtube":{"id":"qcxpaSvb-lM","artist":"Bhai Ravinder Singh"}},{"id":"shabad-1528","type":"Shabad","title":"Har kaa naam ridhai nit dhiaaiee ","gurmukhiTitle":"ਹਰਿ ਕਾ ਨਾਮੁ ਰਿਦੈ ਨਿਤ ਧਿਆਈ","author":"Guru Arjan Dev Ji","raag":"Raag Aasaa","ang":394,"source":"Sri Guru Granth Sahib Ji","nitnem":false,"lines":[{"g":"ਆਸਾ ਘਰੁ ੭ ਮਹਲਾ ੫ ॥","t":"aasaa ghar satvaa mahalaa panjavaa ||","pa":"","hi":"","en":"Aasaa, Seventh House, Fifth Mehla:"},{"g":"ਹਰਿ ਕਾ ਨਾਮੁ ਰਿਦੈ ਨਿਤ ਧਿਆਈ ॥","t":"har kaa naam ridhai nit dhiaaiee ||","pa":"(ਹੇ ਭਾਈ! ਅੰਗ-ਸੰਗ ਵੱਸਦੇ ਗੁਰੂ ਦੀ ਹੀ ਕਿਰਪਾ ਨਾਲ) ਮੈਂ ਪਰਮਾਤਮਾ ਦਾ ਨਾਮ ਸਦਾ ਆਪਣੇ ਹਿਰਦੇ ਵਿਚ ਧਿਆਉਂਦਾ ਹਾਂ (ਇਸ ਤਰ੍ਹਾਂ ਮੈਂ ਸੰਸਾਰ-ਸਮੁੰਦਰ ਤੋਂ ਪਾਰ ਲੰਘਣ ਜੋਗਾ ਹੋ ਰਿਹਾ ਹਾਂ)","hi":"(हे भाई ! अंग-संग बसते गुरू की ही कृपा से) मैं परमात्मा का नाम सदा अपने हृदय में ध्याता हूँ (इस तरह मैं संसार-समुंद्र से पार लांघने के योग्य हो रहा हूँ)","en":"Meditate continually on the Name of the Lord within your heart."},{"g":"ਸੰਗੀ ਸਾਥੀ ਸਗਲ ਤਰਾਂਈ ॥੧॥","t":"sa(n)gee saathee sagal taraa(n)iee ||1||","pa":"ਆਪਣੇ ਸੰਗੀਆਂ ਸਾਥੀਆਂ (ਗਿਆਨ-ਇੰਦ੍ਰਿਆਂ) ਨੂੰ ਪਾਰ ਲੰਘਾਣ ਜੋਗਾ ਬਣ ਰਿਹਾ ਹਾਂ ।੧।","hi":"अपने संगियों-साथियों (ज्ञानेन्द्रियों) को पार लंघाने के काबिल बन रहा हूँ। 1।","en":"Thus you shall save all your companions and associates. ||1||"},{"g":"ਗੁਰੁ ਮੇਰੈ ਸੰਗਿ ਸਦਾ ਹੈ ਨਾਲੇ ॥","t":"gur merai sa(n)g sadhaa hai naale ||","pa":"(ਹੇ ਭਾਈ! ਮੇਰਾ) ਗੁਰੂ ਸਦਾ ਮੇਰੇ ਨਾਲ ਵੱਸਦਾ ਹੈ ਮੇਰੇ ਅੰਗ-ਸੰਗ ਰਹਿੰਦਾ ਹ","hi":"(हे भाई ! मेरा) गुरू सदा मेरे साथ बसता है मेरे अंग-संग रहता है","en":"My Guru is always with me, near at hand."},{"g":"ਸਿਮਰਿ ਸਿਮਰਿ ਤਿਸੁ ਸਦਾ ਸਮੑਾਲੇ ॥੧॥ ਰਹਾਉ ॥","t":"simar simar tis sadhaa sam(h)aale ||1|| rahaau ||","pa":"(ਗੁਰੂ ਦੀ ਹੀ ਕਿਰਪਾ ਨਾਲ) ਮੈਂ ਉਸ (ਪਰਮਾਤਮਾ) ਨੂੰ ਸਦਾ ਸਿਮਰ ਕੇ ਸਦਾ ਆਪਣੇ ਹਿਰਦੇ ਵਿਚ ਵਸਾਈ ਰੱਖਦਾ ਹਾਂ ।੧।","hi":"(प्रभू की कृपा से) मैं उस (परमात्मा) को सदा सिमर के सदा अपने दिल में बसाए रखता हूँ। 1।","en":"Meditating, meditating in remembrance on Him, I cherish Him forever. ||1||Pause||"},{"g":"ਤੇਰਾ ਕੀਆ ਮੀਠਾ ਲਾਗੈ ॥","t":"teraa keeaa meeThaa laagai ||","pa":"(ਹੇ ਪ੍ਰਭੂ! ਇਹ ਤੇਰੇ ਮਿਲਾਏ ਹੋਏ ਗੁਰੂ ਦੀ ਮੇਹਰ ਹੈ ਕਿ) ਮੈਨੂੰ ਤੇਰਾ ਕੀਤਾ ਹੋਇਆ ਹਰੇਕ ਕੰਮ ਚੰਗਾ ਲੱਗ ਰਿਹਾ ਹੈ","hi":"(हे प्रभू ! ये तेरे मिलाए हुए गुरू की मेहर ही है कि) मुझे तेरा किया हुआ हरेक काम अच्छा लग रहा है","en":"Your actions seem so sweet to me."},{"g":"ਹਰਿ ਨਾਮੁ ਪਦਾਰਥੁ ਨਾਨਕੁ ਮਾਂਗੈ ॥੨॥੪੨॥੯੩॥","t":"har naam padhaarath naanak maa(n)gai ||2||42||93||","pa":"ਤੇ (ਤੇਰਾ ਦਾਸ) ਨਾਨਕ ਤੇਰੇ ਪਾਸੋਂ ਸਭ ਤੋਂ ਕੀਮਤੀ ਵਸਤ ਤੇਰਾ ਨਾਮ ਮੰਗ ਰਿਹਾ ਹੈ ।੨।੪੨।੯੩।","hi":"और (तेरा दास) नानक तेरे से (तेरी) सबसे कीमती वस्तु तेरा नाम मांग रहा है। 2। 42। 93।","en":"Nanak begs for the treasure of the Naam, the Name of the Lord. ||2||42||93||"}],"audioUrl":null,"youtube":{"id":"2Bx2MDU7E7k","artist":"Singh Bandhu"}},{"id":"shabad-4594","type":"Shabad","title":"He gobi(n)dh he gopaal he dhiaal laal ","gurmukhiTitle":"ਹੇ ਗੋਬਿੰਦ ਹੇ ਗੋਪਾਲ ਹੇ ਦਇਆਲ ਲਾਲ","author":"Guru Arjan Dev Ji","raag":"Raag Malaar","ang":1273,"source":"Sri Guru Granth Sahib Ji","nitnem":false,"lines":[{"g":"ਮਲਾਰ ਮਹਲਾ ੫ ॥","t":"malaar mahalaa panjavaa ||","pa":"","hi":"","en":"Malaar, Fifth Mehla:"},{"g":"ਹੇ ਗੋਬਿੰਦ ਹੇ ਗੋਪਾਲ ਹੇ ਦਇਆਲ ਲਾਲ ॥੧॥ ਰਹਾਉ ॥","t":"he gobi(n)dh he gopaal he dhiaal laal ||1|| rahaau ||","pa":"ਹੇ ਗੋਬਿੰਦ! ਹੇ ਗੋਪਾਲ! ਹੇ ਦਇਆ ਦੇ ਸੋਮੇ! ਹੇ ਸੋਹਣੇ ਪ੍ਰਭੂ! ।੧।ਰਹਾਉ।","hi":"हे गोबिंद ! हे गोपाल ! हे दया के श्रोत ! हे सुंदर प्रभू !। 1। रहाउ।","en":"O Lord of the Universe, O Lord of the World, O Dear Merciful Beloved. ||1||Pause||"},{"g":"ਪ੍ਰਾਨ ਨਾਥ ਅਨਾਥ ਸਖੇ ਦੀਨ ਦਰਦ ਨਿਵਾਰ ॥੧॥","t":"praan naath anaath sakhe dheen dharadh nivaar ||1||","pa":"ਹੇ ਜਿੰਦ ਦੇ ਮਾਲਕ! ਹੇ ਨਿਖਸਮਿਆਂ ਦੇ ਸਹਾਈ! ਹੇ ਗ਼ਰੀਬਾਂ ਦੇ ਦਰਦ ਦੂਰ ਕਰਨ ਵਾਲੇ! ।੧।","hi":"हे जिंद के मालिक ! हे निखसमों के सहायता करने वाले ! हे गरीबों के दर्द दूर करने वाले !। 1।","en":"You are the Master of the breath of life, the Companion of the lost and forsaken, the Destroyer of the pains of the poor. ||1||"},{"g":"ਹੇ ਸਮ੍ਰਥ ਅਗਮ ਪੂਰਨ ਮੋਹਿ ਮਇਆ ਧਾਰਿ ॥੨॥","t":"he samrath agam pooran moh miaa dhaar ||2||","pa":"ਹੇ ਸਭ ਤਾਕਤਾਂ ਦੇ ਮਾਲਕ! ਹੇ ਅਪਹੁੰਚ! ਹੇ ਸਰਬ-ਵਿਆਪਕ! ਮੇਰੇ ਉਤੇ ਮਿਹਰ ਕਰ! ।੨।","hi":"हे सब ताकतों के मालिक ! हे अपहुँच ! हे सर्व व्यापक ! मेरे पर मेहर कर !। 2।","en":"O All-powerful, Inaccessible, Perfect Lord, please shower me with Your Mercy. ||2||"},{"g":"ਅੰਧ ਕੂਪ ਮਹਾ ਭਇਆਨ ਨਾਨਕ ਪਾਰਿ ਉਤਾਰ ॥੩॥੮॥੩੦॥","t":"a(n)dh koop mahaa bhiaan naanak paar utaar ||3||8||30||","pa":"ਹੇ ਨਾਨਕ! (ਆਖ—ਹੇ ਪ੍ਰਭੂ! ਇਹ ਸੰਸਾਰ) ਬੜਾ ਡਰਾਉਣਾ ਖੂਹ ਹੈ ਜਿਸ ਵਿਚ (ਮਾਇਆ ਦੇ ਮੋਹ ਦਾ) ਘੁੱਪ ਹਨੇਰਾ ਹੈ (ਮੈਨੂੰ ਇਸ ਵਿਚੋਂ) ਪਾਰ ਲੰਘਾ ਲੈ ।੩।੮।੩੦।","hi":"हे नानक ! (कह- हे प्रभू ! यह संसार) बड़ा डरावना कूँआ हैं जिसमें (माया के मोह का) घोर अंधेरा है (मुझे इसमें से) पार लंघा ले। 3। 8। 30।","en":"Please, carry Nanak across the terrible, deep dark pit of the world to the other side. ||3||8||30||"}],"audioUrl":null,"youtube":{"id":"KMRJneCk5B0","artist":"Singh Bandhu"}},{"id":"shabad-1364","type":"Shabad","title":"Moh na bisaarahu mai jan teraa ","gurmukhiTitle":"ਮੋਹਿ ਨ ਬਿਸਾਰਹੁ ਮੈ ਜਨੁ ਤੇਰਾ","author":"Bhagat Ravi Das Ji","raag":"Raag Gauree","ang":345,"source":"Sri Guru Granth Sahib Ji","nitnem":false,"lines":[{"g":"ਰਾਗੁ ਗਉੜੀ ਰਵਿਦਾਸ ਜੀ ਕੇ ਪਦੇ ਗਉੜੀ ਗੁਆਰੇਰੀ","t":"raag gauRee ravidhaas jee ke padhe gauRee guaareree","pa":"","hi":"","en":"Raag Gauree, Padhay Of Ravi Daas Jee, Gauree Gwaarayree:"},{"g":"ੴ ਸਤਿਨਾਮੁ ਕਰਤਾ ਪੁਰਖੁ ਗੁਰਪ੍ਰਸਾਦਿ ॥","t":"ikOankaar satinaam karataa purakh guraprasaadh ||","pa":"","hi":"","en":"One Universal Creator God. Truth Is The Name. Creative Being Personified. By Guru's Grace:"},{"g":"ਮੇਰੀ ਸੰਗਤਿ ਪੋਚ ਸੋਚ ਦਿਨੁ ਰਾਤੀ ॥","t":"meree sa(n)gat poch soch dhin raatee ||","pa":"(ਹੇ ਪ੍ਰਭੂ!) ਦਿਨ ਰਾਤ ਮੈਨੂੰ ਇਹ ਸੋਚ ਰਹਿੰਦੀ ਹੈ (ਮੇਰਾ ਕੀਹ ਬਣੇਗਾ?) ਮਾੜਿਆਂ ਨਾਲ ਮੇਰਾ ਬਹਿਣ-ਖਲੋਣ ਹੈ,","hi":"(हे प्रभू !) दिन रात मुझे ये सोच रहती है (मेरा क्या बनेगा?) बुरे लोगों के साथ मेरा उठना-बैठना है।","en":"The company I keep is wretched and low, and I am anxious day and night;"},{"g":"ਮੇਰਾ ਕਰਮੁ ਕੁਟਿਲਤਾ ਜਨਮੁ ਕੁਭਾਂਤੀ ॥੧॥","t":"meraa karam kuTilataa janam kubhaa(n)tee ||1||","pa":"ਖੋਟ ਮੇਰਾ (ਨਿੱਤ-ਕਰਮ) ਹੈ; ਮੇਰਾ ਜਨਮ (ਭੀ) ਨੀਵੀਂ ਜਾਤਿ ਵਿਚੋਂ ਹੈ ।੧।","hi":"खोट मेरा (नित्य कर्म) है; मेरा जनम (भी) नीच जाति में से है। 1।","en":"my actions are crooked, and I am of lowly birth. ||1||"},{"g":"ਰਾਮ ਗੁਸਈਆ ਜੀਅ ਕੇ ਜੀਵਨਾ ॥","t":"raam gusieeaa jeea ke jeevanaa ||","pa":"ਹੇ ਮੇਰੇ ਰਾਮ! ਹੇ ਮੇਰੇ ਰਾਮ! ਹੇ ਧਰਤੀ ਦੇ ਸਾਈਂ! ਹੇ ਮੇਰੀ ਜਿੰਦ ਦੇ ਆਸਰੇ!","hi":"हे मेरे राम ! हे मेरे राम ! हे धरती के साई ! हे मेरी जिंद के आसरे !","en":"O Lord, Master of the earth, Life of the soul,"},{"g":"ਮੋਹਿ ਨ ਬਿਸਾਰਹੁ ਮੈ ਜਨੁ ਤੇਰਾ ॥੧॥ ਰਹਾਉ ॥","t":"moh na bisaarahu mai jan teraa ||1|| rahaau ||","pa":"ਮੈ­ਨੂੰ ਨਾਹ ਵਿਸਾਰੀਂ, ਮੈਂ ਤੇਰਾ ਦਾਸ ਹਾਂ ।੧।ਰਹਾਉ।","hi":"मुझे ना बिसारना। मैं तेरा दास हूँ। 1। रहाउ।","en":"please do not forget me! I am Your humble servant. ||1||Pause||"},{"g":"ਮੇਰੀ ਹਰਹੁ ਬਿਪਤਿ ਜਨ ਕਰਹੁ ਸੁਭਾਈ ॥","t":"meree harahu bipat jan karahu subhaiee ||","pa":"(ਹੇ ਪ੍ਰਭੂ! ਮੇਰੀ ਇਹ ਬਿਪਤਾ ਕੱਟ; ਮੈਨੂੰ ਸੇਵਕ ਨੂੰ ਚੰਗੀ ਭਾਵਨਾ ਵਾਲਾ ਬਣਾ ਲੈ;","hi":"(हे प्रभू !) मेरी ये बिपता काट; मुझ सेवक को अच्छी भावना वाला बना ले;","en":"Take away my pains, and bless Your humble servant with Your Sublime Love."},{"g":"ਚਰਣ ਨ ਛਾਡਉ ਸਰੀਰ ਕਲ ਜਾਈ ॥੨॥","t":"charan na chhaaddau sareer kal jaiee ||2||","pa":"ਚਾਹੇ ਮੇਰੇ ਸਰੀਰ ਦੀ ਸੱਤਿਆ ਭੀ ਚਲੀ ਜਾਵੇ, (ਹੇ ਰਾਮ!) ਮੈਂ ਤੇਰੇ ਚਰਨ ਨਹੀਂ ਛੱਡਾਂਗਾ ।੨।","hi":"चाहे मेरे शरीर की सक्ता भी चली जाए। (हे राम !) मैं तेरे चरण नहीं छोड़ूँगा। 2।","en":"I shall not leave Your Feet, even though my body may perish. ||2||"},{"g":"ਕਹੁ ਰਵਿਦਾਸ ਪਰਉ ਤੇਰੀ ਸਾਭਾ ॥","t":"kahu ravidhaas parau teree saabhaa ||","pa":"ਹੇ ਰਵਿਦਾਸ! (ਪ੍ਰਭੂ-ਦਰ ਤੇ) ਆਖ—(ਹੇ ਪ੍ਰਭੂ!) ਮੈਂ ਤੇਰੀ ਸ਼ਰਨ ਪਿਆ ਹਾਂ,","hi":"हे रविदास ! (प्रभू दर पर) कह– (हे प्रभू !) मैं तेरी शरण पड़ा हूँ।","en":"Says Ravi Daas, I seek the protection of Your Sanctuary;"},{"g":"ਬੇਗਿ ਮਿਲਹੁ ਜਨ ਕਰਿ ਨ ਬਿਲਾਂਬਾ ॥੩॥੧॥","t":"beg milahu jan kar na bilaa(n)baa ||3||1||","pa":"ਮੈਨੂੰ ਸੇਵਕ ਨੂੰ ਛੇਤੀ ਮਿਲੋ, ਢਿੱਲ ਨਾਹ ਕਰ ।੩।੧।","hi":"मुझ सेवक को जल्दी मिलो। ढील ना कर। 3। 1।","en":"please, meet Your humble servant - do not delay! ||3||1||"},{"g":"ਬੇਗਮ ਪੁਰਾ ਸਹਰ ਕੋ ਨਾਉ ॥","t":"begam puraa sahar ko naau ||","pa":"(ਜਿਸ ਆਤਮਕ ਅਵਸਥਾ-ਰੂਪ ਸ਼ਹਿਰ ਵਿਚ ਮੈਂ ਵੱਸਦਾ ਹਾਂ) ਉਸ ਸ਼ਹਿਰ ਦਾ ਨਾਮ ਹੈ ਬੇ-ਗ਼ਮਪੁਰਾ (ਭਾਵ, ਉਸ ਅਵਸਥਾ ਵਿਚ ਕੋਈ ਗ਼ਮ ਨਹੀਂ ਪੋਹ ਸਕਦਾ);","hi":"(जिस आत्मिक-अवस्था रूपी शहर में मैं बसता हूँ) उस शहर का नाम है बे-ग़मपुरा (भाव। उस अवस्था में कोई ग़म नहीं छू सकता);","en":"Baygumpura, 'the city without sorrow', is the name of the town."},{"g":"ਦੂਖੁ ਅੰਦੋਹੁ ਨਹੀ ਤਿਹਿ ਠਾਉ ॥","t":"dhookh a(n)dhoh nahee teh Thaau ||","pa":"ਉਸ ਥਾਂ ਨਾਹ ਕੋਈ ਦੁੱਖ ਹੈ, ਨਾਹ ਚਿੰਤਾ","hi":"उस जगह पर ना कोई दुख है। ना चिंता और ना कोई घबराहट।","en":"There is no suffering or anxiety there."},{"g":"ਨਾਂ ਤਸਵੀਸ ਖਿਰਾਜੁ ਨ ਮਾਲੁ ॥","t":"naa(n) tasavees khiraaj na maal ||","pa":"ਨਾਹ ਕੋਈ ਘਬਰਾਹਟ, ਉਥੇ ਦੁਨੀਆ ਵਾਲੀ ਜਾਇਦਾਦ ਨਹੀਂ ਅਤੇ ਨਾਹ ਹੀ ਉਸ ਜਾਇਦਾਦ ਨੂੰ ਮਸੂਲ ਹੈ;","hi":"वहां दुनिया वाली घबराहट नहीं और ना ही उस जायदाद को मसुल है;","en":"There are no troubles or taxes on commodities there."},{"g":"ਖਉਫੁ ਨ ਖਤਾ ਨ ਤਰਸੁ ਜਵਾਲੁ ॥੧॥","t":"khauf na khataa na taras javaal ||1||","pa":"ਉਸ ਅਵਸਥਾ ਵਿਚ ਕਿਸੇ ਪਾਪ ਕਰਮ ਕਰਨ ਦਾ ਖ਼ਤਰਾ ਨਹੀਂ; ਕੋਈ ਡਰ ਨਹੀਂ; ਕੋਈ ਗਿਰਾਵਟ ਨਹੀਂ ।੧।","hi":"उस अवस्था में किसी पाप कर्म करने का खतरा नहीं; कोई डर नहीं; कोई गिरावट नहीं। 1।","en":"There is no fear, blemish or downfall there. ||1||"},{"g":"ਅਬ ਮੋਹਿ ਖੂਬ ਵਤਨ ਗਹ ਪਾਈ ॥","t":"ab moh khoob vatan geh paiee ||","pa":"ਹੇ ਮੇਰੇ ਵੀਰ! ਹੁਣ ਮੈਂ ਵੱਸਣ ਲਈ ਸੋਹਣੀ ਥਾਂ ਲੱਭ ਲਈ ਹੈ,","hi":"हे मेरे वीर ! अब मैंने बसने के लिए सुंदर जगह ढूँढ ली है।","en":"Now, I have found this most excellent city."},{"g":"ਊਹਾਂ ਖੈਰਿ ਸਦਾ ਮੇਰੇ ਭਾਈ ॥੧॥ ਰਹਾਉ ॥","t":"uoohaa(n) khair sadhaa mere bhaiee ||1|| rahaau ||","pa":"ਉਥੇ ਸਦਾ ਸੁਖ ਹੀ ਸੁਖ ਹੈ ।੧।ਰਹਾਉ।","hi":"वहां सदा सुख ही सुख है। 1। रहाउ।","en":"There is lasting peace and safety there, O Siblings of Destiny. ||1||Pause||"},{"g":"ਕਾਇਮੁ ਦਾਇਮੁ ਸਦਾ ਪਾਤਿਸਾਹੀ ॥","t":"kaim dhaim sadhaa paatisaahee ||","pa":"ਉਹ (ਆਤਮਕ ਅਵਸਥਾ ਇਕ ਐਸੀ) ਪਾਤਸ਼ਾਹੀ (ਹੈ ਜੋ) ਸਦਾ ਹੀ ਟਿਕੀ ਰਹਿਣ ਵਾਲੀ ਹੈ,","hi":"वह (आत्मिक अवस्था एक ऐसी) बादशाहत ( है जो) सदा ही टिकी रहने वाली है।","en":"God's Kingdom is steady, stable and eternal."},{"g":"ਦੋਮ ਨ ਸੇਮ ਏਕ ਸੋ ਆਹੀ ॥","t":"dhom na sem ek so aahee ||","pa":"ਉਥੇ ਕਿਸੇ ਦਾ ਦੂਜਾ ਤੀਜਾ ਦਰਜਾ ਨਹੀਂ, ਸਭ ਇਕੋ ਜਿਹੇ ਹਨ;","hi":"वहाँ किसी का दूसरा-तीसरा दर्जा नहीं। सब एक जैसे ही हैं।","en":"There is no second or third status; all are equal there."},{"g":"ਆਬਾਦਾਨੁ ਸਦਾ ਮਸਹੂਰ ॥","t":"aabaadhaan sadhaa masahoor ||","pa":"ਉਹ ਸ਼ਹਿਰ ਸਦਾ ਉੱਘਾ ਹੈ ਤੇ ਵੱਸਦਾ ਹੈ,","hi":"वह शहर सदा सघन है और आबाद है।","en":"That city is populous and eternally famous."},{"g":"ਊਹਾਂ ਗਨੀ ਬਸਹਿ ਮਾਮੂਰ ॥੨॥","t":"uoohaa(n) ganee baseh maamoor ||2||","pa":"ਉਥੇ ਧਨੀ ਤੇ ਰੱਜੇ ਹੋਏ ਬੰਦੇ ਵੱਸਦੇ ਹਨ (ਭਾਵ, ਉਸ ਆਤਮਕ ਦਰਜੇ ਤੇ ਜੋ ਜੋ ਅੱਪੜਦੇ ਹਨ ਉਹਨਾਂ ਦੇ ਅੰਦਰ ਕੋਈ ਵਿਤਕਰਾ ਨਹੀਂ ਰਹਿੰਦਾ ਤੇ ਉਹਨਾਂ ਨੂੰ ਦੁਨੀਆ ਦੀ ਭੁੱਖ ਨਹੀਂ ਰਹਿੰਦੀ) ।੨।","hi":"वहाँ धनी और तृप्त लोग ही बसते हैं (भाव। उस आत्मिक दर्जे पे जो जो पहुँचते हैं उनके अंदर कोई भेदभाव नहीं रहता ओर उन्हें दुनिया की भूख नहीं रहती)। 2।","en":"Those who live there are wealthy and contented. ||2||"},{"g":"ਤਿਉ ਤਿਉ ਸੈਲ ਕਰਹਿ ਜਿਉ ਭਾਵੈ ॥","t":"tiau tiau sail kareh jiau bhaavai ||","pa":"(ਉਸ ਆਤਮਕ ਸ਼ਹਿਰ ਵਿਚ ਅੱਪੜੇ ਹੋਏ ਬੰਦੇ ਉਸ ਅਵਸਥਾ ਵਿਚ) ਅਨੰਦ ਨਾਲ ਵਿਚਰਦੇ ਹਨ;","hi":"(उस आत्मिक शहर में पहुँचे हुए बंदे उस अवस्था में) आनंद से विचरते हैं;","en":"They stroll about freely, just as they please."},{"g":"ਮਹਰਮ ਮਹਲ ਨ ਕੋ ਅਟਕਾਵੈ ॥","t":"maharam mahal na ko aTakaavai ||","pa":"ਉਹ ਉਸ (ਰੱਬੀ) ਮਹਲ ਦੇ ਭੇਤੀ ਹੁੰਦੇ ਹਨ; (ਇਸ ਵਾਸਤੇ) ਕੋਈ (ਉਹਨਾਂ ਦੇ ਰਾਹ ਵਿਚ) ਰੋਕ ਨਹੀਂ ਪਾ ਸਕਦਾ ।","hi":"वह उस (ईश्वरीय) महल का भेद जानने वाले होते हैं; (इस वास्ते) कोई (उनके राह में) रोक नहीं डाल सकता।","en":"They know the Mansion of the Lord's Presence, and no one blocks their way."},{"g":"ਕਹਿ ਰਵਿਦਾਸ ਖਲਾਸ ਚਮਾਰਾ ॥","t":"keh ravidhaas khalaas chamaaraa ||","pa":"ਚਮਿਆਰ ਰਵਿਦਾਸ ਜਿਸ ਨੇ (ਦੁਖ-ਅੰਦੋਹ ਤਸ਼ਵੀਸ਼ ਆਦਿਕ ਤੋਂ) ਖ਼ਲਾਸੀ ਪਾ ਲਈ ਹੈ ਆਖਦਾ ਹੈ—","hi":"चमार रविदास जिसने (दुख-अंदोह-तशवीश आदि से) छुटकारा पा लिया है कहता है–","en":"Says Ravi Daas, the emancipated shoe-maker:"},{"g":"ਜੋ ਹਮ ਸਹਰੀ ਸੁ ਮੀਤੁ ਹਮਾਰਾ ॥੩॥੨॥","t":"jo ham saharee su meet hamaaraa ||3||2||","pa":"ਅਸਾਡਾ ਮਿੱਤਰ ਉਹ ਹੈ ਜੋ ਅਸਾਡਾ ਸਤਸੰਗੀ ਹੈ ।੩।੨।","hi":"हमारा मित्र वह है जो हमारा सत्संगी है। 3। 2।","en":"whoever is a citizen there, is a friend of mine. ||3||2||"}],"audioUrl":null,"youtube":{"id":"QN0LMzsSlOU","artist":"Singh Bandhu"}},{"id":"shabad-2567","type":"Shabad","title":"Tumaree saran tumaaree aasaa tum hee sajan suhele ","gurmukhiTitle":"ਤੁਮਰੀ ਸਰਣਿ ਤੁਮਾਰੀ ਆਸਾ ਤੁਮ ਹੀ ਸਜਨ ਸੁਹੇਲੇ","author":"Guru Arjan Dev Ji","raag":"Raag Dhanaasree","ang":673,"source":"Sri Guru Granth Sahib Ji","nitnem":false,"lines":[{"g":"ਧਨਾਸਰੀ ਮਹਲਾ ੫ ॥","t":"dhanaasaree mahalaa panjavaa ||","pa":"","hi":"","en":"Dhanaasaree, Fifth Mehla:"},{"g":"ਤੁਮ ਦਾਤੇ ਠਾਕੁਰ ਪ੍ਰਤਿਪਾਲਕ ਨਾਇਕ ਖਸਮ ਹਮਾਰੇ ॥","t":"tum dhaate Thaakur pratipaalak naik khasam hamaare ||","pa":"ਹੇ ਪ੍ਰਭੂ! ਤੂੰ ਸਭ ਦਾਤਾਂ ਦੇਣ ਵਾਲਾ ਹੈਂ, ਤੂੰ ਮਾਲਕ ਹੈਂ, ਤੂੰ ਸਭਨਾਂ ਨੂੰ ਪਾਲਣ ਵਾਲਾ ਹੈਂ, ਤੂੰ ਸਾਡਾ ਆਗੂ ਹੈਂ (ਜੀਵਨ-ਅਗਵਾਈ ਦੇਣ ਵਾਲਾ ਹੈਂ), ਤੂੰ ਸਾਡਾ ਖਸਮ ਹੈਂ ।","hi":"हे प्रभू ! तू सबको दातें देने वाला है।तू मालिक है।तू सबको पालने वाला है।तू हमारा नायक है (जीवन की अगुवाई देने वाला है)।तू हमारा पति है।","en":"You are the Giver, Master and Nurturer of all, my Husband Lord."},{"g":"ਨਿਮਖ ਨਿਮਖ ਤੁਮ ਹੀ ਪ੍ਰਤਿਪਾਲਹੁ ਹਮ ਬਾਰਿਕ ਤੁਮਰੇ ਧਾਰੇ ॥੧॥","t":"nimakh nimakh tum hee pratipaalahu ham baarik tumare dhaare ||1||","pa":"ਹੇ ਪ੍ਰਭੂ! ਤੂੰ ਹੀ ਇਕ ਇਕ ਛਿਨ ਸਾਡੀ ਪਾਲਣਾ ਕਰਦਾ ਹੈਂ, ਅਸੀ (ਤੇਰੇ) ਬੱਚੇ ਤੇਰੇ ਆਸਰੇ (ਜੀਊਂਦੇ) ਹਾਂ ।","hi":"हे प्रभू ! तू ही एक-एक छिन हमारी पालना करता है।हम (तेरे) बच्चे तेरे आसरे (जीते) हैं। 1।","en":"Each and every moment, You cherish and nurture me; I am Your child, and I rely upon You alone. ||1||"},{"g":"ਜਿਹਵਾ ਏਕ ਕਵਨ ਗੁਨ ਕਹੀਐ ॥","t":"jihavaa ek kavan gun kaheeaai ||","pa":"। (ਮਨੁੱਖ ਦੀ) ਇਕ ਜੀਭ ਨਾਲ ਤੇਰਾ ਕੇਹੜਾ ਕੇਹੜਾ ਗੁਣ ਦੱਸਿਆ ਜਾਏ? ।੧।ਰਹਾਉ।","hi":"(मनुष्य की) एक जीभ से तेरा कौन-कौन सा गुण बताया जाए।","en":"I have only one tongue - which of Your Glorious Virtues can I describe?"},{"g":"ਬੇਸੁਮਾਰ ਬੇਅੰਤ ਸੁਆਮੀ ਤੇਰੋ ਅੰਤੁ ਨ ਕਿਨ ਹੀ ਲਹੀਐ ॥੧॥ ਰਹਾਉ ॥","t":"besumaar bea(n)t suaamee tero a(n)t na kin hee laheeaai ||1|| rahaau ||","pa":"ਹੇ ਅਣਗਿਣਤ ਗੁਣਾਂ ਦੇ ਮਾਲਕ! ਹੇ ਬੇਅੰਤ ਮਾਲਕ-ਪ੍ਰਭੂ! ਕਿਸੇ ਭੀ ਪਾਸੋਂ ਤੇਰੇ ਗੁਣਾਂ ਦਾ ਅੰਤ ਨਹੀਂ ਲੱਭਿਆ ਜਾ ਸਕਿਆ","hi":"हे अनगिनत गुणों के मालिक ! हे बेअंत मालिक प्रभू ! किसी भी पक्ष से तेरे गुणों का अंत नहीं पाया जा सकता। 1।रहाउ।","en":"Unlimited, infinite Lord and Master - no one knows Your limits. ||1||Pause||"},{"g":"ਕੋਟਿ ਪਰਾਧ ਹਮਾਰੇ ਖੰਡਹੁ ਅਨਿਕ ਬਿਧੀ ਸਮਝਾਵਹੁ ॥","t":"koT paraadh hamaare kha(n)ddahu anik bidhee samajhaavahu ||","pa":"ਹੇ ਪ੍ਰਭੂ! ਤੂੰ ਸਾਡੇ ਕੋ੍ਰੜਾਂ ਅਪਰਾਧ ਨਾਸ ਕਰਦਾ ਹੈਂ, ਤੂੰ ਸਾਨੂੰ ਅਨੇਕਾਂ ਤਰੀਕਿਆਂ ਨਾਲ (ਜੀਵਨ-ਜੁਗਤਿ) ਸਮਝਾਂਦਾ ਹੈਂ","hi":"हे प्रभू ! तू हमारे करोड़ों अपराध नाश करता है।तू हमें अनेकों तरीकों से (जीवन जुगति) समझाता है।","en":"You destroy millions of my sins, and teach me in so many ways."},{"g":"ਹਮ ਅਗਿਆਨ ਅਲਪ ਮਤਿ ਥੋਰੀ ਤੁਮ ਆਪਨ ਬਿਰਦੁ ਰਖਾਵਹੁ ॥੨॥","t":"ham agiaan alap mat thoree tum aapan biradh rakhaavahu ||2||","pa":"ਅਸੀ ਜੀਵ ਆਤਮਕ ਜੀਵਨ ਦੀ ਸੂਝ ਤੋਂ ਸੱਖਣੇ ਹਾਂ, ਸਾਡੀ ਅਕਲ ਥੋੜੀ ਹੈ ਹੋਛੀ ਹੈ । (ਫਿਰ ਭੀ) ਤੂੰ ਆਪਣਾ ਮੁੱਢ-ਕਦੀਮਾਂ ਦਾ ਪਿਆਰ ਵਾਲਾ ਸੁਭਾਉ ਕਾਇਮ ਰੱਖਦਾ ਹੈਂ ।੨","hi":"हम जीव आत्मिक जीवन की सूझ से वंचित हैं।हमारी अक्ल थोड़ी है होछी है।(फिर भी) तू अपना बिरद भरा प्यार वाला स्वभाव सदा कायम रखता है। 2।","en":"I am so ignorant - I understand nothing at all. Please honor Your innate nature, and save me! ||2||"},{"g":"ਤੁਮਰੀ ਸਰਣਿ ਤੁਮਾਰੀ ਆਸਾ ਤੁਮ ਹੀ ਸਜਨ ਸੁਹੇਲੇ ॥","t":"tumaree saran tumaaree aasaa tum hee sajan suhele ||","pa":"ਨਾਨਕ! (ਆਖ—) ਹੇ ਪ੍ਰਭੂ! ਅਸੀ ਤੇਰੇ ਹੀ ਆਸਰੇ-ਪਰਨੇ ਹਾਂ, ਸਾ­ਨੂੰ ਤੇਰੀ ਹੀ (ਸਹਾਇਤਾ ਦੀ) ਆਸ ਹੈ, ਤੂੰ ਹੀ ਸਾਡਾ ਸੱਜਣ ਹੈਂ,","hi":"हे नानक ! (कह–) हे प्रभू ! हम तेरे ही आसरे-सहारे से हैं।हमें तेरी ही (सहायता की) आस है।तू ही हमारा सज्जन है।तू ही हमें सुख देने वाला है।","en":"I seek Your Sanctuary - You are my only hope. You are my companion, and my best friend."},{"g":"ਰਾਖਹੁ ਰਾਖਨਹਾਰ ਦਇਆਲਾ ਨਾਨਕ ਘਰ ਕੇ ਗੋਲੇ ॥੩॥੧੨॥","t":"raakhahu raakhanahaar dhiaalaa naanak ghar ke gole ||3||12||","pa":"ਤੂੰ ਹੀ ਸਾਨੂੰ ਸੁਖ ਦੇਣ ਵਾਲਾ ਹੈਂ । ਹੇ ਦਇਆਵਾਨ! ਹੇ ਸਭ ਦੀ ਰੱਖਿਆ ਕਰਨ-ਜੋਗੇ! ਸਾਡੀ ਰੱਖਿਆ ਕਰ, ਅਸੀ ਤੇਰੇ ਘਰ ਦੇ ਗ਼ੁਲਾਮ ਹਾਂ ।੩।੧੨।","hi":"हे दयावान ! हे सबकी रक्षा करने के समर्थ ! हमारी रक्षा कर।हम तेरे घर के गुलाम हैं। 3। 12।","en":"Save me, O Merciful Saviour Lord; Nanak is the slave of Your home. ||3||12||"}],"audioUrl":null,"youtube":{"id":"7wAMROkV17k","artist":"Bhai Mehtab Singh"}},{"id":"shabad-299","type":"Shabad","title":"A(n)mirat baanee har har teree ","gurmukhiTitle":"ਅੰਮ੍ਰਿਤ ਬਾਣੀ ਹਰਿ ਹਰਿ ਤੇਰੀ","author":"Guru Arjan Dev Ji","raag":"Raag Maajh","ang":103,"source":"Sri Guru Granth Sahib Ji","nitnem":false,"lines":[{"g":"ਮਾਝ ਮਹਲਾ ੫ ॥","t":"maajh mahalaa panjavaa ||","pa":"","hi":"","en":"Maajh, Fifth Mehla:"},{"g":"ਅੰਮ੍ਰਿਤ ਬਾਣੀ ਹਰਿ ਹਰਿ ਤੇਰੀ ॥","t":"a(n)mirat baanee har har teree ||","pa":"ਹੇ ਹਰੀ । ਤੇਰੀ ਸਿਫ਼ਤਿ-ਸਾਲਾਹ ਦੀ ਬਾਣੀ ਆਤਮਕ ਜੀਵਨ ਦੇਣ ਵਾਲੀ ਹੈ (ਆਤਮਕ ਮੌਤ ਤੋਂ ਬਚਾਣ ਵਾਲੀ ਹੈ),","hi":"हे हरी !तेरी सिफत सलाह की बाणी आत्मिक जीवन देने वाली है (आत्मिक मौत से बचाने वाली है)~","en":"The Word of Your Bani, Lord, is Ambrosial Nectar."},{"g":"ਸੁਣਿ ਸੁਣਿ ਹੋਵੈ ਪਰਮ ਗਤਿ ਮੇਰੀ ॥","t":"sun sun hovai param gat meree ||","pa":"(ਗੁਰੂ ਦੀ ਉਚਾਰੀ ਹੋਈ ਇਹ ਬਾਣੀ) ਮੁੜ ਮੁੜ ਸੁਣ ਕੇ ਮੇਰੀ ਉੱਚੀ ਆਤਮਕ ਅਵਸਥਾ ਬਣਦੀ ਜਾ ਰਹੀ ਹੈ ।","hi":"(गुरू की उचारी हुई ये बाणी) बार बार सुन के मेरी ऊँची आत्मिक अवस्था बनती जा रही है।","en":"Hearing it again and again, I am elevated to the supreme heights."},{"g":"ਜਲਨਿ ਬੁਝੀ ਸੀਤਲੁ ਹੋਇ ਮਨੂਆ ਸਤਿਗੁਰ ਕਾ ਦਰਸਨੁ ਪਾਏ ਜੀਉ ॥੧॥","t":"jalan bujhee seetal hoi manooaa satigur kaa dharasan paae jeeau ||1||","pa":"ਗੁਰੂ ਦਾ ਦਰਸਨ ਕਰ ਕੇ (ਤ੍ਰਿਸ਼ਨਾ ਈਰਖਾ ਆਦਿਕ ਦੀ) ਸੜਨ ਬੁੱਝ ਜਾਂਦੀ ਹੈ ਤੇ ਮਨ ਠੰਢਾ-ਠਾਰ ਹੋ ਜਾਂਦਾ ਹੈ ।੧।","hi":"गुरू का दर्शन करके (तृष्णा~ ईश्या आदि की) जलन बुझ जाती है और मन ठंडा ठार हो जाता है।1।","en":"The burning within me has been extinguished, and my mind has been cooled and soothed, by the Blessed Vision of the True Guru. ||1||"},{"g":"ਸੂਖੁ ਭਇਆ ਦੁਖੁ ਦੂਰਿ ਪਰਾਨਾ ॥","t":"sookh bhiaa dhukh dhoor paraanaa ||","pa":"ਜਿਸ ਨੇ ਪਰਮਾਤਮਾ ਦਾ ਨਾਮ ਨੂੰ ਸੁਣਿਆ ਉਸ ਦੇ ਅੰਦਰ ਆਤਮਕ ਆਨੰਦ ਪੈਦਾ ਹੋ ਗਿਆ (ਉਸ ਦਾ) ਦੁੱਖ ਦੂਰ ਭੱਜ ਗਿਆ ।","hi":"आत्मिक आनंद पैदा हो गया (उस का) दुख दूर भाग गया।","en":"Happiness is obtained, and sorrow runs far away,"},{"g":"ਸੰਤ ਰਸਨ ਹਰਿ ਨਾਮੁ ਵਖਾਨਾ ॥","t":"sa(n)t rasan har naam vakhaanaa ||","pa":"ਗੁਰੂ ਦੀ ਜੀਭ ਨੇ (ਜਦੋਂ) ਪਰਮਾਤਮਾ ਦਾ ਨਾਮ ਉਚਾਰਿਆ (ਆਤਮਕ ਆਨੰਦ ਪੈਦਾ ਹੋ ਗਿਆ)","hi":"गुरू की जीभ ने (जब) परमात्मा का नाम उचारा","en":"when the Saints chant the Lord's Name."},{"g":"ਜਲ ਥਲ ਨੀਰਿ ਭਰੇ ਸਰ ਸੁਭਰ ਬਿਰਥਾ ਕੋਇ ਨ ਜਾਏ ਜੀਉ ॥੨॥","t":"jal thal neer bhare sar subhar birathaa koi na jaae jeeau ||2||","pa":"(ਜਿਵੇਂ ਵਰਖਾ ਹੋਣ ਨਾਲ) ਟੋਏ ਟਿੱਬੇ ਤਾਲਾਬ (ਸਭ) ਪਾਣੀ ਨਾਲ ਨਕਾ-ਨਕ ਭਰ ਜਾਂਦੇ ਹਨ (ਤਿਵੇਂ ਗੁਰੂ ਦੇ ਦਰ ਤੇ ਪ੍ਰਭੂ-ਨਾਮ ਦੀ ਵਰਖਾ ਹੁੰਦੀ ਹੈ ਤੇ ਜੇਹੜੇ ਵਡਭਾਗੀ ਮਨੁੱਖ ਗੁਰੂ ਦੀ ਸਰਨ ਆਉਂਦੇ ਹਨ ਉਹਨਾਂ ਦਾ ਮਨ ਉਹਨਾਂ ਦੇ ਗਿਆਨ-ਇੰਦੇ੍ਰ ਸਭ ਨਾਮ-ਜਲ ਨਾਲ ਨਕਾ-ਨਕ ਭਰ ਜਾਂਦੇ ਹਨ । ਗੁਰੂ ਦੇ ਦਰ ਤੇ ਆਇਆਂ ਕੋਈ ਮਨੁੱਖ (ਨਾਮ-ਅੰਮ੍ਰਿਤ ਤੋਂ) ਸੱਖਣਾ ਨਹੀਂ ਜਾਂਦਾ ।੨।","hi":"(जैसे बरखा होने से) गड्ढे (टोए टिब्बे) तालाब सब पानी से नाको नाक भर जाते हैं (वैसे ही गुरू के दर पे प्रभू नाम की बरखा होती है तब जो भाग्यशाली मनुष्य गुरू की शरण में आते हैं उनका मन~ उनकी ज्ञानेंद्रियां सब नाम जल से नाको नाक भर जाती है। गुरू के दर पे आया कोई मनुष्य (नाम अमृत) से वंचित नहीं रह जाता।2।","en":"The sea, the dry land, and the lakes are filled with the Water of the Lord's Name; no place is left empty. ||2||"},{"g":"ਦਇਆ ਧਾਰੀ ਤਿਨਿ ਸਿਰਜਨਹਾਰੇ ॥","t":"dhiaa dhaaree tin sirajanahaare ||","pa":"ਉਸ ਸਿਰਜਨਹਾਰ ਪ੍ਰਭੂ ਨੇ (ਮਿਹਰ ਕੀਤੀ) ਤੇ ਗੁਰੂ ਘੱਲਿਆ,","hi":"उस सृजनहार प्रभू ने मेहर की (और गुरू को भेजा इस तरह उसने सृष्टि के)","en":"The Creator has showered His Kindness;"},{"g":"ਜੀਅ ਜੰਤ ਸਗਲੇ ਪ੍ਰਤਿਪਾਰੇ ॥","t":"jeea ja(n)t sagale pratipaare ||","pa":"ਇਸ ਤਰ੍ਹਾਂ ਉਸ ਨੇ ਸ੍ਰਿਸ਼ਟੀ ਦੇ) ਸਾਰੇ ਜੀਵਾਂ ਦੀ (ਵਿਕਾਰਾਂ ਤੋਂ) ਰਾਖੀ (ਦੀ ਵਿਓਂਤ) ਕੀਤੀ ।","hi":"सारे जीवों की (विकारों से) रक्षा (की तरकीब) की।","en":"He cherishes and nurtures all beings and creatures."},{"g":"ਮਿਹਰਵਾਨ ਕਿਰਪਾਲ ਦਇਆਲਾ ਸਗਲੇ ਤ੍ਰਿਪਤਿ ਅਘਾਏ ਜੀਉ ॥੩॥","t":"miharavaan kirapaal dhiaalaa sagale tirapat aghaae jeeau ||3||","pa":"ਮਿਹਰਵਾਨ ਕਿਰਪਾਲ ਦਇਆਵਾਨ (ਪਰਮਾਤਮਾ ਦੀ ਮਿਹਰ ਨਾਲ ਗੁਰੂ ਦੀ ਸਰਨ ਆਏ) ਸਾਰੇ ਜੀਵ (ਮਾਇਆ ਦੀ ਤੇ੍ਰਹ ਭੁੱਖ ਵਲੋਂ) ਪੂਰਨ ਤੌਰ ਤੇ ਰੱਜ ਗਏ ।੩।","hi":"मेहरवान~ कृपाल~ दयावान (परमात्मा की मेहर से गुरू की शरण आए) सारे जीव (माया की प्यास भूख की ओर से) पूर्ण तौर पे तृप्त हो गए।3।","en":"He is Merciful, Kind and Compassionate. All are satisfied and fulfilled through Him. ||3||"},{"g":"ਵਣੁ ਤ੍ਰਿਣੁ ਤ੍ਰਿਭਵਣੁ ਕੀਤੋਨੁ ਹਰਿਆ ॥","t":"van tiran tirabhavan keeton hariaa ||","pa":"(ਜਿਵੇਂ ਜਦੋਂ) ਜਗਤ ਦੇ ਪੈਦਾ ਕਰਨ ਵਾਲੇ ਪ੍ਰਭੂ ਨੇ (ਵਰਖਾ ਕੀਤੀ ਤਾਂ) ਇਕ ਪਲ ਵਿਚ ਹੀ ਜੰਗਲ ਘਾਹ ਤੇ ਸਾਰਾ ਤ੍ਰਿਵਨੀ ਜਗਤ ਹਰਾ ਕਰ ਦਿੱਤਾ","hi":"जंगल~ घास और सारा त्रिवनी जगत हरा कर दिया ~","en":"The woods, the meadows and the three worlds are rendered green."},{"g":"ਕਰਣਹਾਰਿ ਖਿਨ ਭੀਤਰਿ ਕਰਿਆ ॥","t":"karanahaar khin bheetar kariaa ||","pa":"ਉਸ ਦਾ ਭੇਜਿਆ ਗੁਰੂ ਨਾਮ ਦੀ ਵਰਖਾ ਕਰਦਾ ਹੈ, (ਇਕ ਪਲ ਵਿਚ ਹੀ )ਗੁਰੂ-ਦਰ ਤੇ ਆਏ ਬੰਦਿਆਂ ਦੇ ਹਿਰਦੇ ਨਾਮ-ਜਲ ਨਾਲ ਆਤਮਕ ਜੀਵਨ ਵਾਲੇ ਬਣ ਜਾਂਦੇ ਹਨ) ।","hi":"जगत के पैदा करने वाले प्रभू ने (बरखा की तो) एक पल में ही हरा कर दिया (उसी तरह उसका भेजा हुआ गुरू~ नाम की बरखा करता है~ गुरू दर पे आए लोगों के हृदय नाम जल से आत्मिक जीवन वाले बन जाते हैं)।","en":"The Doer of all did this in an instant."},{"g":"ਗੁਰਮੁਖਿ ਨਾਨਕ ਤਿਸੈ ਅਰਾਧੇ ਮਨ ਕੀ ਆਸ ਪੁਜਾਏ ਜੀਉ ॥੪॥੨੩॥੩੦॥","t":"gurmukh naanak tisai araadhe man kee aas pujaae jeeau ||4||23||30||","pa":"ਹੇ ਨਾਨਕ ! ਗੁਰੂ ਦੀ ਸਰਨ ਪੈ ਕੇ ਜੇਹੜਾ ਮਨੁੱਖ ਉਸ ਪਰਮਾਤਮਾ ਨੂੰ ਸਿਮਰਦਾ ਹੈ, ਪਰਮਾਤਮਾ ਉਸ ਦੇ ਮਨ ਦੀ ਆਸ ਪੂਰੀ ਕਰ ਦੇਂਦਾ ਹੈ (ਦੁਨੀਆ ਦੀਆਂ ਆਸਾ-ਤ੍ਰਿਸ਼ਨਾ ਵਿਚ ਭਟਕਣੋਂ ਉਸ ਨੂੰ ਬਚਾ ਲੈਂਦਾ ਹੈ) ।੪।੨੩।੩੦।","hi":"हे नानक ! गुरू की शरण पड़ कर जो मनुष्य उस परमात्मा को सिमरता है~ परमात्मा उसके मन की आस पूरी कर देता है (दुनिया की आसा तृष्णा में भटकने से उसको बचा लेता है)।4।23।30।","en":"As Gurmukh, Nanak meditates on the One who fulfills the desires of the mind. ||4||23||30||"}],"audioUrl":null,"youtube":{"id":"NB7q2LImC1E","artist":"Bhai Joginder Singh Riar"}},{"id":"shabad-4683","type":"Shabad","title":"Ghar meh ghar dhekhai dhei so satigur purakh sujaan ","gurmukhiTitle":"ਘਰ ਮਹਿ ਘਰੁ ਦੇਖਾਇ ਦੇਇ ਸੋ ਸਤਿਗੁਰੁ ਪੁਰਖੁ ਸੁਜਾਣੁ","author":"Guru Nanak Dev Ji","raag":"Raag Malaar","ang":1291,"source":"Sri Guru Granth Sahib Ji","nitnem":false,"lines":[{"g":"ਸਲੋਕ ਮਃ ੧ ॥","t":"salok mahalaa pehilaa ||","pa":"","hi":"","en":"Shalok, First Mehla:"},{"g":"ਘਰ ਮਹਿ ਘਰੁ ਦੇਖਾਇ ਦੇਇ ਸੋ ਸਤਿਗੁਰੁ ਪੁਰਖੁ ਸੁਜਾਣੁ ॥","t":"ghar meh ghar dhekhai dhei so satigur purakh sujaan ||","pa":"ਉਹ ਹੈ ਸਿਆਣਾ ਸਤਿਗੁਰੂ ਪੁਰਖ ਜੋ ਹਿਰਦੇ-ਘਰ ਵਿਚ ਪਰਮਾਤਮਾ ਦੇ ਰਹਿਣ ਦਾ ਥਾਂ ਵਿਖਾ ਦੇਂਦਾ ਹੈ","hi":"वह है समझदार सतिगुरू पुरख जो हृदय-घर में परमात्मा के रहने की जगह दिखा देता है;","en":"The True Guru is the All-knowing Primal Being; He shows us our true home within the home of the self."},{"g":"ਪੰਚ ਸਬਦ ਧੁਨਿਕਾਰ ਧੁਨਿ ਤਹ ਬਾਜੈ ਸਬਦੁ ਨੀਸਾਣੁ ॥","t":"pa(n)ch sabadh dhunikaar dhun teh baajai sabadh neesaan ||","pa":"ਜਦੋਂ ਮਨੁੱਖ) ਉਸ ਘਰ ਵਿਚ (ਅੱਪੜਦਾ ਹੈ) ਤਦੋਂ ਗੁਰੂ ਦਾ ਸ਼ਬਦ-ਰੂਪ ਨਗਾਰਾ ਵੱਜਦਾ ਹੈ (ਭਾਵ, ਗੁਰ-ਸ਼ਬਦ ਦਾ ਪ੍ਰਭਾਵ ਇਤਨਾ ਪ੍ਰਬਲ ਹੁੰਦਾ ਹੈ ਕਿ ਕੋਈ ਹੋਰ ਖਿੱਚ ਪੋਹ ਨਹੀਂ ਸਕਦੀ, ਤਦੋਂ ਮਾਨੋ) ਪੰਜ ਕਿਸਮ ਦੇ ਸਾਜ਼ਾਂ ਦੀ ਇਕ-ਰਸ ਸੰਗੀਤਕ ਆਵਾਜ਼ ਉੱਠਦੀ ਹੈ (","hi":"(जब मनुष्य) उस घर में (पहुँचता है) तब गुरू का शबद-रूप नगारा बजता है (भाव। गुरू-शबद का प्रभाव इतना प्रबल होता है कि कोई और आकर्षण उस पर असर नहीं डाल सकता। तब मानो। ) पाँच किस्म के साजों की एक-रस संगीतक आवाज़ उठती है (जो मस्ती पैदा करती है)","en":"The Panch Shabad, the Five Primal Sounds, resonate and resound within; the insignia of the Shabad is revealed there, vibrating gloriously."},{"g":"ਦੀਪ ਲੋਅ ਪਾਤਾਲ ਤਹ ਖੰਡ ਮੰਡਲ ਹੈਰਾਨੁ ॥","t":"dheep loa paataal teh kha(n)dd ma(n)ddal hairaan ||","pa":"ਜੋ ਮਸਤੀ ਪੈਦਾ ਕਰਦੀ ਹੈ) ਇਸ ਅਵਸਥਾ ਵਿਚ (ਅੱਪੜ ਕੇ) ਮਨੁੱਖ (ਬੇਅੰਤ ਕੁਦਰਤਿ ਦੇ ਕੌਤਕ) ਦੀਪਾਂ, ਲੋਕਾਂ, ਪਾਤਾਲਾਂ, ਖੰਡਾਂ ਤੇ ਮੰਡਲਾਂ ਨੂੰ ਵੇਖ ਕੇ ਹੈਰਾਨ ਹੁੰਦਾ ਹੈ;","hi":"इस अवस्था में (पहुँच के) मनुष्य (बेअंत कुदरति के करिश्मे) द्वीपों। लोकों। पातालों। खण्डों और मण्डलों को देख के हैरान होता है;","en":"Worlds and realms, nether regions, solar systems and galaxies are wondrously revealed."},{"g":"ਤਾਰ ਘੋਰ ਬਾਜਿੰਤ੍ਰ ਤਹ ਸਾਚਿ ਤਖਤਿ ਸੁਲਤਾਨੁ ॥","t":"taar ghor baaji(n)tr teh saach takhat sulataan ||","pa":"(ਇਸ ਸਾਰੀ ਕੁਦਰਤਿ ਦਾ) ਪਾਤਸ਼ਾਹ ਸੱਚੇ ਤਖ਼ਤ ਉਤੇ ਬੈਠਾ ਦਿੱਸਦਾ ਹੈ, ਉਸ ਹਾਲਤ ਵਿਚ ਅੱਪੜਿਆਂ; ਮਾਨੋ, ਵਾਜਿਆਂ ਦੀ ਉੱਚੀ ਸੁਰ ਦੀ ਘਨਘੋਰ ਲੱਗੀ ਪਈ ਹੁੰਦੀ ਹੈ","hi":"(इस सारी कुदरति का) पातशाह सच्चे तख़्त पर बैठा दिखता है। उस हालत में पहुँचने से। मानो। साज़ों की ऊँची सुर की घनघोर झड़ी लगी हुई रहती है।","en":"The strings and the harps vibrate and resound; the true throne of the Lord is there."},{"g":"ਸੁਖਮਨ ਕੈ ਘਰਿ ਰਾਗੁ ਸੁਨਿ ਸੁੰਨਿ ਮੰਡਲਿ ਲਿਵ ਲਾਇ ॥","t":"sukhaman kai ghar raag sun su(n)n ma(n)ddal liv lai ||","pa":"ਇਸ ਰੱਬੀ ਮਿਲਾਪ ਵਿਚ ਬੈਠਾ ਮਨੁੱਖ (ਮਾਨੋ) ਰਾਗ ਸੁਣ ਸੁਣ ਕੇ ਅਫੁਰ ਅਵਸਥਾ ਵਿਚ ਸੁਰਤਿ ਜੋੜੀ ਰੱਖਦਾ ਹੈ (ਭਾਵ, ਰੱਬੀ ਮਿਲਾਪ ਦੀ ਮੌਜ ਵਿਚ ਇਤਨਾ ਮਸਤ ਹੁੰਦਾ ਹੈ ਕਿ ਜਗਤ ਵਾਲਾ ਕੋਈ ਫੁਰਨਾ ਉਸ ਦੇ ਮਨ ਵਿਚ ਨਹੀਂ ਉੱਠਦਾ) ।","hi":"इस ईश्वरीय मिलाप में बैठा मनुष्य (मानो) राग सुन-सुन के अफुर अवस्था में सुरति जोड़े रखता है (भाव। ईश्वरीय मिलाप की मौज में इतना मस्त होता है कि जगत का कोई फुरना उसके मन में नहीं उठता)।","en":"Listen to the music of the home of the heart - Sukhmani, peace of mind. Lovingly tune in to His state of celestial ecstasy."},{"g":"ਅਕਥ ਕਥਾ ਬੀਚਾਰੀਐ ਮਨਸਾ ਮਨਹਿ ਸਮਾਇ ॥","t":"akath kathaa beechaareeaai manasaa maneh samai ||","pa":"ੲਥੇ ਬੇਅੰਤ ਪ੍ਰਭੂ ਦੇ ਗੁਣ ਜਿਉਂ ਜਿਉਂ ਵੀਚਾਰੀਦੇ ਹਨ ਤਿਉਂ ਤਿਉਂ ਮਨ ਦਾ ਫੁਰਨਾ ਮਨ ਵਿਚ ਹੀ ਗ਼ਰਕ ਹੁੰਦਾ ਜਾਂਦਾ ਹੈ; ਇਹ ਮਨ ਕਿਸੇ ਹੋਰ ਪਾਸੇ ਨਹੀਂ ਜਾਂਦਾ ਕਿਉਂਕਿ ਹਿਰਦਾ-ਰੂਪ ਕਉਲ ਫੁੱਲ (ਮਾਇਆ ਵਲੋਂ) ਪਰਤ ਕੇ ਨਾਮ-ਅੰਮ੍ਰਿਤ ਨਾਲ ਭਰ ਜਾਂਦਾ ਹੈ;","hi":"यहाँ पर (इस अवस्था में) बेअंत प्रभू के गुण ज्यों-ज्यों विचारे जाते हैं। त्यों-त्यों मन का फुरना मन में ग़रक होता जाता है;","en":"Contemplate the Unspoken Speech, and the desires of the mind are dissolved."},{"g":"ਉਲਟਿ ਕਮਲੁ ਅੰਮ੍ਰਿਤਿ ਭਰਿਆ ਇਹੁ ਮਨੁ ਕਤਹੁ ਨ ਜਾਇ ॥","t":"aulaT kamal a(n)mirat bhariaa ih man katahu na jai ||","pa":"ਉਸ ਪ੍ਰਭੂ ਵਿਚ, ਜੋ ਸਭ ਦਾ ਮੁੱਢ ਹੈ ਤੇ ਜੁਗਾਂ ਦੇ ਬਣਨ ਤੋਂ ਭੀ ਪਹਿਲਾਂ ਦਾ ਹੈ,","hi":"ये मन किसी और तरफ़ नहीं जाता क्योंकि हृदय-रूप कमल-फूल (माया से) पलट के नाम-अमृत से भर जाता है;","en":"The heart-lotus is turned upside-down, and is filled with Ambrosial Nectar. This mind does not go out; it does not get distracted."},{"g":"ਅਜਪਾ ਜਾਪੁ ਨ ਵੀਸਰੈ ਆਦਿ ਜੁਗਾਦਿ ਸਮਾਇ ॥","t":"ajapaa jaap na veesarai aadh jugaadh samai ||","pa":"ਮਨ ਇਉਂ ਲੀਨ ਹੁੰਦਾ ਹੈ ਕਿ ਪ੍ਰਭੂ ਦੀ ਯਾਦ (ਕਿਸੇ ਵੇਲੇ) ਨਹੀਂ ਭੁੱਲਦੀ, ਜੀਭ ਹਿਲਾਣ ਤੋਂ ਬਿਨਾ ਹੀ ਸਿਮਰਨ ਹੁੰਦਾ ਰਹਿੰਦਾ ਹੈ ।","hi":"उस प्रभू में। जो सबका आदि है और जुगों के बनने से भी पहले का है। मन इस तरह लीन होता है कि प्रभू की याद (किसी वक्त) नहीं भूलती। जीभ हिलाए बग़ैर ही सिमरन होता रहता है।","en":"It does not forget the Chant which is chanted without chanting; it is immersed in the Primal Lord God of the ages."},{"g":"ਸਭਿ ਸਖੀਆ ਪੰਚੇ ਮਿਲੇ ਗੁਰਮੁਖਿ ਨਿਜ ਘਰਿ ਵਾਸੁ ॥","t":"sabh sakheeaa pa(n)che mile gurmukh nij ghar vaas ||","pa":"ਇਸ ਤਰ੍ਹਾਂ) ਗੁਰੂ ਦੇ ਸਨਮੁਖ ਹੋਇਆਂ ਮਨੁੱਖ ਨਿਰੋਲ ਆਪਣੇ ਘਰ ਵਿਚ ਟਿਕ ਜਾਂਦਾ ਹੈ (ਜਿਵੇਂ ਕੋਈ ਇਸ ਨੂੰ ਬੇ-ਦਖ਼ਲ ਨਹੀਂ ਕਰ ਸਕਦਾ, ਇਸ ਦੇ) ਸਾਰੇ ਗਿਆਨ-ਇੰਦ੍ਰੇ ਤੇ ਪੰਜੇ (ਦੈਵੀ ਗੁਣ ਭਾਵ, ਸਤ ਸੰਤੋਖ ਦਇਆ ਧਰਮ ਧੀਰਜ) ਸੰਗੀ ਬਣ ਜਾਂਦੇ ਹਨ ।","hi":"(इस तरह) गुरू के सन्मुख होने पर मनुष्य पूरी तरह से अपने घर में टिक जाता है (जहाँ से इसको कोई बेदख़ल नहीं कर सकता। इसकी) सारी ज्ञानेन्द्रियां और पाँचों (दैवी गुण। भाव। सत-संतोख-दया-धर्म-धैर्य) संगी बन जाते हैं।","en":"All the sister-companions are blessed with the five virtues. The Gurmukhs dwell in the home of the self deep within."},{"g":"ਸਬਦੁ ਖੋਜਿ ਇਹੁ ਘਰੁ ਲਹੈ ਨਾਨਕੁ ਤਾ ਕਾ ਦਾਸੁ ॥੧॥","t":"sabadh khoj ih ghar lahai naanak taa kaa dhaas ||1||","pa":"ਸਤਿਗੁਰੂ ਦੇ ਸ਼ਬਦ ਨੂੰ ਸਮਝ ਕੇ ਜੋ ਮਨੁੱਖ ਇਸ (ਨਿਰੋਲ ਆਪਣੇ) ਘਰ ਨੂੰ ਲੱਭ ਲੈਂਦਾ ਹੈ, ਨਾਨਕ ਉਸ ਦਾ ਸੇਵਕ ਹੈ ।੧।","hi":"सतिगुरू के शबद को समझ के जो मनुष्य इस (सिर्फ अपने) घर को पा लेता है। नानक उसका सेवक है। 1।","en":"Nanak is the slave of that one who seeks the Shabad and finds this home within. ||1||"}],"audioUrl":null,"youtube":null},{"id":"shabad-1721","type":"Shabad","title":"Balihaaree kudharat vasiaa ","gurmukhiTitle":"ਬਲਿਹਾਰੀ ਕੁਦਰਤਿ ਵਸਿਆ","author":"Guru Nanak Dev Ji","raag":"Raag Aasaa","ang":469,"source":"Sri Guru Granth Sahib Ji","nitnem":false,"lines":[{"g":"ਸਲੋਕੁ ਮਃ ੧ ॥","t":"salok mahalaa pehilaa ||","pa":"","hi":"","en":"Shalok, First Mehla:"},{"g":"ਦੁਖੁ ਦਾਰੂ ਸੁਖੁ ਰੋਗੁ ਭਇਆ ਜਾ ਸੁਖੁ ਤਾਮਿ ਨ ਹੋਈ ॥","t":"dhukh dhaaroo sukh rog bhiaa jaa sukh taam na hoiee ||","pa":"(ਹੇ ਪ੍ਰਭੂ! ਤੇਰੀ ਅਜਬ ਕੁਦਰਤ ਹੈ ਕਿ) ਬਿਪਤਾ (ਜੀਵਾਂ ਦੇ ਰੋਗਾਂ ਦਾ) ਇਲਾਜ (ਬਣ ਜਾਂਦੀ) ਹੈ, ਅਤੇ ਸੁਖ (ਉਹਨਾਂ ਲਈ) ਦੁੱਖ ਦਾ (ਕਾਰਨ) ਹੋ ਜਾਂਦਾ ਹੈ । ਪਰ ਜੇ (ਅਸਲੀ ਆਤਮਕ) ਸੁਖ (ਜੀਵ ਨੂੰ) ਮਿਲ ਜਾਏ, ਤਾਂ (ਦੁੱਖ) ਨਹੀਂ ਰਹਿੰਦਾ ।","hi":"(हे प्रभू ! तेरी अजब कुदरति है कि) बिपता (जीवों के रोगों का) इलाज (बन जाती) है।और सुख (उनके लिए) दुख का (कारण) हो जाता है।पर अगर (असली आत्मिक) सुख (जीव को) मिल जाए।तो (दुख) नहीं रहता।","en":"Suffering is the medicine, and pleasure the disease, because where there is pleasure, there is no desire for God."},{"g":"ਤੂੰ ਕਰਤਾ ਕਰਣਾ ਮੈ ਨਾਹੀ ਜਾ ਹਉ ਕਰੀ ਨ ਹੋਈ ॥੧॥","t":"too(n) karataa karanaa mai naahee jaa hau karee na hoiee ||1||","pa":"ਹੇ ਪ੍ਰਭੂ! ਤੂੰ ਕਰਨਹਾਰ ਕਰਤਾਰ ਹੈਂ (ਤੂੰ ਆਪ ਹੀ ਇਹਨਾਂ ਭੇਤਾਂ ਨੂੰ ਸਮਝਦਾ ਹੈਂ), ਮੇਰੀ ਸਮਰਥਾ ਨਹੀਂ ਹੈ (ਕਿ ਮੈਂ ਸਮਝ ਸਕਾਂ) । ਜੇ ਮੈਂ ਆਪਣੇ ਆਪ ਨੂੰ ਕੁਝ ਸਮਝ ਲਵਾਂ (ਭਾਵ, ਜੇ ਮੈਂ ਇਹ ਖ਼ਿਆਲ ਕਰਨ ਲੱਗ ਪਵਾਂ ਕਿ ਮੈਂ ਤੇਰੇ ਭੇਤ ਨੂੰ ਸਮਝ ਸਕਦਾ ਹਾਂ) ਤਾਂ ਇਹ ਗੱਲ ਫਬਦੀ ਨਹੀਂ ।੧।","hi":"हे प्रभू ! तू करणहार करतार है (तू खुद ही इन भेदों को समझता है)।मेरी समर्थता नहीं है (कि मैं समझ सकूँ)।अगर मैं अपने आप को कुछ समझ लूँ (भाव।अगर मैं ये ख्याल करने लग जाऊँ कि मैं तेरे भेद को समझ सकता हूँ) तो ये बात फबती नहीं। 1।","en":"You are the Creator Lord; I can do nothing. Even if I try, nothing happens. ||1||"},{"g":"ਬਲਿਹਾਰੀ ਕੁਦਰਤਿ ਵਸਿਆ ॥","t":"balihaaree kudharat vasiaa ||","pa":"ਹੇ ਕੁਦਰਤ ਵਿਚ ਵੱਸ ਰਹੇ ਕਰਤਾਰ! ਮੈਂ ਤੈਥੋਂ ਸਦਕੇ ਹਾਂ,","hi":"हे कुदरति में बस रहे करतार ! मैं तुझसे सदके हूँ।","en":"I am a sacrifice to Your almighty creative power which is pervading everywhere."},{"g":"ਤੇਰਾ ਅੰਤੁ ਨ ਜਾਈ ਲਖਿਆ ॥੧॥ ਰਹਾਉ ॥","t":"teraa a(n)t na jaiee lakhiaa ||1|| rahaau ||","pa":"ਤੇਰਾ ਅੰਤ ਪਾਇਆ ਨਹੀਂ ਜਾ ਸਕਦਾ ।੧।ਰਹਾਉ।","hi":"तेरा अंत नहीं पाया जा सकता। 1।रहाउ।","en":"Your limits cannot be known. ||1||Pause||"},{"g":"ਜਾਤਿ ਮਹਿ ਜੋਤਿ ਜੋਤਿ ਮਹਿ ਜਾਤਾ ਅਕਲ ਕਲਾ ਭਰਪੂਰਿ ਰਹਿਆ ॥","t":"jaat meh jot jot meh jaataa akal kalaa bharapoor rahiaa ||","pa":"ਸਾਰੀ ਸ੍ਰਿਸ਼ਟੀ ਵਿਚ ਤੇਰਾ ਹੀ ਨੂਰ ਵੱਸ ਰਿਹਾ ਹੈ, ਸਾਰੇ ਜੀਵਾਂ ਵਿਚ ਤੇਰਾ ਹੀ ਪ੍ਰਕਾਸ਼ ਹੈ, ਤੂੰ ਸਭ ਥਾਈਂ ਇਕ-ਰਸ ਵਿਆਪਕ ਹੈਂ ।","hi":"सारी सृष्टि में तेरा ही नूर बस रहा है।सारे जीवों में तेरा ही प्रकाश है।तू सब जगह एक-रस व्यापक है।","en":"Your Light is in Your creatures, and Your creatures are in Your Light; Your almighty power is pervading everywhere."},{"g":"ਤੂੰ ਸਚਾ ਸਾਹਿਬੁ ਸਿਫਤਿ ਸੁਆਲਿੑਉ ਜਿਨਿ ਕੀਤੀ ਸੋ ਪਾਰਿ ਪਇਆ ॥","t":"too(n) sachaa saahib sifat suaali(h)au jin keetee so paar piaa ||","pa":"ਹੇ ਪ੍ਰਭੂ! ਤੂੰ ਸਦਾ-ਥਿਰ ਰਹਿਣ ਵਾਲਾ ਹੈਂ, ਤੇਰੀਆਂ ਸੋਹਣੀਆਂ ਵਡਿਆਈਆਂ ਹਨ । ਜਿਸ ਜਿਸ ਨੇ ਤੇਰੇ ਗੁਣ ਗਾਏ ਹਨ, ਉਹ ਸੰਸਾਰ-ਸਮੰੁਦਰ ਤੋਂ ਤਰ ਗਿਆ ਹੈ ।","hi":"हे प्रभू ! तू सदा-स्थिर रहने वाला है।तेरी सुंदर सोहानी महानताएं हैं।जिस जिस ने तेरे गुण गाए हैं।वह संसार समुंदर से पार हो गया है।","en":"You are the True Lord and Master; Your Praise is so beautiful. One who sings it, is carried across."},{"g":"ਕਹੁ ਨਾਨਕ ਕਰਤੇ ਕੀਆ ਬਾਤਾ ਜੋ ਕਿਛੁ ਕਰਣਾ ਸੁ ਕਰਿ ਰਹਿਆ ॥੨॥","t":"kahu naanak karate keeaa baataa jo kichh karanaa su kar rahiaa ||2||","pa":"ਹੇ ਨਾਨਕ! (ਤੂੰ ਭੀ) ਕਰਤਾਰ ਦੀ ਸਿਫ਼ਤਿ-ਸਾਲਾਹ ਕਰ, (ਤੇ ਆਖ ਕਿ) ਪ੍ਰਭੂ ਜੋ ਕੁਝ ਕਰਨਾ ਚੰਗਾ ਸਮਝਦਾ ਹੈ ਉਹ ਕਰ ਰਿਹਾ ਹੈ (ਭਾਵ, ਉਸ ਦੇ ਕੰਮਾਂ ਵਿਚ ਕਿਸੇ ਦਾ ਦਖ਼ਲ ਨਹੀਂ ਹੈ) ।੧।","hi":"हे नानक ! (तू भी) करतार की सिफत सालाह कर।(और कह कि) प्रभू जो कुछ करना ठीक समझता है वही वह कर रहा है (भाव।उसके कामों में किसी का दख़ल नहीं है)। 1।","en":"Nanak speaks the stories of the Creator Lord; whatever He is to do, He does. ||2||"}],"audioUrl":null,"youtube":null},{"id":"shabad-9470","type":"Shabad","title":"Mitr piaare noo(n) haal mureedhaa(n) dhaa kahanaa ","gurmukhiTitle":"ਮਿਤ੍ਰ ਪਿਆਰੇ ਨੂੰ ਹਾਲੁ ਮੁਰੀਦਾਂ ਦਾ ਕਹਣਾ","author":"Guru Gobind Singh Ji","raag":"","ang":711,"source":"Dasam Bani","nitnem":false,"lines":[{"g":"ਖਿਆਲ ਪਾਤਿਸਾਹੀ ੧੦ ॥","t":"khiaal paatisaahee 10 ||","pa":"ਖਿਆਲ ਪਾਤਿਸ਼ਾਹੀ ੧੦:","hi":"","en":"KHYAL OF THE TENTH KING"},{"g":"ਮਿਤ੍ਰ ਪਿਆਰੇ ਨੂੰ ਹਾਲੁ ਮੁਰੀਦਾਂ ਦਾ ਕਹਣਾ ॥","t":"mitr piaare noo(n) haal mureedhaa(n) dhaa kahanaa ||","pa":"ਪਿਆਰੇ ਮਿਤਰ (ਪ੍ਰਭੂ) ਨੂੰ (ਅਸਾ) ਮੁਰੀਦਾ ਦਾ ਹਾਲ (ਜਾ ਕੇ) ਕਹਿਣਾ।","hi":"","en":"Convey to the dear friend the condition of the disciples,"},{"g":"ਤੁਧ ਬਿਨੁ ਰੋਗੁ ਰਜਾਈਆਂ ਦਾ ਓਢਣੁ ਨਾਗ ਨਿਵਾਸਾਂ ਦੇ ਰਹਣਾ ॥","t":"tudh bin rog rajaieeaa(n) dhaa oddan naag nivaasaa(n) dhe rahanaa ||","pa":"ਤੇਰੇ ਬਿਨਾ ਰਜ਼ਾਈਆਂ ਦਾ ਓੜਨਾ ਰੋਗ ਦੇ ਸਮਾਨ ਹੈ ਅਤੇ ਨਿਵਾਸ ਸਥਾਨਾ ਵਿਚ ਰਹਿਣਾ ਨਾਗਾ ਵਿਚ (ਰਹਿਣਾ ਹੈ)।","hi":"","en":"Without Thee, the taking over of quilt is like disease and living in the house is like living with serpents"},{"g":"ਸੂਲ ਸੁਰਾਹੀ ਖੰਜਰੁ ਪਿਯਾਲਾ ਬਿੰਗ ਕਸਾਈਯਾਂ ਦਾ ਸਹਣਾ ॥","t":"sool suraahee kha(n)jar piyaalaa bi(n)g kasaieeyaa(n) dhaa sahanaa ||","pa":"(ਤੁਹਾਡੇ ਬਿਨਾ) ਸੁਰਾਹੀ ਸੂਲ ਵਰਗੀ, ਪਿਆਲਾ ਖ਼ੰਜਰ ਦੇ ਸਮਾਨ ਅਤੇ (ਵਿਯੋਗ) ਕਸਾਈਆਂ ਦੇ ਵਿੰਗੇ ਛੁਰੇ (ਦੀ ਸਟ ਨੂੰ) ਸਹਿਨ ਕਰਨ ਦੇ ਸਮਾਨ ਹਨ।","hi":"","en":"The flask is like the spike, the cup is like a dagger and (the separation) is like enduring the chopper of the butchers,"},{"g":"ਯਾਰੜੇ ਦਾ ਸਾਨੂੰ ਸੱਥਰ ਚੰਗਾ ਭੱਠ ਖੇੜਿਆਂ ਦਾ ਰਹਣਾ ॥੧॥੧॥੬॥","t":"yaaraRe dhaa saanoo(n) sa'thar cha(n)gaa bha'Th kheRiaa(n) dhaa rahanaa ||1||1||6||","pa":"ਯਾਰ (ਮਿਤਰ) ਦਾ ਦਿੱਤਾ ਹੋਇਆ ਸਥਰ (ਭੂਮੀ-ਆਸਨ) ਸਾਨੂੰ ਚੰਗਾ ਹੈ, (ਪਰ ਉਸ ਤੋਂ ਵਿਛੁੜ ਕੇ ਸੁਖ ਪੂਰਵਕ) ਪਿੰਡ ਵਿਚ ਸੌਣਾ ਭਠ ਵਿਚ ਰਹਿਣ ਵਰਗਾ ਹੈ ॥੧॥੧॥੬॥","hi":"","en":"The pallet of the beloved Friend is most pleasing and the worldly pleasures are like furnace.1.1"}],"audioUrl":null,"youtube":null},{"id":"shabad-7671","type":"Shabad","title":"Dheh sivaa bar moh ihai subh karaman te kabahoo(n) na Taro ","gurmukhiTitle":"ਦੇਹ ਸਿਵਾ ਬਰੁ ਮੋਹਿ ਇਹੈ ਸੁਭ ਕਰਮਨ ਤੇ ਕਬਹੂੰ ਨ ਟਰੋ","author":"Guru Gobind Singh Ji","raag":"","ang":100,"source":"Dasam Bani","nitnem":false,"lines":[{"g":"ਸ੍ਵੈਯਾ ॥","t":"savaiyaa ||","pa":"ਸ੍ਵੈਯਾ:","hi":"","en":"SWAYYA"},{"g":"ਦੇਹ ਸਿਵਾ ਬਰੁ ਮੋਹਿ ਇਹੈ ਸੁਭ ਕਰਮਨ ਤੇ ਕਬਹੂੰ ਨ ਟਰੋ ॥","t":"dheh sivaa bar moh ihai subh karaman te kabahoo(n) na Taro ||","pa":"ਹੇ ਸ਼ਿਵਾ! ਮੈਨੂੰ ਇਹ ਵਰ ਦੇ ਕਿ (ਮੈਂ) ਸ਼ੁਭ ਕੰਮਾ (ਨੂੰ ਕਰਨੋਂ) ਨਾ ਟਲਾ।","hi":"","en":"O Goddess, grant me this that I may not hesitate from performing good actions."},{"g":"ਨ ਡਰੋ ਅਰਿ ਸੋ ਜਬ ਜਾਇ ਲਰੋ ਨਿਸਚੈ ਕਰਿ ਅਪੁਨੀ ਜੀਤ ਕਰੋ ॥","t":"n ddaro ar so jab jai laro nisachai kar apunee jeet karo ||","pa":"ਜਦੋਂ ਵੈਰੀ ਨਾਲ (ਰਣ-ਭੂਮੀ ਵਿਚ ਜਾ ਕੇ) ਲੜਾ ਤਾ (ਜ਼ਰਾ) ਨਾ ਡਰਾ ਅਤੇ ਨਿਸ਼ਚੇ ਹੀ ਆਪਣੀ ਜਿਤ ਪ੍ਰਾਪਤ ਕਰਾ।","hi":"","en":"I may not fear the enemy, when I go to fight and assuredly I may become victorious."},{"g":"ਅਰੁ ਸਿਖ ਹੌ ਆਪਨੇ ਹੀ ਮਨ ਕੋ ਇਹ ਲਾਲਚ ਹਉ ਗੁਨ ਤਉ ਉਚਰੋ ॥","t":"ar sikh hau aapane hee man ko ieh laalach hau gun tau ucharo ||","pa":"ਅਤੇ ਆਪਣੇ ਮਨ ਨੂੰ ਸਿਖਿਆ ਦੇਵਾ ਕਿ ਮੈਨੂੰ (ਸਦਾ) ਇਹ ਲਾਲਚ (ਬਣਿਆ ਰਹੇ ਕਿ ਮੈਂ) ਤੇਰੇ ਗੁਣਾ ਨੂੰ ਉਚਾਰਦਾ ਰਹਾ।","hi":"","en":"And I may give this instruction to my mind and have this tempotration that I may ever utter Thy Praises."},{"g":"ਜਬ ਆਵ ਕੀ ਅਉਧ ਨਿਦਾਨ ਬਨੈ ਅਤਿ ਹੀ ਰਨ ਮੈ ਤਬ ਜੂਝ ਮਰੋ ॥੨੩੧॥","t":"jab aav kee aaudh nidhaan banai at hee ran mai tab joojh maro ||231||","pa":"ਅਤੇ ਜਦੋਂ ਉਮਰ ਦਾ ਅੰਤਿਮ ਸਮਾ ਆ ਜਾਏ ਤਾ ਅਤਿ ਦੇ ਯੁੱਧ ਵਿਚ ਲੜਦਾ ਹੋਇਆ ਮਰ ਜਾਵਾ ॥੨੩੧॥","hi":"","en":"That when the end of my life comes, I may die fighting in the battlefield.231."},{"g":"ਚੰਡਿ ਚਰਿਤ੍ਰ ਕਵਿਤਨ ਮੈ ਬਰਨਿਓ ਸਭ ਹੀ ਰਸ ਰੁਦ੍ਰਮਈ ਹੈ ॥","t":"cha(n)dd charitr kavitan mai baranio sabh hee ras rudhramiee hai ||","pa":"ਚੰਡੀ-ਚਰਿਤ੍ਰ ਕਵਿਤਾ ਵਿਚ ਕਥਨ ਕੀਤਾ ਹੈ। (ਇਹ) ਸਾਰੀ (ਕਵਿਤਾ) ਰੌਦਰਰਸ ਵਿਚ ਲਿਖੀ ਹੈ।","hi":"","en":"I have narrated this Chandi Charitra in poetry, which is all full of Rudra Rasa (sentiment of ragge)."},{"g":"ਏਕ ਤੇ ਏਕ ਰਸਾਲ ਭਇਓ ਨਖ ਤੇ ਸਿਖ ਲਉ ਉਪਮਾ ਸੁ ਨਈ ਹੈ ॥","t":"ek te ek rasaal bhio nakh te sikh lau upamaa su niee hai ||","pa":"ਇਕ ਤੋਂ ਇਕ (ਉਕਤੀ) ਰਸ ਭਰਪੂਰ ਹੈ ਅਤੇ ਆਦਿ ਤੋਂ ਅੰਤ ਤਕ (ਪੈਰਾ ਦੇ ਨਹੁੰਆਂ ਤੋਂ ਸਿਰ ਦੀ ਚੋਟੀ ਤਕ) ਹਰ ਉਪਮਾ ਨਵੀਂ ਹੈ।","hi":"","en":"The stanzas one and all, are beautifully composed, which contain new sillies from beginning to end."},{"g":"ਕਉਤਕ ਹੇਤੁ ਕਰੀ ਕਵਿ ਨੇ ਸਤਿਸਯ ਕੀ ਕਥਾ ਇਹ ਪੂਰੀ ਭਈ ਹੈ ॥","t":"kautak het karee kav ne satisay kee kathaa ieh pooree bhiee hai ||","pa":"ਕਵੀ ਨੇ ਮਾਨਸਿਕ ਵਿਲਾਸ ('ਕਉਤਕ') ਲਈ ਇਕ ਕਾਵਿ-ਰਚਨਾ ਕੀਤੀ ਹੈ। 'ਸਤਸਈ' ਦੀ ਇਹ ਪੂਰੀ ਕਥਾ ਵਰਣਿਤ ਹੈ।","hi":"","en":"The poet has composed it for the pleasure of his mind, and the discourse of seven hundred Saloks is completed here."},{"g":"ਜਾਹਿ ਨਮਿਤ ਪੜੈ ਸੁਨਿ ਹੈ ਨਰ ਸੋ ਨਿਸਚੈ ਕਰਿ ਤਾਹਿ ਦਈ ਹੈ ॥੨੩੨॥","t":"jaeh namit paRai sun hai nar so nisachai kar taeh dhiee hai ||232||","pa":"ਜਿਸ (ਮਨੋਰਥ) ਲਈ (ਕੋਈ) ਪੁਰਸ਼ (ਇਸ ਰਚਨਾ ਨੂੰ) ਪੜ੍ਹੇ ਅਤੇ ਸੁਣੇਗਾ, ਉਸ ਨੂੰ ਅੱਵਸ਼ ਹੀ (ਦੇਵੀ) ਉਹੀ (ਵਰ) ਪ੍ਰਦਾਨ ਕਰੇਗੀ ॥੨੩੨॥","hi":"","en":"For whatever purpose a person ready it or listens to it, the hgoddess will assuredly grant him that.232."}],"audioUrl":null,"youtube":null}]};


export const gurbani = window.SikhifyData.gurbani;
